plugins.payload:
// Miruro: one catalog API in front of several upstream sites. An anime is found by its AniList
// (or MyAnimeList) id; successful answers are gzip-compressed JSON XOR-ed with a fixed key, so
// this plugin needs the binary helpers of the Anix runtime (`$anilili`).

class Provider {
  constructor() {
    this.mirrors = [
      "https://www.miruro.bz",
      "https://www.miruro.ru",
      "https://www.miruro.to",
      "https://www.miruro.tv",
    ];
    this.catalogKey = "miruro/catalog";
    // Upstream sites the API has been seen to answer with, in the order they are preferred.
    this.upstreams = ["kickassanime", "anikoto", "aniwaves", "icarus", "animepahe"];
    this.mirrorStaggerMs = 400;
    this.requestBudgetMs = 9000;
    this.maxAttempts = 3;
    this.maxPages = 20;
    this.maxGroupsChecked = 8;
    this.streamCheckMs = 7000;
    this.lastGood = -1;
  }

  getSettings() {
    return {
      episodeServers: this.upstreams.slice(),
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    this._requireHost();
    const media = (opts && opts.media) || {};
    const anilistId = Number(media.id);
    if (!(anilistId > 0)) {
      throw new Error("the AniList id of the anime is needed (opts.media.id)");
    }

    let anime = await this._lookup("anilist", anilistId);
    const malId = Number(media.idMal);
    if (!anime && malId > 0) anime = await this._lookup("mal", malId);
    if (!anime) return [];

    const dub = Boolean(opts.dub);
    const counts = anime.episode_counts || {};
    const count = this._count(dub ? counts.dub : counts.sub);
    // The site says how far each audio version goes; zero dubbed episodes means no dub.
    if (dub && !(count > 0)) return [];

    const titles = anime.title || {};
    const title =
      this._text(titles.english) || this._text(titles.romaji) || this._text(titles.native) ||
      this._text(media.englishTitle) || this._text(media.romajiTitle) || this._text(opts.query) || "Miruro";
    const audio = dub ? "dub" : "sub";
    return [
      {
        id: anime.id + "/" + audio + "/" + (count === null ? "" : count),
        title: title,
        url: this._mirror() + "/",
        subOrDub: audio,
        year: typeof anime.season_year === "number" ? anime.season_year : undefined,
      },
    ];
  }

  async findEpisodes(id) {
    this._requireHost();
    const parts = String(id).split("/");
    const animeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    const limit = parts[2] ? Number(parts[2]) : null;
    if (!this._isAnimeId(animeId)) throw new Error("invalid anime id '" + id + "'");

    let items;
    try {
      items = await this._list("/api/v1/anime/" + animeId + "/episodes?limit=10000");
    } catch (error) {
      if (error.problem && error.problem.status === 404) throw new Error("anime not on Miruro");
      throw error;
    }

    const seen = {};
    const episodes = [];
    for (const item of items) {
      // Specials are numbered from 20000 by the site and are not part of the regular list.
      if (!item || item.kind !== "regular") continue;
      const number = this._number(item.episode_number);
      if (number === null || number < 0) continue;
      // An episode that is listed but not out yet in this audio version is not offered.
      if (limit !== null && isFinite(limit) && number > limit) continue;
      const key = String(number);
      if (seen[key]) continue;
      seen[key] = true;

      const thumbnail = this._text(item.thumbnail_url);
      episodes.push({
        id: animeId + "/" + audio + "/" + key + "/" + this._skipPart(item.skip_times),
        number: number,
        url: this._mirror() + "/",
        title: this._text(item.title) || "Episode " + key,
        image: thumbnail && this._isHttpUrl(thumbnail) ? thumbnail : undefined,
        synopsis: this._text(item.synopsis) || undefined,
      });
    }
    episodes.sort(function (a, b) {
      return a.number - b.number;
    });
    if (episodes.length === 0) throw new Error(audio === "dub" ? "no dub" : "no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    this._requireHost();
    const parts = String((episode && episode.id) || "").split("/");
    const animeId = parts[0];
    const audio = parts[1];
    const number = parts[2];
    if (!this._isAnimeId(animeId) || (audio !== "sub" && audio !== "dub") || !/^\d+(\.\d+)?$/.test(number || "")) {
      throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    }

    let play;
    try {
      play = await this._request("/api/v1/anime/" + animeId + "/episodes/" + number + "/play");
    } catch (error) {
      if (error.problem && error.problem.status === 404) {
        const about = String(error.problem.title || "").toLowerCase();
        throw new Error(about.indexOf("episode") >= 0 ? "episode " + number + " not listed" : "anime not on Miruro");
      }
      throw error;
    }

    let groups = this._sourceGroups(play, audio);
    if (groups.length === 0) throw new Error(audio === "dub" ? "no dub" : "no playable source for this episode");

    const wanted = String(server || "default");
    if (wanted !== "default") {
      const offered = this._distinct(groups.map(function (g) { return g.upstream; }));
      groups = groups.filter(function (g) { return g.upstream.toLowerCase() === wanted.toLowerCase(); });
      if (groups.length === 0) {
        throw new Error("'" + wanted + "' has no stream for this episode (offered: " + offered.join(", ") + ")");
      }
    }

    const chosen = await this._firstPlayable(groups);
    const result = {
      server: chosen.upstream,
      headers: chosen.headers,
      videoSources: chosen.sources,
    };
    const skip = this._parseSkipPart(parts[3] || "");
    if (skip) result.skip = skip;
    return result;
  }

  // ---------------------------------------------------------------- sources

  // One group per upstream site, track and header set, in the order they are to be tried: for
  // sub the soft-subtitle track ("ssub") before the hard-subbed one ("sub"); for dub the dub
  // track. Servers that only offer an embed page have no streams and are left out.
  _sourceGroups(play, audio) {
    const tracks = play && Array.isArray(play.tracks) ? play.tracks : null;
    if (!tracks) throw new Error("the play answer has no track list");
    const kinds = audio === "dub" ? ["dub"] : ["ssub", "sub"];
    const groups = [];

    for (const kind of kinds) {
      for (const track of tracks) {
        if (!track || track.track !== kind) continue;
        const providers = Array.isArray(track.providers) ? track.providers : [];
        for (const provider of providers) {
          if (!provider) continue;
          const upstream = this._text(provider.provider) || "unknown";
          // A hard-subbed video needs no subtitle file.
          const subtitles = kind === "sub" ? [] : this._subtitles(provider.subtitles);
          const variant =
            kind === "ssub" ? "Soft sub" : kind === "sub" ? "Hard sub" : subtitles.length > 0 ? "Dub + subtitles" : "Dub";

          const servers = Array.isArray(provider.servers) ? provider.servers : [];
          for (const entry of servers) {
            if (!entry) continue;
            const serverName = this._text(entry.server) || "server";
            const headers = {};
            const rawHeaders = entry.headers && typeof entry.headers === "object" ? entry.headers : {};
            for (const name of Object.keys(rawHeaders)) {
              if (name && typeof rawHeaders[name] === "string" && rawHeaders[name]) headers[name] = rawHeaders[name];
            }
            const headerKey = JSON.stringify(Object.keys(headers).sort().map(function (n) { return [n.toLowerCase(), headers[n]]; }));

            const streams = Array.isArray(entry.streams) ? entry.streams : [];
            for (const stream of streams) {
              if (!stream || !this._isHttpUrl(stream.url)) continue;
              const type = stream.format === "hls" ? "m3u8" : stream.format === "mp4" ? "mp4" : null;
              if (!type) continue;
              const quality = this._text(stream.quality) || "auto";

              let group = null;
              for (const existing of groups) {
                if (existing.upstream === upstream && existing.kind === kind && existing.headerKey === headerKey) group = existing;
              }
              if (!group) {
                group = { upstream: upstream, kind: kind, headerKey: headerKey, headers: headers, sources: [] };
                groups.push(group);
              }
              group.sources.push({
                url: stream.url,
                type: type,
                quality: this._uniqueQuality(group.sources, upstream + " · " + serverName + " · " + quality + " · " + variant),
                label: variant,
                subtitles: subtitles,
              });
            }
          }
        }
      }
    }
    return groups;
  }

  _uniqueQuality(sources, wanted) {
    let label = wanted;
    let n = 2;
    while (sources.some(function (s) { return s.quality === label; })) {
      label = wanted + " (" + n + ")";
      n += 1;
    }
    return label;
  }

  // At most one file is the default. Upstream sites often mark whichever file comes first, so
  // an English file wins: the marked one if it is English, else the first English one, and
  // only without any English file whatever the site marked.
  _subtitles(listed) {
    if (!Array.isArray(listed)) return [];
    const self = this;
    const usable = listed.filter(function (entry) { return entry && self._isHttpUrl(entry.file); });
    const isEnglish = function (entry) {
      const code = String(entry.language || "").toLowerCase();
      const label = String(entry.label || "").toLowerCase();
      return code === "en" || code === "eng" || code === "english" || label.indexOf("eng") === 0;
    };
    const marked = function (entry) { return entry.default === true; };
    let chosen = usable.findIndex(function (e) { return marked(e) && isEnglish(e); });
    if (chosen < 0) chosen = usable.findIndex(isEnglish);
    if (chosen < 0) chosen = usable.findIndex(marked);

    return usable.map(function (entry, index) {
      const language = self._text(entry.label) || self._text(entry.language) || "Subtitles";
      return {
        id: (self._text(entry.language) || "sub") + "-" + index,
        url: entry.file,
        language: language,
        isDefault: index === chosen,
        format: self._subtitleFormat(entry.file, entry.format),
      };
    });
  }

  _subtitleFormat(url, declared) {
    const known = ["vtt", "srt", "ass", "ssa"];
    const said = String(declared || "").trim().toLowerCase();
    if (known.indexOf(said) >= 0) return said;
    const path = String(url).split(/[?#]/)[0];
    const ext = path.slice(path.lastIndexOf(".") + 1).toLowerCase();
    return known.indexOf(ext) >= 0 ? ext : "vtt";
  }

  // The first group, in order, with a playlist that can actually be fetched; that stream is put
  // first. The groups are checked at the same time, so the choice costs no more than the
  // slowest check. A group that only has files (mp4) cannot be checked cheaply and is used only
  // when no playlist answered.
  async _firstPlayable(groups) {
    const self = this;
    const candidates = groups.slice(0, this.maxGroupsChecked);
    const outcomes = await Promise.all(
      candidates.map(function (group) {
        return self._withDeadline(self._checkGroup(group), self.streamCheckMs, { ok: false, reason: "timed out" });
      })
    );

    for (let i = 0; i < candidates.length; i += 1) {
      if (outcomes[i].ok) {
        const group = candidates[i];
        const first = group.sources[outcomes[i].index];
        const rest = group.sources.filter(function (s) { return s !== first; });
        return { upstream: group.upstream, headers: group.headers, sources: [first].concat(rest) };
      }
    }
    for (let i = 0; i < candidates.length; i += 1) {
      if (outcomes[i].unchecked) {
        return { upstream: candidates[i].upstream, headers: candidates[i].headers, sources: candidates[i].sources };
      }
    }
    let reason = "no stream";
    for (let i = 0; i < candidates.length; i += 1) {
      if (outcomes[i].reason) {
        reason = candidates[i].upstream + ": " + outcomes[i].reason;
        break;
      }
    }
    throw new Error("stream check failed (" + reason + ")");
  }

  async _checkGroup(group) {
    let reason = null;
    let playlists = 0;
    for (let index = 0; index < group.sources.length && playlists < 3; index += 1) {
      const source = group.sources[index];
      if (source.type !== "m3u8") continue;
      playlists += 1;
      try {
        const response = await fetch(source.url, { headers: group.headers });
        if (!response.ok) {
          reason = reason || "HTTP " + response.status + " from " + this._host(source.url);
          continue;
        }
        const body = String(await response.text());
        if (body.indexOf("#EXTM3U") >= 0) return { ok: true, index: index };
        reason = reason || this._host(source.url) + " did not answer with a playlist";
      } catch (error) {
        reason = reason || this._host(source.url) + " unreachable";
      }
    }
    if (playlists === 0) return { ok: false, unchecked: true };
    return { ok: false, reason: reason || "no stream" };
  }

  _withDeadline(promise, ms, fallback) {
    return new Promise(function (resolve) {
      let settled = false;
      const timer = setTimeout(function () {
        if (!settled) {
          settled = true;
          resolve(fallback);
        }
      }, ms);
      promise.then(
        function (value) {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve(value);
        },
        function () {
          if (settled) return;
          settled = true;
          clearTimeout(timer);
          resolve(fallback);
        }
      );
    });
  }

  // ---------------------------------------------------------------- skip times

  // Intro and outro from an episode's `skip_times`: `op` (else `mixed_op`) is the intro, `ed`
  // (else `mixed_ed`) the outro; recaps and other kinds are not skipped. They travel in the
  // episode id as `i{start}-{end}` and/or `o{start}-{end}`.
  _skipPart(entries) {
    const self = this;
    const window = function (kinds) {
      if (!Array.isArray(entries)) return null;
      for (const kind of kinds) {
        for (const entry of entries) {
          if (!entry || entry.kind !== kind) continue;
          const start = self._number(entry.start_seconds);
          const end = self._number(entry.end_seconds);
          if (start !== null && end !== null && start >= 0 && end > start) return start + "-" + end;
        }
      }
      return null;
    };
    const intro = window(["op", "mixed_op"]);
    const outro = window(["ed", "mixed_ed"]);
    const parts = [];
    if (intro) parts.push("i" + intro);
    if (outro) parts.push("o" + outro);
    return parts.join(",");
  }

  _parseSkipPart(part) {
    if (!part) return null;
    const skip = {};
    for (const window of part.split(",")) {
      const match = /^([io])(\d+(?:\.\d+)?)-(\d+(?:\.\d+)?)$/.exec(window);
      if (!match) continue;
      const start = Number(match[2]);
      const end = Number(match[3]);
      if (!(end > start)) continue;
      if (match[1] === "i") {
        skip.introStart = start;
        skip.introEnd = end;
      } else {
        skip.outroStart = start;
        skip.outroEnd = end;
      }
    }
    return Object.keys(skip).length > 0 ? skip : null;
  }

  // ---------------------------------------------------------------- catalog API

  // Picks the anime a lookup answer has for the given external id. Like the site's own client,
  // an id counts as found only when exactly one anime lists it.
  async _lookup(kind, id) {
    let items;
    try {
      items = await this._list("/api/v1/anime?" + kind + "_id_in=" + id + "&limit=100");
    } catch (error) {
      if (error.problem) throw new Error("request rejected (" + this._problemText(error.problem) + ")");
      throw error;
    }
    const wanted = String(id);
    const matches = [];
    for (const item of items) {
      const listed = item && item.external_ids && item.external_ids[kind];
      if (!Array.isArray(listed)) continue;
      if (!listed.some(function (value) { return String(value).trim() === wanted; })) continue;
      if (!this._isAnimeId(item.id)) continue;
      if (!matches.some(function (m) { return m.id === item.id; })) matches.push(item);
    }
    return matches.length === 1 ? matches[0] : null;
  }

  // Every item of a list endpoint, following its cursor as far as it goes.
  async _list(path) {
    const items = [];
    const cursors = [];
    for (;;) {
      const pagePath = cursors.length > 0 ? path + "&cursor=" + encodeURIComponent(cursors[cursors.length - 1]) : path;
      const page = await this._request(pagePath);
      if (!page || !Array.isArray(page.data)) throw new Error("the answer has no item list");
      for (const item of page.data) items.push(item);
      const next = this._text(page.next_cursor);
      if (page.has_more === true && next && cursors.indexOf(next) < 0 && cursors.length + 1 < this.maxPages) {
        cursors.push(next);
      } else {
        return items;
      }
    }
  }

  // One API request: the mirrors are raced, and when all of them fail for a passing reason (a
  // 502/503/504 or no connection) the race is run again after a pause, within a time budget.
  // An error answer of the API itself is thrown with `problem` set.
  async _request(path) {
    const deadline = Date.now() + this.requestBudgetMs;
    const pauses = [300, 800];
    for (let attempt = 1; ; attempt += 1) {
      const outcome = await this._race(path, deadline);
      if (outcome.answer) {
        if (outcome.answer.problem) {
          const error = new Error("request rejected (" + this._problemText(outcome.answer.problem) + ")");
          error.problem = outcome.answer.problem;
          throw error;
        }
        return outcome.answer.data;
      }

      const failures = outcome.failures;
      const limited = failures.filter(function (f) { return f.rateLimited; })[0];
      if (limited) throw new Error(limited.message);
      const allPassing = failures.length === this.mirrors.length && failures.every(function (f) { return f.passing; });
      const pause = pauses[Math.min(attempt - 1, pauses.length - 1)];
      if (allPassing && attempt < this.maxAttempts && Date.now() + pause < deadline) {
        await this._sleep(pause);
        continue;
      }
      throw new Error(this._summarize(failures));
    }
  }

  // The most telling reason among the mirrors: a block by the site's bot protection, then an
  // answer naming the mirror that gave it; a connection failure only when no mirror answered.
  _summarize(failures) {
    const blocked = failures.filter(function (f) { return f.blocked; })[0];
    if (blocked) return blocked.message;
    const answered = failures.filter(function (f) { return !f.passing || f.status; })[0];
    if (answered) return answered.message;
    return failures.length > 0 ? "no Miruro mirror reachable (" + failures[0].message + ")" : "no Miruro mirror answered in time";
  }

  // Each further mirror joins the race a little after the previous one, so a healthy first
  // mirror answers before the others are asked at all. The mirror that answered last starts.
  _race(path, deadline) {
    const self = this;
    const order = [];
    for (let i = 0; i < this.mirrors.length; i += 1) order.push(i);
    if (this.lastGood > 0) {
      order.splice(order.indexOf(this.lastGood), 1);
      order.unshift(this.lastGood);
    }

    return new Promise(function (resolve) {
      const failures = [];
      const timers = [];
      let settled = false;
      const finish = function (outcome) {
        if (settled) return;
        settled = true;
        timers.forEach(function (t) { clearTimeout(t); });
        resolve(outcome);
      };

      timers.push(setTimeout(function () { finish({ failures: failures }); }, Math.max(0, deadline - Date.now())));
      order.forEach(function (index, slot) {
        timers.push(
          setTimeout(function () {
            if (settled) return;
            self._ask(index, path).then(
              function (answer) {
                self.lastGood = index;
                finish({ answer: answer });
              },
              function (failure) {
                failures.push(failure);
                // The mirrors share one backend: being told to slow down holds for all.
                if (failure.rateLimited || failures.length === order.length) finish({ failures: failures });
              }
            );
          }, slot * self.mirrorStaggerMs)
        );
      });
    });
  }

  // Asks one mirror. Resolves with `{ data }` or `{ problem }`; rejects with a failure object
  // `{ message, passing, rateLimited, blocked, status }`.
  async _ask(index, path) {
    const mirror = this.mirrors[index];
    const host = this._host(mirror).replace(/^www\./, "");
    let response;
    try {
      response = await $anilili.fetchBytes(mirror + path, {
        headers: { Referer: mirror + "/", Accept: "*/*" },
      });
    } catch (error) {
      throw { message: host + ": " + this._errorText(error), passing: true };
    }
    if (!response || typeof response.status !== "number") throw { message: host + ": no answer", passing: true };

    const status = response.status;
    const base64 = typeof response.base64 === "string" ? response.base64 : "";
    if (response.url && !this._sameSite(this._host(response.url), host)) {
      throw { message: host + " redirected to " + this._host(response.url), passing: false, status: status };
    }
    if (status === 429) {
      throw { message: "rate limited by Miruro, try again shortly", passing: false, rateLimited: true, status: status };
    }

    if (status >= 200 && status < 300) {
      try {
        return { data: this._decode(base64) };
      } catch (error) {
        throw { message: host + ": " + this._errorText(error), passing: false, status: status };
      }
    }

    const body = this._base64Text(base64);
    const mitigated = this._header(response.headers, "cf-mitigated");
    if (mitigated || ((status === 403 || status === 503) && this._looksLikeChallenge(body))) {
      throw { message: "blocked by the site's bot protection", passing: false, blocked: true, status: status };
    }
    if (status === 502 || status === 503 || status === 504) {
      throw { message: "HTTP " + status + " from " + host, passing: true, status: status };
    }
    // Only what the API itself says counts as its answer; any other error page is the mirror's.
    const contentType = String(this._header(response.headers, "content-type") || "").toLowerCase();
    if (status >= 400 && status < 500 && contentType.indexOf("json") >= 0) {
      const problem = this._problem(status, body);
      if (problem) return { problem: problem };
    }
    throw { message: "HTTP " + status + " from " + host, passing: false, status: status };
  }

  // A successful answer: XOR with the catalog key, gunzip, parse. A body that already is JSON
  // text is parsed as it is.
  _decode(base64) {
    const head = this._binary(base64.slice(0, 16)).replace(/^\s+/, "");
    if (head.charAt(0) === "{" || head.charAt(0) === "[") return JSON.parse(this._base64Text(base64));

    const plain = $anilili.xor(base64, this.catalogKey);
    const magic = this._binary(String(plain).slice(0, 4));
    if (magic.charCodeAt(0) !== 0x1f || magic.charCodeAt(1) !== 0x8b) {
      throw new Error("the answer is not in the catalog encoding");
    }
    let text;
    try {
      text = $anilili.gunzip(plain);
    } catch (error) {
      throw new Error("the answer does not decompress");
    }
    return JSON.parse(text);
  }

  _problem(status, body) {
    let value;
    try {
      value = JSON.parse(body);
    } catch (error) {
      return null;
    }
    if (!value || typeof value !== "object" || Array.isArray(value)) return null;
    const title = this._text(value.title);
    const detail = this._text(value.detail);
    if (!title && !detail) return null;
    return { status: status, title: title || "HTTP " + status, detail: detail };
  }

  _problemText(problem) {
    return problem.detail || problem.title;
  }

  // ---------------------------------------------------------------- small helpers

  _requireHost() {
    if (
      typeof $anilili === "undefined" || !$anilili ||
      typeof $anilili.fetchBytes !== "function" ||
      typeof $anilili.xor !== "function" ||
      typeof $anilili.gunzip !== "function"
    ) {
      throw new Error("requires Anix (this plugin needs the $anilili helpers to decode Miruro's answers)");
    }
  }

  _mirror() {
    return this.mirrors[this.lastGood >= 0 ? this.lastGood : 0];
  }

  _isAnimeId(id) {
    return typeof id === "string" && /^[A-Za-z0-9_-]{32}$/.test(id);
  }

  _isHttpUrl(url) {
    return typeof url === "string" && /^https?:\/\/[^\s\/]+/i.test(url);
  }

  _text(value) {
    if (typeof value !== "string") return null;
    const trimmed = value.trim();
    return trimmed ? trimmed : null;
  }

  _number(value) {
    const number = typeof value === "number" ? value : typeof value === "string" && value.trim() ? Number(value) : NaN;
    return isFinite(number) ? number : null;
  }

  _count(value) {
    const number = this._number(value);
    return number === null || number < 0 ? null : Math.floor(number);
  }

  _distinct(values) {
    return values.filter(function (value, index) { return values.indexOf(value) === index; });
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _header(headers, name) {
    if (!headers) return null;
    if (typeof headers.get === "function") {
      const value = headers.get(name);
      if (value !== undefined && value !== null) return String(value);
    }
    const wanted = name.toLowerCase();
    for (const key of Object.keys(headers)) {
      if (key.toLowerCase() === wanted) return String(headers[key]);
    }
    return null;
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  _sleep(ms) {
    return new Promise(function (resolve) { setTimeout(resolve, ms); });
  }

  // Base64 to a string of one character per byte.
  _binary(base64) {
    try {
      return atob(base64);
    } catch (error) {
      return "";
    }
  }

  _base64Text(base64) {
    const binary = this._binary(base64);
    if (typeof TextDecoder !== "undefined" && typeof Uint8Array !== "undefined") {
      const bytes = new Uint8Array(binary.length);
      for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
      return new TextDecoder().decode(bytes);
    }
    try {
      return decodeURIComponent(escape(binary));
    } catch (error) {
      return binary;
    }
  }
}

// AniZone (anizone.to): original audio with soft subtitles. Search results and the player
// configuration are embedded in the pages as `JSON.parse('...')` literals.

class Provider {
  constructor() {
    this.base = "https://anizone.to";
    this.maxListedEpisodes = 5000;
    // The key of English titles in the site's per-language title maps.
    this.englishKey = "1";
  }

  getSettings() {
    return {
      episodeServers: ["AniZone"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/anime?search=" + encodeURIComponent(query));
      const items = this._literalAfter(html, "items:");
      if (!Array.isArray(items)) {
        if (results.length === 0 && html.indexOf("items:") < 0) throw new Error("the search page has changed (no result list)");
        continue;
      }
      for (const item of items) {
        if (!item || typeof item.slug !== "string" || !item.slug) continue;
        if (results.some(function (r) { return r.slug === item.slug; })) continue;
        const titles = [];
        if (typeof item.main_title === "string" && item.main_title) titles.push(item.main_title);
        const list = item.title_list && typeof item.title_list === "object" ? item.title_list : {};
        for (const key of Object.keys(list)) {
          if (typeof list[key] === "string" && list[key] && titles.indexOf(list[key]) < 0) titles.push(list[key]);
        }
        if (titles.length === 0) continue;
        const count = typeof item.episode_count === "number" && item.episode_count > 0 ? Math.floor(item.episode_count) : 0;
        results.push({
          slug: item.slug,
          id: item.slug + "/" + count,
          title: titles[0],
          url: this.base + "/anime/" + encodeURIComponent(item.slug),
          subOrDub: "sub",
          altTitles: titles.slice(1),
          year: typeof item.start_year === "number" ? item.start_year : undefined,
          episodeCount: count || undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results.map(function (r) {
      delete r.slug;
      return r;
    });
  }

  async findEpisodes(id) {
    const parts = String(id).split("/");
    const slug = parts[0];
    const count = Math.min(Math.max(parseInt(parts[1], 10) || 0, 0), this.maxListedEpisodes);
    if (!slug) throw new Error("invalid anime id '" + id + "'");

    // Every episode page carries the whole episode list with titles; the first one is asked.
    // When that fails the list is numbered from the episode count the search gave.
    let episodes = [];
    try {
      const html = await this._page(this._episodeUrl(slug, "1"));
      episodes = this._episodeList(html, slug);
    } catch (error) {
      if (count === 0) throw error;
    }
    if (episodes.length === 0) {
      for (let n = 1; n <= count; n += 1) {
        episodes.push({ id: slug + "/" + n, number: n, url: this._episodeUrl(slug, String(n)), title: "Episode " + n });
      }
    }
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("/");
    const slug = parts[0];
    const number = parts[1];
    if (!slug || !number) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "anizone") throw new Error("unknown server '" + wanted + "'");

    let html;
    try {
      html = await this._page(this._episodeUrl(slug, number));
    } catch (error) {
      if (/^not found/.test(error.message)) throw new Error("episode " + number + " not on AniZone");
      throw error;
    }
    const player = this._player(html);
    if (!player) throw new Error("no video on the episode page");

    return {
      server: "AniZone",
      headers: { Referer: this.base + "/" },
      videoSources: [
        {
          url: player.url,
          type: this._isHls(player.url) ? "m3u8" : "mp4",
          quality: "auto",
          label: "Soft sub",
          subtitles: player.subtitles,
        },
      ],
    };
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _episodeUrl(slug, number) {
    return this.base + "/anime/" + encodeURIComponent(slug) + "/" + encodeURIComponent(number);
  }

  // Episode links of the list on an episode page, each preceded by its titles per language.
  _episodeList(html, slug) {
    const linkRe = new RegExp('href="https?://[^"/]+/anime/' + slug.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") + '/(\\d+(?:\\.\\d+)?)"', "g");
    const episodes = [];
    const seen = {};
    let cursor = 0;
    let match;
    while ((match = linkRe.exec(html)) !== null) {
      const number = Number(match[1]);
      const before = html.slice(cursor, match.index);
      cursor = linkRe.lastIndex;
      if (!isFinite(number) || seen[match[1]]) continue;
      // Only links of the episode list carry a title map right before them.
      const at = before.lastIndexOf("epsTitles:");
      if (at < 0) continue;
      seen[match[1]] = true;
      const titles = this._literalAfter(before.slice(at), "epsTitles:");
      let title = null;
      if (titles && typeof titles === "object") {
        title = typeof titles[this.englishKey] === "string" && titles[this.englishKey].trim() ? titles[this.englishKey].trim() : null;
      }
      episodes.push({
        id: slug + "/" + match[1],
        number: number,
        url: this._episodeUrl(slug, match[1]),
        title: title || "Episode " + match[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    return episodes;
  }

  // The playlist URL and subtitle tracks from an episode page's player configuration.
  _player(html) {
    const config = this._literalAfter(html, "vidstackPlayer(");
    if (config && typeof config.src === "string" && config.src) {
      const self = this;
      const tracks = Array.isArray(config.subtitles) ? config.subtitles : [];
      const subtitles = [];
      tracks.forEach(function (track, index) {
        if (!track || typeof track.file !== "string" || !track.file) return;
        const url = self._fixUrl(track.file);
        subtitles.push({
          id: (typeof track.language === "string" && track.language ? track.language : "sub") + "-" + index,
          url: url,
          language: (typeof track.title === "string" && track.title) || (typeof track.language === "string" && track.language) || "Unknown",
          isDefault: track.default === true,
          format: self._subtitleFormat(url, track.format),
        });
      });
      // Exactly one default: the site's own choice, else full English subtitles, else the first.
      if (subtitles.filter(function (s) { return s.isDefault; }).length !== 1) {
        let chosen = subtitles.findIndex(function (s) { return s.isDefault; });
        if (chosen < 0) chosen = subtitles.findIndex(function (s) { return /^en\b/i.test(s.id) && !/sign|song/i.test(s.language); });
        if (chosen < 0) chosen = subtitles.findIndex(function (s) { return /^en\b/i.test(s.id); });
        subtitles.forEach(function (s, index) { s.isDefault = index === Math.max(chosen, 0); });
      }
      return { url: this._fixUrl(config.src), subtitles: subtitles };
    }
    const playlists = this._mediaUrls(html).filter(this._isHls);
    return playlists.length > 0 ? { url: playlists[0], subtitles: [] } : null;
  }

  // ---------------------------------------------------------------- shared helpers

  async _page(url) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: this.base + "/" } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (response.url && this._host(response.url) !== "unknown host" && !this._sameSite(this._host(response.url), host)) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Finds `JSON.parse('...')` after `marker` and returns the decoded value, or null.
  _literalAfter(body, marker) {
    const start = body.indexOf(marker);
    if (start < 0) return null;
    const opener = "JSON.parse('";
    const open = body.indexOf(opener, start + marker.length);
    if (open < 0) return null;
    let end = -1;
    for (let i = open + opener.length; i < body.length; i += 1) {
      const ch = body.charAt(i);
      if (ch === "\\") i += 1;
      else if (ch === "'") {
        end = i;
        break;
      }
    }
    if (end < 0) return null;
    // The literal usually sits inside an HTML attribute, so entities come first.
    const literal = body.slice(open + opener.length, end)
      .replace(/&quot;/g, '"')
      .replace(/&#0?39;/g, "'")
      .replace(/&amp;/g, "&");
    try {
      return JSON.parse(this._decodeJsString(literal));
    } catch (error) {
      return null;
    }
  }

  // Decodes the contents of a JavaScript string literal (one layer of escapes).
  _decodeJsString(literal) {
    return literal.replace(/\\(u[0-9a-fA-F]{4}|x[0-9a-fA-F]{2}|[\s\S])/g, function (whole, escape) {
      const kind = escape.charAt(0);
      if ((kind === "u" || kind === "x") && escape.length > 1) return String.fromCharCode(parseInt(escape.slice(1), 16));
      if (kind === "n") return "\n";
      if (kind === "r") return "\r";
      if (kind === "t") return "\t";
      if (kind === "b") return "\b";
      if (kind === "f") return "\f";
      return escape;
    });
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        // A protocol-relative URL only counts when it opens a quoted value.
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  // Normalises URLs that sites emit without a scheme or with a doubled slash after it.
  _fixUrl(url) {
    const trimmed = String(url).trim();
    if (trimmed.indexOf("https:///") === 0) return "https://" + trimmed.slice(9);
    if (trimmed.indexOf("//") === 0) return "https:" + trimmed;
    return trimmed;
  }

  _subtitleFormat(url, declared) {
    const known = ["vtt", "srt", "ass", "ssa"];
    const said = String(declared || "").trim().toLowerCase();
    if (known.indexOf(said) >= 0) return said;
    const path = String(url).split(/[?#]/)[0];
    const ext = path.slice(path.lastIndexOf(".") + 1).toLowerCase();
    return known.indexOf(ext) >= 0 ? ext : "vtt";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// KickAssAnime (kaa.lt): sub and dub through the site's JSON API. Streams come from its player
// pages, whose configuration sits in an HTML-encoded `props` attribute.

class Provider {
  constructor() {
    this.mirrors = ["https://kaa.lt"];
    this.languages = { sub: "ja-JP", dub: "en-US" };
    // Episode pages fetched at once when listing a long show.
    this.pageBatch = 6;
    this.maxPages = 40;
    this.maxPlayers = 3;
  }

  getSettings() {
    return {
      episodeServers: ["VidStreaming", "CatStream"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const dub = Boolean(opts && opts.dub);
    const audio = dub ? "dub" : "sub";
    const lang = this.languages[audio];

    const results = [];
    for (const query of queries) {
      const answer = await this._api("/api/fsearch", {
        method: "POST",
        body: JSON.stringify({ query: query }),
      });
      const items = Array.isArray(answer.json && answer.json.result) ? answer.json.result : Array.isArray(answer.json) ? answer.json : [];
      for (const item of items) {
        if (!item || typeof item.slug !== "string" || !item.slug) continue;
        // A show is offered dubbed only when the site lists English audio for it.
        const locales = Array.isArray(item.locales) ? item.locales : [];
        if (dub && locales.indexOf(lang) < 0) continue;
        if (results.some(function (r) { return r.id.split("|")[1] === item.slug; })) continue;
        const titles = [];
        for (const title of [item.title_en, item.title]) {
          if (typeof title === "string" && title.trim() && titles.indexOf(title.trim()) < 0) titles.push(title.trim());
        }
        if (titles.length === 0) continue;
        results.push({
          id: answer.mirror + "|" + item.slug + "|" + lang,
          title: titles[0],
          url: answer.mirror + "/" + item.slug,
          subOrDub: audio,
          altTitles: titles.slice(1),
          year: typeof item.year === "number" ? item.year : undefined,
          episodeCount: typeof item.episode_count === "number" && item.episode_count > 0 ? item.episode_count : undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const show = this._parseShowId(id);
    const self = this;
    const first = await this._episodePage(show, 1);

    const bySlug = {};
    const order = [];
    const add = function (page, entry) {
      const key = String(entry.number);
      if (!bySlug[key]) order.push(key);
      if (!bySlug[key] || entry.slug) bySlug[key] = { page: page, entry: entry };
    };
    first.episodes.forEach(function (entry) { add(1, entry); });

    if (first.pages.length > 0) {
      // The page index names every episode. The other pages are fetched for titles and episode
      // slugs; one that fails leaves its episodes listed by number, resolved when played.
      const others = first.pages.filter(function (p) { return p.number !== 1; }).slice(0, this.maxPages);
      for (let i = 0; i < others.length; i += this.pageBatch) {
        const batch = others.slice(i, i + this.pageBatch);
        const fetched = await Promise.all(
          batch.map(function (p) {
            return self._episodePage(show, p.number).then(
              function (page) { return page; },
              function () { return null; }
            );
          })
        );
        batch.forEach(function (p, index) {
          if (fetched[index]) fetched[index].episodes.forEach(function (entry) { add(p.number, entry); });
          p.eps.forEach(function (number) {
            if (!bySlug[String(number)]) add(p.number, { number: number, written: self._formatNumber(number), slug: "", title: null });
          });
        });
      }
      first.pages.forEach(function (p) {
        p.eps.forEach(function (number) {
          if (!bySlug[String(number)]) add(p.number, { number: number, written: self._formatNumber(number), slug: "", title: null });
        });
      });
    } else {
      let hasNext = first.hasNext;
      for (let page = 2; hasNext && page <= this.maxPages; page += 1) {
        const next = await this._episodePage(show, page);
        if (next.episodes.length === 0) break;
        next.episodes.forEach(function (entry) { add(page, entry); });
        hasNext = next.hasNext;
      }
    }

    const episodes = order.map(function (key) {
      const found = bySlug[key];
      const entry = found.entry;
      return {
        id: [show.mirror, show.slug, show.lang, found.page, entry.written, entry.slug].join("|"),
        number: entry.number,
        url: entry.slug ? show.mirror + "/" + show.slug + "/ep-" + entry.written + "-" + entry.slug : show.mirror + "/" + show.slug,
        title: entry.title || "Episode " + entry.written,
      };
    });
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error(show.lang === this.languages.dub ? "no dub" : "no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    if (parts.length < 6 || !this._isHttpUrl(parts[0]) || !parts[1]) {
      throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    }
    const show = { mirror: parts[0], slug: parts[1], lang: parts[2] };
    let written = parts[4];
    let slug = parts[5];

    if (!slug) {
      const page = await this._episodePage(show, parseInt(parts[3], 10) || 1);
      const number = Number(written);
      const entry = page.episodes.filter(function (e) { return Math.abs(e.number - number) < 0.01; })[0];
      if (!entry || !entry.slug) throw new Error("episode " + written + " not listed");
      written = entry.written;
      slug = entry.slug;
    }

    const detail = await this._api(
      "/api/show/" + encodeURIComponent(show.slug) + "/episode/ep-" + encodeURIComponent(written) + "-" + encodeURIComponent(slug),
      null,
      show.mirror
    );
    const self = this;
    let players = (Array.isArray(detail.json && detail.json.servers) ? detail.json.servers : [])
      .filter(function (s) { return s && typeof s.src === "string" && s.src; })
      .map(function (s) { return { name: String(s.name || s.shortName || "server"), src: self._fixUrl(s.src) }; });
    if (players.length === 0) throw new Error("the site lists this episode without a video");

    const wanted = String(server || "default");
    if (wanted !== "default") {
      const offered = players.map(function (p) { return p.name; });
      players = players.filter(function (p) { return p.name.toLowerCase() === wanted.toLowerCase(); });
      if (players.length === 0) throw new Error("'" + wanted + "' is not offered for this episode (offered: " + offered.join(", ") + ")");
    }

    const audio = show.lang === this.languages.dub ? "Dub" : "Sub";
    let reason = null;
    for (const player of players.slice(0, this.maxPlayers)) {
      let html;
      try {
        html = await this._text(player.src, { headers: { Referer: show.mirror + "/", Origin: show.mirror } }, true);
      } catch (error) {
        reason = reason || this._errorText(error);
        continue;
      }
      const found = this._player(html);
      if (!found) {
        reason = reason || "player not supported (" + player.name + ", " + this._host(player.src) + ")";
        continue;
      }
      const origin = this._origin(player.src);
      return {
        server: player.name,
        headers: origin ? { Referer: origin + "/" } : {},
        videoSources: [
          {
            url: found.url,
            type: this._isHls(found.url) ? "m3u8" : "mp4",
            quality: "auto",
            label: found.subtitles.length > 0 ? audio + " · soft subtitles" : audio,
            subtitles: found.subtitles,
          },
        ],
      };
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _parseShowId(id) {
    const parts = String(id).split("|");
    if (parts.length < 3 || !this._isHttpUrl(parts[0]) || !parts[1] || !parts[2]) {
      throw new Error("invalid anime id '" + id + "'");
    }
    return { mirror: parts[0], slug: parts[1], lang: parts[2] };
  }

  // One page of the episodes API. The episode array is `result` (or `result.episodes`, or
  // `episodes`), and the index of all pages is the top-level `pages` array.
  async _episodePage(show, page) {
    const answer = await this._api(
      "/api/show/" + encodeURIComponent(show.slug) + "/episodes?page=" + page + "&lang=" + encodeURIComponent(show.lang),
      null,
      show.mirror
    );
    const json = answer.json || {};
    const result = json.result;
    const items = Array.isArray(result) ? result
      : result && Array.isArray(result.episodes) ? result.episodes
      : Array.isArray(json.episodes) ? json.episodes : [];

    const episodes = [];
    for (const item of items) {
      if (!item) continue;
      let number = this._number(item.episode_number);
      if (number === null) number = this._number(item.number);
      if (number === null || typeof item.slug !== "string" || !item.slug) continue;
      episodes.push({
        number: number,
        written: typeof item.episode_string === "string" && item.episode_string ? item.episode_string : this._formatNumber(number),
        slug: item.slug,
        title: typeof item.title === "string" && item.title.trim() ? item.title.trim() : null,
      });
    }

    const self = this;
    const listed = Array.isArray(json.pages) ? json.pages : result && Array.isArray(result.pages) ? result.pages : [];
    const pages = listed.map(function (entry, index) {
      const eps = entry && Array.isArray(entry.eps) ? entry.eps : [];
      return {
        number: entry && typeof entry.number === "number" ? entry.number : index + 1,
        eps: eps.map(function (n) { return self._number(n); }).filter(function (n) { return n !== null; }),
      };
    });

    const hasNext = typeof json.hasNextPage === "boolean" ? json.hasNextPage : Boolean(result && result.hasNextPage);
    return { episodes: episodes, pages: pages, hasNext: hasNext };
  }

  // The playlist and subtitle tracks from a player page: `props` holds
  // `{"manifest":[0,"//host/master.m3u8"],"subtitles":[1,[[0,{...}]]],...}`.
  _player(html) {
    const re = /props="([^"]*)"/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      let props;
      try {
        props = JSON.parse(this._unescapeBody(match[1]));
      } catch (error) {
        continue;
      }
      const manifest = props && Array.isArray(props.manifest) ? props.manifest[1] : null;
      if (typeof manifest !== "string" || !manifest) continue;

      const self = this;
      const value = function (field) { return Array.isArray(field) ? field[1] : undefined; };
      const tracks = props && Array.isArray(props.subtitles) && Array.isArray(props.subtitles[1]) ? props.subtitles[1] : [];
      const subtitles = [];
      tracks.forEach(function (wrapped, index) {
        const track = Array.isArray(wrapped) ? wrapped[1] : null;
        const src = track ? value(track.src) : null;
        if (typeof src !== "string" || !src) return;
        const url = self._fixUrl(src);
        const language = value(track.language);
        subtitles.push({
          id: (typeof language === "string" && language ? language : "sub") + "-" + index,
          url: url,
          language: value(track.name) || language || "Unknown",
          isDefault: false,
          format: self._subtitleFormat(url, value(track.format)),
        });
      });
      // The player marks no default; English is the one shown first.
      let chosen = subtitles.findIndex(function (s) { return /^en\b/i.test(s.id) || /^english/i.test(String(s.language)); });
      if (chosen < 0 && subtitles.length > 0) chosen = 0;
      if (chosen >= 0) subtitles[chosen].isDefault = true;
      return { url: this._fixUrl(manifest), subtitles: subtitles };
    }
    const urls = this._mediaUrls(html);
    return urls.length > 0 ? { url: urls[0], subtitles: [] } : null;
  }

  // ---------------------------------------------------------------- requests

  // A JSON request to the site, trying each mirror in turn (or only `onlyMirror`).
  async _api(path, init, onlyMirror) {
    const mirrors = onlyMirror ? [onlyMirror] : this.mirrors;
    let failure = null;
    for (const mirror of mirrors) {
      const headers = { Referer: mirror + "/", Accept: "application/json" };
      const options = { headers: headers };
      if (init && init.method) {
        options.method = init.method;
        options.body = init.body;
        headers["Content-Type"] = "application/json";
        headers["Origin"] = mirror;
      }
      try {
        const text = await this._text(mirror + path, options, false);
        const trimmed = text.replace(/^\s+/, "");
        if (trimmed.charAt(0) === "<") {
          throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : this._host(mirror) + " answered with a page instead of data");
        }
        let json;
        try {
          json = JSON.parse(trimmed);
        } catch (error) {
          throw new Error(this._host(mirror) + " sent unreadable data");
        }
        return { mirror: mirror, json: json };
      } catch (error) {
        failure = failure || error;
      }
    }
    throw failure || new Error("no mirror configured");
  }

  // The body of a 2xx answer. A redirect to another site is an error unless `anyHost`, which
  // is for player pages.
  async _text(url, options, anyHost) {
    const host = this._host(url);
    const init = { headers: (options && options.headers) || {} };
    if (options && options.method) {
      init.method = options.method;
      init.body = options.body;
    }
    let response;
    try {
      response = await fetch(url, init);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (!anyHost && response.url && this._host(response.url) !== "unknown host" && !this._sameSite(this._host(response.url), host)) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  // ---------------------------------------------------------------- shared helpers

  _isHttpUrl(url) {
    return typeof url === "string" && /^https?:\/\/[^\s\/]+/i.test(url);
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : null;
  }

  _number(value) {
    const number = typeof value === "number" ? value : typeof value === "string" && value.trim() ? Number(value) : NaN;
    return isFinite(number) ? number : null;
  }

  // 12 -> "12", 12.5 -> "12.5".
  _formatNumber(number) {
    return String(Math.round(number * 1000) / 1000);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        // A protocol-relative URL only counts when it opens a quoted value.
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  // Normalises URLs that sites emit without a scheme or with a doubled slash after it.
  _fixUrl(url) {
    const trimmed = String(url).trim();
    if (trimmed.indexOf("https:///") === 0) return "https://" + trimmed.slice(9);
    if (trimmed.indexOf("//") === 0) return "https:" + trimmed;
    return trimmed;
  }

  _subtitleFormat(url, declared) {
    const known = ["vtt", "srt", "ass", "ssa"];
    const said = String(declared || "").trim().toLowerCase();
    if (known.indexOf(said) >= 0) return said;
    const path = String(url).split(/[?#]/)[0];
    const ext = path.slice(path.lastIndexOf(".") + 1).toLowerCase();
    return known.indexOf(ext) >= 0 ? ext : "vtt";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// AnimeGG (animegg.org): sub and dub as direct MP4 files in several qualities. The watch page
// holds one embedded player per audio version; the embed page names the files.

class Provider {
  constructor() {
    this.base = "https://www.animegg.org";
  }

  getSettings() {
    return {
      episodeServers: ["Animegg"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/search?q=" + encodeURIComponent(query), this.base + "/");
      // One result: <a href="/series/slug" class="mse"> ... <h2>Title</h2> ... Alt Titles : a, b </a>
      const blocks = html.split(/<a\s+href="(?=\/series\/)/).slice(1);
      for (const block of blocks) {
        const path = block.slice(0, block.indexOf('"')).split(/[?#]/)[0];
        const slug = path.replace(/^\/series\//, "");
        if (!slug || results.some(function (r) { return r.id.split("|")[0] === slug; })) continue;
        const body = block.split("</a>")[0];
        const heading = /<h2[^>]*>([\s\S]*?)<\/h2>/.exec(body);
        const title = heading ? this._plain(heading[1]) : "";
        const alt = /Alt Titles\s*:\s*([^<]*)/.exec(body);
        const count = /Episodes:\s*(\d+)/.exec(body);
        const altTitles = alt
          ? this._plain(alt[1]).split(/\s*,\s*/).map(function (t) { return t.trim(); }).filter(function (t) { return t; })
          : [];
        // The slug is the title with dashes, which is a usable title in its own right.
        const fromSlug = slug.replace(/-+/g, " ").trim();
        results.push({
          id: slug + "|" + audio,
          title: title || fromSlug,
          url: this.base + path,
          subOrDub: audio,
          altTitles: title ? altTitles.concat([fromSlug]) : altTitles,
          episodeCount: count ? parseInt(count[1], 10) : undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!slug) throw new Error("invalid anime id '" + id + "'");

    const html = await this._page(this.base + "/series/" + slug, this.base + "/");
    // One entry: <a href="/x-episode-12" class="anm_det_pop"><strong>X 12</strong></a>
    // <i class="anititle">Title</i> followed by links ending in #subbed / #dubbed.
    const entries = html.split(/<a\s+href="(?=\/[^"]*-episode-\d)/).slice(1);
    const byNumber = {};
    const total = {};
    for (const entry of entries) {
      const href = entry.slice(0, entry.indexOf('"'));
      const path = href.split("#")[0];
      const numbered = /-episode-(\d+(?:\.\d+)?)/.exec(path);
      if (!numbered) continue;
      const key = numbered[1];
      total[key] = true;
      const found = byNumber[key] || { path: path, title: null, sub: false, dub: false, marked: false };
      byNumber[key] = found;
      const fragment = href.indexOf("#") >= 0 ? href.slice(href.indexOf("#") + 1).toLowerCase() : "";
      if (fragment === "subbed") found.sub = found.marked = true;
      if (fragment === "dubbed") found.dub = found.marked = true;
      const named = /<i[^>]*class="anititle"[^>]*>([\s\S]*?)<\/i>/.exec(entry.split(/<\/li>/)[0]);
      if (named && !found.title) found.title = this._plain(named[1]) || null;
    }

    const episodes = [];
    for (const key of Object.keys(byNumber)) {
      const found = byNumber[key];
      // A page without audio markers is taken as subbed.
      const offered = found.marked ? found[audio] : audio === "sub";
      if (!offered) continue;
      episodes.push({
        id: found.path + "|" + audio,
        number: Number(key),
        url: this.base + found.path,
        title: found.title || "Episode " + key,
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) {
      throw new Error(Object.keys(total).length === 0 ? "no episodes listed" : audio === "dub" ? "no dub" : "no subbed episodes");
    }
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const path = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!path || path.charAt(0) !== "/") throw new Error("invalid episode id '" + (episode && episode.id) + "'");

    const watchUrl = this.base + path;
    const html = await this._page(watchUrl, this.base + "/");

    // One tab per audio version and host: <div id="subbed-Animegg"><iframe src="/embed/123">.
    const tabs = [];
    const tabRe = /<div[^>]*\bid="(subbed|dubbed)-([^"]+)"[^>]*>\s*<iframe[^>]*\bsrc="([^"]+)"/gi;
    let match;
    while ((match = tabRe.exec(html)) !== null) {
      tabs.push({ audio: match[1].toLowerCase() === "dubbed" ? "dub" : "sub", name: match[2], src: match[3] });
    }
    if (tabs.length === 0) {
      // Older markup: a single player without audio tabs, which is the subbed one.
      const lone = /<iframe[^>]*\bsrc="(\/embed\/[^"]+|https?:\/\/[^"]*animegg[^"]*\/embed\/[^"]+)"/i.exec(html);
      if (lone) tabs.push({ audio: "sub", name: "Animegg", src: lone[1] });
    }

    let candidates = tabs.filter(function (tab) { return tab.audio === audio; });
    if (candidates.length === 0) {
      if (tabs.length > 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");
      const playlists = this._mediaUrls(html).filter(this._isHls);
      if (playlists.length === 0) throw new Error("no player on the episode page");
      return {
        server: "Animegg",
        headers: { Referer: this.base + "/" },
        videoSources: playlists.map(function (url, index) {
          return { url: url, type: "m3u8", quality: index === 0 ? "auto" : "auto (" + (index + 1) + ")", subtitles: [] };
        }),
      };
    }

    const wanted = String(server || "default");
    if (wanted !== "default") {
      const offered = candidates.map(function (tab) { return tab.name; });
      candidates = candidates.filter(function (tab) { return tab.name.toLowerCase() === wanted.toLowerCase(); });
      if (candidates.length === 0) throw new Error("'" + wanted + "' is not offered for this episode (offered: " + offered.join(", ") + ")");
    }

    let reason = null;
    for (const tab of candidates) {
      const embedUrl = this._absolute(tab.src);
      let embed;
      try {
        embed = await this._page(embedUrl, watchUrl);
      } catch (error) {
        reason = reason || this._errorText(error);
        continue;
      }
      const sources = this._videoSources(embed, audio);
      if (sources.length === 0) {
        reason = reason || "the player names no video";
        continue;
      }
      return { server: tab.name, headers: { Referer: embedUrl }, videoSources: sources };
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // Videos named by an embed page's player setup (`{file: "/play/1/video.mp4?for=..", label:
  // "720p"}`), best quality first. `/play/...` links are files behind a redirect.
  _videoSources(embedHtml, audio) {
    const text = this._unescapeBody(embedHtml);
    const found = [];
    const self = this;
    const add = function (raw, label) {
      if (!/\/play\/|\.mp4(?:[?#]|$)|\.m3u8(?:[?#]|$)/i.test(raw)) return;
      const url = self._absolute(raw);
      if (found.some(function (f) { return f.url === url; })) return;
      found.push({ url: url, label: label || "" });
    };

    const objectRe = /\{[^{}]*?file:\s*["']([^"']+)["'][^{}]*?\}/g;
    let match;
    while ((match = objectRe.exec(text)) !== null) {
      const label = /label:\s*["']([^"']*)["']/.exec(match[0]);
      add(match[1], label ? label[1] : "");
    }
    if (found.length === 0) {
      const looseRe = /(?:file:\s*["']|src=["'])([^"']*(?:\/play\/|\.mp4|\.m3u8)[^"']*)/g;
      while ((match = looseRe.exec(text)) !== null) add(match[1], "");
    }

    const height = function (label) { return parseInt(label, 10) || 0; };
    found.sort(function (a, b) { return height(b.label) - height(a.label); });
    const voice = audio === "dub" ? "Dub" : "Sub";
    const used = {};
    return found.map(function (f, index) {
      let quality = f.label || "auto";
      if (used[quality]) quality = quality + " (" + (index + 1) + ")";
      used[quality] = true;
      return { url: f.url, type: self._isHls(f.url) ? "m3u8" : "mp4", quality: quality, label: voice, subtitles: [] };
    });
  }

  _absolute(raw) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    return this.base + (url.charAt(0) === "/" ? "" : "/") + url;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  // ---------------------------------------------------------------- shared helpers

  async _page(url, referer) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: referer } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (response.url && this._host(response.url) !== "unknown host" && !this._sameSite(this._host(response.url), host)) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        // A protocol-relative URL only counts when it opens a quoted value.
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// HiAnime (hianime.at): sub and dub as HLS with soft subtitles and intro/outro times, from two
// players (ZokoAnime and MegaPlay, listed as HD-1).
// Endpoints and the ZokoAnime decoding as in ani-cli (github.com/pystardust/ani-cli).

class Provider {
  constructor() {
    this.base = "https://hianime.at";
    this.servers = ["ZokoAnime", "HD-1"];
    this.playerKey = "otaku-embed-v1";
    this.megaPlayKey = "i?LMTAx0Q6,:}50U";
    this.megaPlayIv = "W0;27ToaUpl_P%'c";
  }

  getSettings() {
    return {
      episodeServers: ["ZokoAnime", "HD-1"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/search?keyword=" + encodeURIComponent(query));
      // The sidebar repeats the result markup for unrelated shows.
      const main = html.split(/id="main-sidebar"/)[0];
      const blocks = main.split(/<div class="flw-item/).slice(1);
      for (const block of blocks) {
        // <a href=".../watch/one-piece-1" class="film-poster-ahref" data-id="1"> and
        // <a href=".../one-piece-1" title="One Piece" class="dynamic-name" data-jname="One Piece">
        const name = /<a\s+href="[^"]*\/([^"\/?#]+)"\s+title="([^"]*)"\s+class="dynamic-name"(?:\s+data-jname="([^"]*)")?/.exec(block);
        const numeric = /\bdata-id="(\d+)"/.exec(block);
        if (!name || !numeric) continue;
        const slug = name[1];
        if (results.some(function (r) { return r.slug === slug; })) continue;
        const subbed = this._tick(block, "tick-sub");
        const dubbed = this._tick(block, "tick-dub");
        const count = audio === "dub" ? dubbed : subbed;
        if (audio === "dub" && dubbed === 0) continue;
        const title = this._plain(name[2]);
        const other = name[3] ? this._plain(name[3]) : "";
        if (!title && !other) continue;
        results.push({
          slug: slug,
          id: slug + "|" + numeric[1] + "|" + audio + "|" + count,
          title: title || other,
          url: this.base + "/" + slug,
          subOrDub: audio,
          altTitles: title && other && other !== title ? [other] : [],
          episodeCount: count || undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results.map(function (r) {
      delete r.slug;
      return r;
    });
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const numeric = parts[1];
    const audio = parts[2] === "dub" ? "dub" : "sub";
    const offered = parseInt(parts[3], 10) || 0;
    if (!slug || !/^\d+$/.test(numeric || "")) throw new Error("invalid anime id '" + id + "'");

    const data = await this._json(this.base + "/api/theme/episode/list/" + numeric, this.base + "/watch/" + slug);
    const html = data && typeof data.html === "string" ? data.html : "";
    // One entry: <a title="Episode 1" class="ssl-item ep-item" data-number="1" data-id="1" href="...">
    const episodes = [];
    const seen = {};
    const entries = html.split(/<a\s+(?=[^>]*\bep-item\b)/).slice(1);
    for (const entry of entries) {
      const tag = entry.slice(0, entry.indexOf(">"));
      const number = /\bdata-number="(\d+(?:\.\d+)?)"/.exec(tag);
      const episodeId = /\bdata-id="(\d+)"/.exec(tag);
      if (!number || !episodeId || seen[number[1]]) continue;
      seen[number[1]] = true;
      const href = /\bhref="([^"]+)"/.exec(tag);
      const named = /class="ep-name[^"]*"[^>]*\btitle="([^"]*)"/.exec(entry);
      episodes.push({
        id: episodeId[1] + "|" + audio,
        number: Number(number[1]),
        url: href ? this._unescapeBody(href[1]) : this.base + "/watch/" + slug + "?ep=" + episodeId[1],
        title: (named && this._plain(named[1])) || "Episode " + number[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    // The list has no audio marks; the search page told how many episodes are dubbed.
    if (audio === "dub" && offered > 0) {
      const dubbed = episodes.filter(function (episode) { return episode.number <= offered; });
      if (dubbed.length === 0) throw new Error("no dub");
      return dubbed;
    }
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const episodeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(episodeId || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const data = await this._json(this.base + "/api/theme/episode/servers?episodeId=" + episodeId, this.base + "/");
    const html = data && typeof data.html === "string" ? data.html : "";
    // One entry: <div class="item server-item" data-type="sub" data-server-name="ZokoAnime" data-hash="base64 of the player URL">
    const offered = [];
    const players = [];
    const itemRe = /<div[^>]*\bserver-item\b[^>]*>/g;
    let match;
    while ((match = itemRe.exec(html)) !== null) {
      const type = /\bdata-type="([^"]*)"/.exec(match[0]);
      const name = /\bdata-server-name="([^"]*)"/.exec(match[0]);
      const hash = /\bdata-hash="([^"]*)"/.exec(match[0]);
      if (!type || !name || !hash) continue;
      offered.push(name[1] + " (" + type[1] + ")");
      if (type[1].toLowerCase() !== audio) continue;
      let decoded = "";
      try {
        decoded = String(atob(hash[1])).trim();
      } catch (error) {
        decoded = "";
      }
      if (/^https?:\/\//i.test(decoded)) players.push({ name: name[1], url: decoded });
    }
    if (offered.length === 0) throw new Error("no player listed for this episode");
    if (players.length === 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");

    // "default" tries the players in the order of `servers`.
    const order = wanted === "default" ? known : [wanted];
    let reason = null;
    let tried = false;
    for (const name of order) {
      const player = players.filter(function (p) { return p.name.toLowerCase() === name.toLowerCase(); })[0];
      if (!player) continue;
      tried = true;
      try {
        const found = name.toLowerCase() === "hd-1" ? await this._megaPlay(player.url) : await this._zoko(player.url);
        const result = {
          server: player.name,
          headers: { Referer: this._origin(player.url) + "/" },
          videoSources: [
            {
              url: found.url,
              type: this._isHls(found.url) ? "m3u8" : "mp4",
              quality: "auto",
              label: audio === "dub" ? "Dub" : "Soft sub",
              subtitles: found.subtitles,
            },
          ],
        };
        if (found.skip) result.skip = found.skip;
        return result;
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    if (!tried) throw new Error("'" + wanted + "' is not offered for this episode (offered: " + offered.join(", ") + ")");
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- players

  // ZokoAnime: the page carries `window.__P`, base64 of the configuration XORed with a key.
  async _zoko(playerUrl) {
    const page = await this._page(playerUrl, true);
    const blob = /window\.__P\s*=\s*"([^"]+)"/.exec(page);
    if (!blob) throw new Error("the player page has changed (no configuration)");
    const config = this._decodeConfig(blob[1]);
    if (!config || typeof config.src !== "string" || !/^https?:\/\//i.test(config.src)) {
      throw new Error("the player names no video");
    }
    const listed = (Array.isArray(config.subtitles) ? config.subtitles : []).map(function (entry) {
      return entry ? { url: entry.src, label: entry.label || entry.lang, isDefault: entry.default === true } : null;
    });
    return { url: config.src, subtitles: this._subtitles(listed, this._origin(playerUrl)), skip: this._skip(config.skip) };
  }

  // MegaPlay (HD-1): the page names a file id; `getSources` answers with the subtitle tracks,
  // the intro/outro times and the video address, AES-encrypted with the player's fixed key.
  async _megaPlay(playerUrl) {
    const origin = this._origin(playerUrl);
    const page = await this._page(playerUrl, true);
    const file = /<div[^>]*\bid="megaplay-player"[^>]*\bdata-id="(\d+)"/.exec(page) || /\bdata-id="(\d+)"/.exec(page);
    if (!file) throw new Error("the player page has changed (no file id)");
    const lane = /[?&]s=([A-Za-z0-9_-]+)/.exec(playerUrl);
    const data = await this._json(origin + "/stream/getSources?id=" + file[1] + (lane ? "&s=" + lane[1] : ""), playerUrl);

    let url = "";
    const plain = data && data.sources;
    if (plain && typeof plain.file === "string") url = plain.file;
    else if (Array.isArray(plain) && plain[0] && typeof plain[0].file === "string") url = plain[0].file;
    else if (data && typeof data.enc === "string" && data.enc) {
      const opened = this._megaPlayOpen(data.enc);
      if (opened && typeof opened.file === "string") url = opened.file;
      else if (opened && opened.sources && typeof opened.sources.file === "string") url = opened.sources.file;
    }
    if (!/^https?:\/\//i.test(url)) throw new Error("the player names no video");

    const listed = (data && Array.isArray(data.tracks) ? data.tracks : []).map(function (track) {
      if (!track || (track.kind && track.kind !== "captions" && track.kind !== "subtitles")) return null;
      return { url: track.file, label: track.label, isDefault: track.default === true };
    });
    return { url: url, subtitles: this._subtitles(listed, origin), skip: this._skip({ intro: data.intro, outro: data.outro }) };
  }

  // AES-256-CBC with the key and IV the player's own script uses (text, zero-padded).
  _megaPlayOpen(enc) {
    if (typeof CryptoJS === "undefined") throw new Error("this host has no CryptoJS to open the HD-1 answer");
    const padded = function (text, size) {
      const bytes = new Uint8Array(size);
      for (let i = 0; i < Math.min(size, text.length); i += 1) bytes[i] = text.charCodeAt(i);
      return bytes;
    };
    let base64 = String(enc).replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4 !== 0) base64 += "=";
    try {
      const opened = CryptoJS.AES.decrypt(base64, padded(this.megaPlayKey, 32), { iv: padded(this.megaPlayIv, 16) });
      return JSON.parse(String(opened.toString(CryptoJS.enc.Utf8)));
    } catch (error) {
      return null;
    }
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // The episode count in a result's badge: <div class="tick-item tick-sub"><i ...></i>1180</div>.
  _tick(block, name) {
    const match = new RegExp('class="[^"]*\\b' + name + '\\b[^"]*">\\s*(?:<i[^>]*>\\s*</i>)?\\s*(\\d+)').exec(block);
    return match ? parseInt(match[1], 10) : 0;
  }

  // The player configuration: base64 of JSON XORed with a repeating key.
  _decodeConfig(blob) {
    let binary;
    try {
      binary = String(atob(blob));
    } catch (error) {
      return null;
    }
    const key = this.playerKey;
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) {
      bytes[i] = (binary.charCodeAt(i) ^ key.charCodeAt(i % key.length)) & 0xff;
    }
    try {
      return JSON.parse(new TextDecoder("utf-8").decode(bytes));
    } catch (error) {
      return null;
    }
  }

  // `listed`: [{ url, label, isDefault }], addresses possibly relative to the player.
  _subtitles(listed, playerOrigin) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !entry.url) continue;
      const url = /^https?:\/\//i.test(entry.url) ? entry.url : playerOrigin + (entry.url.charAt(0) === "/" ? "" : "/") + entry.url;
      if (subtitles.some(function (s) { return s.url === url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // { intro: { start, end }, outro: { start, end } } in seconds.
  _skip(listed) {
    if (!listed || typeof listed !== "object") return null;
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const intro = part(listed.intro);
    const outro = part(listed.outro);
    if (!intro && !outro) return null;
    const skip = {};
    if (intro) {
      skip.introStart = intro.start;
      skip.introEnd = intro.end;
    }
    if (outro) {
      skip.outroStart = outro.start;
      skip.outroEnd = outro.end;
    }
    return skip;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  // ---------------------------------------------------------------- shared helpers

  // The body of a 2xx answer. A redirect to another site is an error unless `anyHost`, which
  // is for player pages.
  async _page(url, anyHost) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: this.base + "/" } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (!anyHost && response.url && this._host(response.url) !== "unknown host" && !this._sameSite(this._host(response.url), host)) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  async _json(url, referer) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: referer, Accept: "application/json", "X-Requested-With": "XMLHttpRequest" } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _origin(url) {
    const match = /^([a-z][a-z0-9+.-]*:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// Aniwatch (aniwatchtv.ro): sub and dub as HLS, from MegaPlay (soft subtitles, intro/outro times),
// ZokoAnime and Vidmoly. The site runs the same theme as HiAnime, behind WordPress: search,
// episode lists and players come from its `wp-json/v1/otakuthemes/` interface. The players' names
// on the site ("HD-1", "Fast Player"…) do not say which host they are, so the address decides.

class Provider {
  constructor() {
    this.base = "https://aniwatchtv.ro";
    this.api = this.base + "/wp-json/v1/otakuthemes/";
    this.servers = ["MegaPlay", "ZokoAnime", "Vidmoly"];
    this.playerKey = "otaku-embed-v1";
    this.megaPlayKey = "i?LMTAx0Q6,:}50U";
    this.megaPlayIv = "W0;27ToaUpl_P%'c";
  }

  getSettings() {
    return {
      episodeServers: ["MegaPlay", "ZokoAnime", "Vidmoly"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const data = await this._json(this.api + "search/suggestions?keyword=" + encodeURIComponent(query), this.base + "/");
      const html = data && typeof data.html === "string" ? data.html : "";
      // One result: <a href=".../anime/one-piece/" class="nav-item"> … <h3 class="film-name dynamic-name" data-jname="One Piece">One Piece</h3>
      for (const block of html.split(/<a\s+(?=[^>]*\bnav-item\b)/).slice(1)) {
        const link = /href="[^"]*\/anime\/([\w-]+)\/?"/.exec(block);
        const name = /class="film-name[^"]*"(?:\s+data-jname="([^"]*)")?[^>]*>([\s\S]*?)<\/h3>/.exec(block);
        if (!link || !name) continue;
        const slug = link[1];
        if (results.some(function (r) { return r.id.split("|")[0] === slug; })) continue;
        const title = this._plain(name[2]);
        const other = name[1] ? this._plain(name[1]) : "";
        if (!title && !other) continue;
        results.push({
          id: slug + "|" + audio,
          title: title || other,
          url: this.base + "/anime/" + slug + "/",
          subOrDub: audio,
          altTitles: title && other && other !== title ? [other] : [],
        });
      }
      if (results.length > 0) break;
    }

    // The suggestions list only five shows and miss main titles ("One Piece" gives its spin-offs),
    // so the page a title's address would have is tried too, and put first when it exists.
    const direct = [];
    for (const query of queries) {
      const slug = this._slug(query);
      if (!slug || direct.some(function (r) { return r.id.split("|")[0] === slug; })) continue;
      let page = "";
      try {
        page = await this._page(this.base + "/anime/" + slug + "/");
      } catch (error) {
        continue;
      }
      const name = /<h2\s+class="film-name[^"]*"(?:\s+data-jname="([^"]*)")?[^>]*>([\s\S]*?)<\/h2>/.exec(page);
      if (!name) continue;
      const title = this._plain(name[2]);
      const other = name[1] ? this._plain(name[1]) : "";
      direct.push({
        id: slug + "|" + audio,
        title: title || other || query,
        url: this.base + "/anime/" + slug + "/",
        subOrDub: audio,
        altTitles: title && other && other !== title ? [other] : [],
      });
    }
    return direct.concat(results.filter(function (r) {
      return !direct.some(function (d) { return d.id === r.id; });
    }));
  }

  // The site's address for a title: "Frieren: Beyond Journey's End" → "frieren-beyond-journeys-end".
  _slug(title) {
    return String(title).toLowerCase().replace(/['’]/g, "").replace(/&/g, " and ").replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    // The show page names its number many times (watchlist buttons); the sidebar names others once.
    const page = await this._page(this.base + "/anime/" + slug + "/");
    const counts = {};
    let numeric = "";
    const idRe = /\bdata-anime-?id="(\d+)"/g;
    let match;
    while ((match = idRe.exec(page)) !== null) {
      counts[match[1]] = (counts[match[1]] || 0) + 1;
      if (!numeric || counts[match[1]] > counts[numeric]) numeric = match[1];
    }
    if (!numeric) throw new Error("the show page has changed (no anime number)");

    const data = await this._json(this.api + "episode/list/" + numeric, this.base + "/anime/" + slug + "/");
    const html = data && typeof data.html === "string" ? data.html : "";
    // One entry: <a title="Episode 1" class="ssl-item ep-item" data-number="1" data-id="10844" href="...">
    const episodes = [];
    const seen = {};
    const entries = html.split(/<a\s+(?=[^>]*\bep-item\b)/).slice(1);
    for (const entry of entries) {
      const tag = entry.slice(0, entry.indexOf(">"));
      const number = /\bdata-number="(\d+(?:\.\d+)?)"/.exec(tag);
      const episodeId = /\bdata-id="(\d+)"/.exec(tag);
      if (!number || !episodeId || seen[number[1]]) continue;
      seen[number[1]] = true;
      const href = /\bhref="([^"]+)"/.exec(tag);
      const named = /class="ep-name[^"]*"[^>]*\btitle="([^"]*)"/.exec(entry);
      episodes.push({
        id: episodeId[1] + "|" + audio,
        number: Number(number[1]),
        url: href ? this._unescapeBody(href[1]) : this.base + "/anime/" + slug + "/",
        title: (named && this._plain(named[1])) || "Episode " + number[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    // The list has no audio marks; a show whose first episode has no dub player has no dub.
    if (audio === "dub") {
      const first = await this._players(episodes[0].id.split("|")[0], "dub");
      if (first.players.length === 0) throw new Error("no dub");
    }
    return episodes;
  }

  // The players an episode lists for one audio: { offered: ["name (type)"], players: [{ name, url }] }.
  async _players(episodeId, audio) {
    const data = await this._json(this.api + "episode/servers?episodeId=" + episodeId, this.base + "/");
    const html = data && typeof data.html === "string" ? data.html : "";
    // One entry: <div class="item server-item" data-type="sub" data-server-name="HD-1" data-hash="base64 of the player URL">
    const offered = [];
    const players = [];
    const itemRe = /<div[^>]*\bserver-item\b[^>]*>/g;
    let match;
    while ((match = itemRe.exec(html)) !== null) {
      const type = /\bdata-type="([^"]*)"/.exec(match[0]);
      const name = /\bdata-server-name="([^"]*)"/.exec(match[0]);
      const hash = /\bdata-hash="([^"]*)"/.exec(match[0]);
      if (!type || !name || !hash) continue;
      offered.push(name[1] + " (" + type[1] + ")");
      if (type[1].toLowerCase() !== audio) continue;
      let decoded = "";
      try {
        decoded = String(atob(hash[1])).trim();
      } catch (error) {
        decoded = "";
      }
      if (/^https?:\/\//i.test(decoded) && !players.some(function (p) { return p.url === decoded; })) {
        players.push({ name: name[1], url: decoded, host: this._serverOf(decoded) });
      }
    }
    return { offered: offered, players: players };
  }

  // Which reader handles a player address; "" for hosts this extension cannot read.
  _serverOf(url) {
    const host = this._host(url);
    if (/^megaplay\.buzz$/.test(host) && /\/stream\//.test(url)) return "MegaPlay";
    if (/zokoanime/.test(host)) return "ZokoAnime";
    if (/vidmoly/.test(host)) return "Vidmoly";
    return "";
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const episodeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(episodeId || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const listed = await this._players(episodeId, audio);
    if (listed.offered.length === 0) throw new Error("no player listed for this episode");
    if (listed.players.length === 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");

    // "default" tries the players in the order of `servers`.
    const order = wanted === "default" ? known : known.filter(function (name) { return name.toLowerCase() === wanted.toLowerCase(); });
    const failures = [];
    let tried = false;
    for (const name of order) {
      for (const player of listed.players.filter(function (p) { return p.host === name; })) {
        tried = true;
        try {
          const found = name === "MegaPlay" ? await this._megaPlay(player.url)
            : name === "ZokoAnime" ? await this._zoko(player.url)
            : await this._vidmoly(player.url);
          const result = {
            server: name,
            headers: { Referer: this._origin(player.url) + "/" },
            videoSources: [
              {
                url: found.url,
                type: this._isHls(found.url) ? "m3u8" : "mp4",
                quality: "auto",
                label: audio === "dub" ? "Dub" : name === "Vidmoly" ? "Hard sub" : "Soft sub",
                subtitles: found.subtitles || [],
              },
            ],
          };
          if (found.skip) result.skip = found.skip;
          return result;
        } catch (error) {
          failures.push(name + ": " + this._errorText(error));
        }
      }
    }
    if (!tried) {
      throw new Error(wanted === "default"
        ? "this episode is only on players this extension can't read (offered: " + listed.offered.join(", ") + ")"
        : "'" + wanted + "' is not offered for this episode");
    }
    throw new Error(failures.join("; ") || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- players

  // ZokoAnime: the page carries `window.__P`, base64 of the configuration XORed with a key.
  async _zoko(playerUrl) {
    const page = await this._page(playerUrl, true);
    const blob = /window\.__P\s*=\s*"([^"]+)"/.exec(page);
    if (!blob) throw new Error("the player page has changed (no configuration)");
    const config = this._decodeConfig(blob[1]);
    if (!config || typeof config.src !== "string" || !/^https?:\/\//i.test(config.src)) {
      throw new Error("the player names no video");
    }
    const listed = (Array.isArray(config.subtitles) ? config.subtitles : []).map(function (entry) {
      return entry ? { url: entry.src, label: entry.label || entry.lang, isDefault: entry.default === true } : null;
    });
    return { url: config.src, subtitles: this._subtitles(listed, this._origin(playerUrl)), skip: this._skip(config.skip) };
  }

  // Vidmoly: the page's player setup names the playlist (`sources: [{ file: '...' }]`).
  async _vidmoly(playerUrl) {
    const page = await this._page(playerUrl, true);
    const setup = /sources:\s*\[\s*\{\s*file:\s*["']([^"']+)["']/.exec(page);
    const video = setup ? this._unescapeBody(setup[1]) : "";
    if (!/^https?:\/\//i.test(video)) throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Vidmoly" : "the player names no video");
    return { url: video, subtitles: [] };
  }

  // MegaPlay: the page names a file id; `getSources` answers with the subtitle tracks,
  // the intro/outro times and the video address, AES-encrypted with the player's fixed key.
  async _megaPlay(playerUrl) {
    const origin = this._origin(playerUrl);
    const page = await this._page(playerUrl, true);
    const file = /<div[^>]*\bid="megaplay-player"[^>]*\bdata-id="(\d+)"/.exec(page) || /\bdata-id="(\d+)"/.exec(page);
    if (!file) throw new Error("the player page has changed (no file id)");
    const lane = /[?&]s=([A-Za-z0-9_-]+)/.exec(playerUrl);
    const data = await this._json(origin + "/stream/getSources?id=" + file[1] + (lane ? "&s=" + lane[1] : ""), playerUrl);

    let url = "";
    const plain = data && data.sources;
    if (plain && typeof plain.file === "string") url = plain.file;
    else if (Array.isArray(plain) && plain[0] && typeof plain[0].file === "string") url = plain[0].file;
    else if (data && typeof data.enc === "string" && data.enc) {
      const opened = this._megaPlayOpen(data.enc);
      if (opened && typeof opened.file === "string") url = opened.file;
      else if (opened && opened.sources && typeof opened.sources.file === "string") url = opened.sources.file;
    }
    if (!/^https?:\/\//i.test(url)) throw new Error("the player names no video");

    const listed = (data && Array.isArray(data.tracks) ? data.tracks : []).map(function (track) {
      if (!track || (track.kind && track.kind !== "captions" && track.kind !== "subtitles")) return null;
      return { url: track.file, label: track.label, isDefault: track.default === true };
    });
    return { url: url, subtitles: this._subtitles(listed, origin), skip: this._skip({ intro: data.intro, outro: data.outro }) };
  }

  // AES-256-CBC with the key and IV the player's own script uses (text, zero-padded).
  _megaPlayOpen(enc) {
    if (typeof CryptoJS === "undefined") throw new Error("this host has no CryptoJS to open the MegaPlay answer");
    const padded = function (text, size) {
      const bytes = new Uint8Array(size);
      for (let i = 0; i < Math.min(size, text.length); i += 1) bytes[i] = text.charCodeAt(i);
      return bytes;
    };
    let base64 = String(enc).replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4 !== 0) base64 += "=";
    try {
      const opened = CryptoJS.AES.decrypt(base64, padded(this.megaPlayKey, 32), { iv: padded(this.megaPlayIv, 16) });
      return JSON.parse(String(opened.toString(CryptoJS.enc.Utf8)));
    } catch (error) {
      return null;
    }
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // The player configuration: base64 of JSON XORed with a repeating key.
  _decodeConfig(blob) {
    let binary;
    try {
      binary = String(atob(blob));
    } catch (error) {
      return null;
    }
    const key = this.playerKey;
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) {
      bytes[i] = (binary.charCodeAt(i) ^ key.charCodeAt(i % key.length)) & 0xff;
    }
    try {
      return JSON.parse(new TextDecoder("utf-8").decode(bytes));
    } catch (error) {
      return null;
    }
  }

  // `listed`: [{ url, label, isDefault }], addresses possibly relative to the player.
  _subtitles(listed, playerOrigin) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !entry.url) continue;
      const url = /^https?:\/\//i.test(entry.url) ? entry.url : playerOrigin + (entry.url.charAt(0) === "/" ? "" : "/") + entry.url;
      if (subtitles.some(function (s) { return s.url === url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // { intro: { start, end }, outro: { start, end } } in seconds.
  _skip(listed) {
    if (!listed || typeof listed !== "object") return null;
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const intro = part(listed.intro);
    const outro = part(listed.outro);
    if (!intro && !outro) return null;
    const skip = {};
    if (intro) {
      skip.introStart = intro.start;
      skip.introEnd = intro.end;
    }
    if (outro) {
      skip.outroStart = outro.start;
      skip.outroEnd = outro.end;
    }
    return skip;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  // ---------------------------------------------------------------- shared helpers

  // The body of a 2xx answer. A redirect to another site is an error unless `anyHost`, which
  // is for player pages.
  async _page(url, anyHost) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: this.base + "/" } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (!anyHost && response.url && this._host(response.url) !== "unknown host" && !this._sameSite(this._host(response.url), host)) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  async _json(url, referer) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: referer, Accept: "application/json", "X-Requested-With": "XMLHttpRequest" } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _origin(url) {
    const match = /^([a-z][a-z0-9+.-]*:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// Anikoto (anikototv.to): sub and dub as HLS with soft subtitles and intro/outro times, from
// the MegaPlay player.
// Site calls as in the Mangayomi source (github.com/Mallyd11/mangayomi-anime-extensions).

class Provider {
  constructor() {
    this.base = "https://anikototv.to";
    this.apiHeaders = { Referer: this.base + "/", "X-Requested-With": "XMLHttpRequest" };
    this.servers = ["HD-1", "Vidstream-2"];
    this.megaPlayKey = "i?LMTAx0Q6,:}50U";
    this.megaPlayIv = "W0;27ToaUpl_P%'c";
  }

  getSettings() {
    return {
      episodeServers: ["HD-1", "Vidstream-2"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/filter?keyword=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
      // One result: <div class="ani poster tip" data-tip="1642"> <a href=".../watch/slug/ep-1">
      // <span class="ep-status sub"><span> 1180</span></span><span class="ep-status dub">...
      // <a class="name d-title" href="..." data-jp="Romaji title">English title</a>
      const blocks = html.split(/<div class="ani poster tip"/).slice(1);
      for (const block of blocks) {
        const numeric = /^\s*data-tip="(\d+)"/.exec(block);
        const link = /<a\s+href="([^"]*\/watch\/([^"\/]+))(?:\/[^"]*)?"/.exec(block);
        const name = /<a\s+class="name d-title"[^>]*?(?:\bdata-jp="([^"]*)")?\s*>([^<]*)<\/a>/.exec(block);
        if (!numeric || !link || !name) continue;
        if (results.some(function (r) { return r.numeric === numeric[1]; })) continue;
        const subbed = this._status(block, "sub");
        const dubbed = this._status(block, "dub");
        if (audio === "dub" && !dubbed) continue;
        const titles = this._distinct([this._plain(name[2]), this._plain(name[1] || "")]);
        if (titles.length === 0) continue;
        results.push({
          numeric: numeric[1],
          id: numeric[1] + "|" + link[2] + "|" + audio,
          title: titles[0],
          url: this._unescapeBody(link[1]),
          subOrDub: audio,
          altTitles: titles.slice(1),
          episodeCount: (audio === "dub" ? dubbed : subbed) || undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results.map(function (r) {
      delete r.numeric;
      return r;
    });
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const numeric = parts[0];
    const slug = parts[1] || "";
    const audio = parts[2] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(numeric)) throw new Error("invalid anime id '" + id + "'");

    const data = await this._api(this.base + "/ajax/episode/list/" + numeric + "?vrf=");
    const html = data && typeof data.result === "string" ? data.result : "";
    // One entry: <li title="Episode title"> <a data-num="1" data-sub="1" data-dub="1" data-ids="token">
    const episodes = [];
    const seen = {};
    let total = 0;
    const entries = html.split(/<li\b/).slice(1);
    for (const entry of entries) {
      const tag = /<a\b[^>]*\bdata-ids="[^"]+"[^>]*>/.exec(entry);
      if (!tag) continue;
      const number = /\bdata-num="(\d+(?:\.\d+)?)"/.exec(tag[0]);
      const token = /\bdata-ids="([^"]+)"/.exec(tag[0]);
      if (!number || !token || seen[number[1]]) continue;
      total += 1;
      const offered = new RegExp('\\bdata-' + audio + '="1"').test(tag[0]);
      if (!offered) continue;
      seen[number[1]] = true;
      const named = /^[^>]*\btitle="([^"]*)"/.exec(entry);
      episodes.push({
        id: token[1] + "|" + audio,
        number: Number(number[1]),
        url: this.base + "/watch/" + slug + "/ep-" + number[1],
        title: (named && this._plain(named[1])) || "Episode " + number[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error(total === 0 ? "no episodes listed" : audio === "dub" ? "no dub" : "no subbed episodes");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const token = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!token || !/^[A-Za-z0-9+\/=_-]+$/.test(token)) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const data = await this._api(this.base + "/ajax/server/list?servers=" + encodeURIComponent(token));
    const html = data && typeof data.result === "string" ? data.result : "";
    // <div class="type" data-type="sub"> ... <li data-link-id="token">HD-1</li>
    const links = [];
    let offeredAny = false;
    const groups = html.split(/<div class="type"/).slice(1);
    for (const group of groups) {
      const type = /^\s*data-type="([^"]*)"/.exec(group);
      const itemRe = /<li\b[^>]*\bdata-link-id="([^"]+)"[^>]*>([^<]*)</g;
      let match;
      while ((match = itemRe.exec(group)) !== null) {
        offeredAny = true;
        if (type && type[1].toLowerCase() === audio) links.push({ name: match[2].trim(), token: match[1] });
      }
    }
    if (!offeredAny) throw new Error("no server listed for this episode");
    if (links.length === 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");

    // "default" tries what the episode offers in the order of `servers`.
    const order = wanted === "default" ? known : [wanted];
    let reason = null;
    let tried = false;
    for (const name of order) {
      const link = links.filter(function (l) { return l.name.toLowerCase() === name.toLowerCase(); })[0];
      if (!link) continue;
      tried = true;
      try {
        const answer = await this._api(this.base + "/ajax/server?get=" + encodeURIComponent(link.token));
        const player = answer && answer.result && typeof answer.result.url === "string" ? answer.result.url : "";
        if (!/^https?:\/\//i.test(player)) throw new Error("the site names no player");
        const found = await this._megaPlay(player);
        const times = answer.result.skip_data || {};
        const pair = function (value) { return Array.isArray(value) ? { start: value[0], end: value[1] } : null; };
        const result = {
          server: link.name,
          headers: { Referer: found.referer },
          videoSources: [
            { url: found.url, type: this._isHls(found.url) ? "m3u8" : "mp4", quality: "auto", label: audio === "dub" ? "Dub" : "Soft sub", subtitles: found.subtitles },
          ],
        };
        const skip = found.skip || this._skip(pair(times.intro), pair(times.outro));
        if (skip) result.skip = skip;
        return result;
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    if (!tried) {
      throw new Error("'" + wanted + "' is not offered for this episode (offered: " + links.map(function (l) { return l.name; }).join(", ") + ")");
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- parsing

  // The episode count of an audio badge: <span class="ep-status sub"><span> 1180</span></span>.
  _status(block, audio) {
    const match = new RegExp('class="ep-status ' + audio + '"[^>]*>\\s*<span[^>]*>\\s*(\\d+)').exec(block);
    return match ? parseInt(match[1], 10) : 0;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  // Undoes HTML entities.
  _unescapeBody(body) {
    return body
      .replace(/&#(\d{2,6});/g, function (whole, code) { return String.fromCodePoint(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,6});/g, function (whole, hex) { return String.fromCodePoint(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&amp;/g, "&");
  }

  // ---------------------------------------------------------------- player

  // MegaPlay: the page names a file id; `getSources` answers with the subtitle tracks, the
  // intro/outro times and the video address, AES-encrypted with the player's fixed key.
  async _megaPlay(playerUrl) {
    const origin = /^(https?:\/\/[^\/?#]+)/i.exec(playerUrl)[1];
    const page = await this._page(playerUrl, this.base + "/");
    const file = /<div[^>]*\bid="megaplay-player"[^>]*\bdata-id="(\d+)"/.exec(page) || /\bdata-id="(\d+)"/.exec(page);
    if (!file) throw new Error("the player page has changed (no file id)");
    const lane = /[?&]s=([A-Za-z0-9_-]+)/.exec(playerUrl);
    const saved = this.apiHeaders;
    let data;
    try {
      this.apiHeaders = { Referer: playerUrl, "X-Requested-With": "XMLHttpRequest" };
      data = await this._api(origin + "/stream/getSources?id=" + file[1] + (lane ? "&s=" + lane[1] : ""));
    } finally {
      this.apiHeaders = saved;
    }

    let video = "";
    const plain = data && data.sources;
    if (plain && typeof plain.file === "string") video = plain.file;
    else if (Array.isArray(plain) && plain[0] && typeof plain[0].file === "string") video = plain[0].file;
    else if (data && typeof data.enc === "string" && data.enc) {
      const opened = this._megaPlayOpen(data.enc);
      if (opened && typeof opened.file === "string") video = opened.file;
      else if (opened && opened.sources && typeof opened.sources.file === "string") video = opened.sources.file;
    }
    if (!/^https?:\/\//i.test(video)) throw new Error("the player names no video");

    const subtitles = this._subtitles((data && Array.isArray(data.tracks) ? data.tracks : []).map(function (track) {
      if (!track || (track.kind && track.kind !== "captions" && track.kind !== "subtitles")) return null;
      return { url: track.file, label: track.label, isDefault: track.default === true };
    }));
    return { url: video, referer: origin + "/", subtitles: subtitles, skip: this._skip(data.intro, data.outro) };
  }

  // AES-256-CBC with the key and IV the player's own script uses (text, zero-padded).
  _megaPlayOpen(enc) {
    if (typeof CryptoJS === "undefined") throw new Error("this host has no CryptoJS to open the MegaPlay answer");
    const padded = function (text, size) {
      const bytes = new Uint8Array(size);
      for (let i = 0; i < Math.min(size, text.length); i += 1) bytes[i] = text.charCodeAt(i);
      return bytes;
    };
    let base64 = String(enc).replace(/-/g, "+").replace(/_/g, "/");
    while (base64.length % 4 !== 0) base64 += "=";
    try {
      const opened = CryptoJS.AES.decrypt(base64, padded(this.megaPlayKey, 32), { iv: padded(this.megaPlayIv, 16) });
      return JSON.parse(String(opened.toString(CryptoJS.enc.Utf8)));
    } catch (error) {
      return null;
    }
  }

  // The body of a 2xx answer.
  async _page(url, referer) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: { Referer: referer } });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return String(await response.text());
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // A JSON answer of the site's API. `init` may carry `method` and `body`.
  async _api(url, init) {
    const host = this._host(url);
    const headers = { Accept: "application/json" };
    for (const name of Object.keys(this.apiHeaders || {})) headers[name] = this.apiHeaders[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/json";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // `listed`: [{ url, label, isDefault }].
  _subtitles(listed) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !/^https?:\/\//i.test(entry.url)) continue;
      if (subtitles.some(function (s) { return s.url === entry.url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: entry.url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // Intro and outro as { start, end } in seconds.
  _skip(intro, outro) {
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const first = part(intro);
    const last = part(outro);
    if (!first && !last) return null;
    const skip = {};
    if (first) {
      skip.introStart = first.start;
      skip.introEnd = first.end;
    }
    if (last) {
      skip.outroStart = last.start;
      skip.outroEnd = last.end;
    }
    return skip;
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// AniLab (the service behind the AniLab and AniDB apps): sub and dub as HLS through its JSON API.
// API as used by the Aniyomi sources (github.com/yuzono/anime-extensions, src/en/anidb, and
// github.com/salmanbappi/sb-extensions-source, src/en/anilab).

class Provider {
  constructor() {
    this.catalog = "https://anilab2.amdapi.click/api";
    this.player = "https://play.anidb.app/api";
    this.site = "https://anilab.so";
    this.apiHeaders = {};
    // Search answers with ids only; this many hits are looked up for their titles.
    this.maxHits = 12;
  }

  getSettings() {
    return {
      episodeServers: ["AniLab"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    for (const query of queries) {
      const found = await this._api(this.catalog + "/search?query=" + encodeURIComponent(query) + "&page=1");
      const ids = [];
      for (const post of found && Array.isArray(found.posts) ? found.posts : []) {
        if (post && typeof post.id === "number" && ids.indexOf(post.id) < 0) ids.push(post.id);
      }
      if (ids.length === 0) continue;

      const self = this;
      const looked = await Promise.all(ids.slice(0, this.maxHits).map(function (postId) {
        return self._api(self.catalog + "/post?id=" + postId).then(
          function (post) { return { post: post }; },
          function (error) { return { error: error }; });
      }));
      const results = [];
      for (const entry of looked) {
        const post = entry.post;
        if (!post || typeof post.id !== "number" || !this._text(post.title)) continue;
        const year = /(\d{4})/.exec(this._text(post.premiered));
        results.push({
          id: post.id + "|" + audio,
          title: this._text(post.title),
          url: this.site + "/",
          subOrDub: audio,
          year: year ? parseInt(year[1], 10) : undefined,
        });
      }
      if (results.length > 0) return results;
      const failed = looked.filter(function (entry) { return entry.error; })[0];
      if (failed) throw failed.error;
    }
    return [];
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const animeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(animeId)) throw new Error("invalid anime id '" + id + "'");

    const data = await this._api(this.player + "/anime/" + animeId + "/episodes");
    const episodes = [];
    const seen = {};
    for (const item of data && Array.isArray(data.list) ? data.list : []) {
      const number = item ? Number(item.number) : NaN;
      if (!item || !/^\d+$/.test(String(item.id)) || !isFinite(number) || seen[number]) continue;
      seen[number] = true;
      const episode = {
        id: item.id + "|" + audio,
        number: number,
        url: this.site + "/",
        title: this._text(item.name) || "Episode " + number,
      };
      if (item.filler === true) episode.filler = true;
      episodes.push(episode);
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const episodeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(episodeId || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "anilab") throw new Error("unknown server '" + wanted + "'");

    // One entry per audio version and mirror: { id: "3512/jpn", lang: "sub", name: "SUB Server #1" }.
    const data = await this._api(this.player + "/episode/" + episodeId + "/servers");
    const listed = (data && Array.isArray(data.list) ? data.list : []).filter(function (entry) {
      return entry && typeof entry.id === "string" && /^\d+\/[a-z]+$/i.test(entry.id);
    });
    if (listed.length === 0) throw new Error("no server listed for this episode");
    const tracks = this._distinct(listed
      .filter(function (entry) { return String(entry.lang || "").toLowerCase() === audio; })
      .map(function (entry) { return entry.id; }));
    if (tracks.length === 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");

    let reason = null;
    for (const track of tracks) {
      try {
        const answer = await this._api(this.player + "/episode/" + track + "/iframe");
        const url = answer && typeof answer.link === "string" ? answer.link : "";
        if (!/^https?:\/\//i.test(url)) {
          reason = reason || "the server names no video";
          continue;
        }
        return {
          server: "AniLab",
          headers: {},
          videoSources: [
            { url: url, type: this._isHls(url) ? "m3u8" : "mp4", quality: "auto", label: audio === "dub" ? "Dub" : "Sub", subtitles: [] },
          ],
        };
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // A JSON answer of the site's API. `init` may carry `method` and `body`.
  async _api(url, init) {
    const host = this._host(url);
    const headers = { Accept: "application/json" };
    for (const name of Object.keys(this.apiHeaders || {})) headers[name] = this.apiHeaders[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/json";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // `listed`: [{ url, label, isDefault }].
  _subtitles(listed) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !/^https?:\/\//i.test(entry.url)) continue;
      if (subtitles.some(function (s) { return s.url === entry.url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: entry.url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // Intro and outro as { start, end } in seconds.
  _skip(intro, outro) {
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const first = part(intro);
    const last = part(outro);
    if (!first && !last) return null;
    const skip = {};
    if (first) {
      skip.introStart = first.start;
      skip.introEnd = first.end;
    }
    if (last) {
      skip.outroStart = last.start;
      skip.outroEnd = last.end;
    }
    return skip;
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// Anidap (anidap.lol): sub and dub from up to five upstream hosts, found by AniList id. HLS,
// most with soft subtitles and intro/outro times.
// API as used by the Mangayomi source (github.com/Mallyd11/mangayomi-anime-extensions).

class Provider {
  constructor() {
    this.site = "https://anidap.lol";
    this.api = "https://chad.anidap.lol/rest/api";
    // Maps an AniList id to the site's id of the anime.
    this.embed = "https://aniembed.se";
    this.apiHeaders = { Origin: this.site, Referer: this.site + "/" };
    this.servers = ["Nero", "Yuki", "Zuna", "Sora", "Loli"];
  }

  getSettings() {
    return {
      episodeServers: ["Nero", "Yuki", "Zuna", "Sora", "Loli"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const media = (opts && opts.media) || {};
    const audio = opts && opts.dub ? "dub" : "sub";
    let entry = null;
    if (typeof media.id === "number" && media.id > 0) {
      entry = {
        id: media.id,
        titles: this._distinct([this._text(media.romajiTitle), this._text(media.englishTitle), this._text(opts && opts.query)]),
        year: media.startDate && typeof media.startDate.year === "number" ? media.startDate.year : undefined,
        count: typeof media.episodeCount === "number" && media.episodeCount > 0 ? media.episodeCount : undefined,
      };
    } else {
      const queries = this._queries(opts);
      if (queries.length === 0) throw new Error("no title to search for");
      entry = await this._anilist(queries[0]);
    }
    if (!entry || entry.titles.length === 0) return [];

    const slug = await this._slug(entry.id);
    if (!slug) return [];
    return [
      {
        id: slug + "|" + audio,
        title: entry.titles[0],
        url: this.site + "/watch/" + slug,
        subOrDub: audio,
        altTitles: entry.titles.slice(1),
        year: entry.year,
        episodeCount: entry.count,
      },
    ];
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!slug) throw new Error("invalid anime id '" + id + "'");

    const listed = await this._api(this.api + "/episodes?id=" + encodeURIComponent(slug));
    const episodes = [];
    const seen = {};
    for (const item of Array.isArray(listed) ? listed : []) {
      if (!item || typeof item.number !== "number" || seen[item.number]) continue;
      seen[item.number] = true;
      const titles = item.titles && typeof item.titles === "object" ? item.titles : {};
      const episode = {
        id: slug + "|" + item.number + "|" + audio,
        number: item.number,
        url: this.site + "/watch/" + slug + "?ep=" + item.number,
        title: this._text(titles.en) || this._text(titles["x-jat"]) || "Episode " + item.number,
      };
      if (typeof item.image === "string" && /^https:\/\//.test(item.image)) episode.image = item.image;
      episodes.push(episode);
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const number = parts[1];
    const audio = parts[2] === "dub" ? "dub" : "sub";
    if (!slug || !/^\d+(\.\d+)?$/.test(number || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const query = "id=" + encodeURIComponent(slug) + "&epNum=" + number;
    const listed = await this._api(this.api + "/servers?" + query);
    const offered = ((listed && listed[audio === "dub" ? "dubProviders" : "subProviders"]) || [])
      .map(function (provider) { return provider && typeof provider.id === "string" ? provider.id.toLowerCase() : ""; })
      .filter(function (name) { return name; });
    if (offered.length === 0) {
      const other = (listed && listed[audio === "dub" ? "subProviders" : "dubProviders"]) || [];
      if (other.length > 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");
      throw new Error("no server listed for this episode");
    }

    // "default" tries what the episode offers in the order of `servers`.
    const order = (wanted === "default" ? known : [wanted])
      .map(function (name) { return name.toLowerCase(); })
      .filter(function (name) { return offered.indexOf(name) >= 0; });
    if (order.length === 0) throw new Error("'" + wanted + "' is not offered for this episode (offered: " + offered.join(", ") + ")");

    let reason = null;
    for (const provider of order) {
      try {
        const data = await this._api(this.api + "/sources?" + query + "&type=" + audio + "&providerId=" + provider);
        const result = this._result(provider, data, audio);
        if (result) return result;
        reason = reason || provider + " has no video for this episode";
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- parsing

  // A sources answer: { sources: [{ url, quality }], tracks: [{ url, label, kind, default }],
  // chapters: [{ title: "Intro" | "Outro", start, end }], headers }.
  _result(provider, data, audio) {
    const self = this;
    const usable = [];
    for (const source of data && Array.isArray(data.sources) ? data.sources : []) {
      const url = source ? this._fixUrl(source.url) : "";
      if (url) usable.push({ url: url, quality: source.quality, type: source.type });
    }
    if (usable.length === 0) return null;

    const headers = {};
    const given = data.headers && typeof data.headers === "object" ? data.headers : {};
