// AnimeWorld (animeworld.ac): Italian subtitles (burnt in) and Italian dub as direct MP4
// files. Dubs are separate entries of the site, named "… (ITA)". Reference for the site's
// pages and its episode API: the Aniyomi extension src/it/animeworld
// (github.com/yuzono/anime-extensions).

class Provider {
  constructor() {
    this.base = "https://www.animeworld.ac";
    this.apiHeaders = { "X-Requested-With": "XMLHttpRequest" };
  }

  getSettings() {
    return {
      episodeServers: ["AnimeWorld"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/search?keyword=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
      // One result: <div class="item"> … <div class="dub">DUB</div> …
      // <a href="/play/slug.id" data-jtitle="Romaji (ITA)" class="name">Title (ITA)</a>
      const items = html.split(/<div class="item">/).slice(1);
      for (const item of items) {
        const link = /<a\b[^>]*\bclass="name"[^>]*>([\s\S]*?)<\/a>/.exec(item);
        if (!link) continue;
        const tag = link[0].slice(0, link[0].indexOf(">") + 1);
        const path = /^\/play\/([^"\/?#]+)/.exec(this._attr(tag, "href"));
        const shown = this._plain(link[1]);
        if (!path || !shown || results.some(function (r) { return r.id.split("|")[0] === path[1]; })) continue;
        const isDub = /<div class="dub">/.test(item.slice(0, link.index)) || /\(ITA\)\s*$/i.test(shown);
        if (isDub !== (audio === "dub")) continue;
        const strip = function (text) { return text.replace(/\s*\(ITA\)\s*$/i, "").trim(); };
        const title = strip(shown) || shown;
        const romaji = strip(this._attr(tag, "data-jtitle"));
        results.push({
          id: path[1] + "|" + audio,
          title: title,
          url: this.base + "/play/" + path[1],
          subOrDub: audio,
          altTitles: this._distinct([romaji !== title ? romaji : "", shown !== title ? shown : ""]),
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[\w.-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    const html = await this._page(this.base + "/play/" + slug, this.base + "/");
    // One entry: <a data-episode-id="59327" data-id="HPKmX1" data-episode-num="1" … href="/play/slug.id/HPKmX1">
    const episodes = [];
    const seen = {};
    const re = /<a\b[^>]*\bdata-episode-num="[^"]*"[^>]*>/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      const token = this._attr(match[0], "data-id");
      const numbered = /^(\d+(?:\.\d+)?)/.exec(this._attr(match[0], "data-episode-num"));
      if (!/^[\w-]+$/.test(token) || !numbered || seen[numbered[1]]) continue;
      seen[numbered[1]] = true;
      episodes.push({
        id: [slug, audio, token].join("|"),
        number: Number(numbered[1]),
        url: this.base + "/play/" + slug + "/" + token,
        title: "Episode " + numbered[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    const token = parts[2];
    if (!slug || !/^[\w-]+$/.test(token || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "animeworld") throw new Error("unknown server '" + wanted + "'");

    const watchUrl = this.base + "/play/" + slug + "/" + token;
    const info = await this._api(this.base + "/api/episode/info?id=" + encodeURIComponent(token) + "&alt=0", { headers: { Referer: watchUrl } });
