    if (!/^https?:\/\//i.test(video)) throw new Error("the site names no video for this episode");

    return {
      server: "AnimeWorld",
      headers: { Referer: this.base + "/" },
      videoSources: [
        {
          url: video,
          type: this._isHls(video) ? "m3u8" : "mp4",
          quality: "auto",
          label: audio === "dub" ? "Italian dub" : "Italian hard sub",
          subtitles: [],
