    this.base = "https://zanix.tr";
    this.player = "https://novuscloud.buzz";
    this.servers = ["ReCloud HD", "ReCloud 1", "ReCloud 2"];
  }

  getSettings() {
    return {
      episodeServers: ["ReCloud HD", "ReCloud 1", "ReCloud 2"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/search?keyword=" + encodeURIComponent(query), this.base + "/");
      // One card: <div class="flw-item"> … <a class="film-poster-ahref" href="/one-piece-12" title="One Piece">
      for (const card of html.split('class="flw-item"').slice(1)) {
        const link = /<a\s[^>]*class="film-poster-ahref"[^>]*>/.exec(card);
        const slug = link ? this._attr(link[0], "href").replace(/^\//, "") : "";
        if (!/^[a-z0-9-]+-\d+$/.test(slug)) continue;
        if (results.some(function (r) { return r.id.split("|")[0] === slug; })) continue;
        const title = this._text(this._attr(link[0], "title"));
        if (!title) continue;
        results.push({ id: slug + "|" + audio, title: title, url: this.base + "/" + slug, subOrDub: audio });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[a-z0-9-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    // The watch page names the anime's number and a token for its session; the episode list
    // answers only with both and the session cookie.
    const watchUrl = this.base + "/watch/" + slug;
    let response;
    try {
      response = await fetch(watchUrl, { headers: { Referer: this.base + "/" } });
    } catch (error) {
      throw new Error(this._host(watchUrl) + " unreachable (" + this._errorText(error) + ")");
    }
    const html = String(await response.text());
    if (!response.ok) throw new Error(this._looksLikeChallenge(html) ? "blocked by the site's bot protection" : "HTTP " + response.status + " from " + this._host(watchUrl));
    const animeId = /\banimeId\s*=\s*(\d+)/.exec(html);
    const token = /window\.AJAX_TOKEN\s*=\s*"([^"]+)"/.exec(html);
    if (!animeId || !token) throw new Error("the watch page has changed (no anime id or token)");
    const headers = { "X-Page-Token": token[1], "X-Requested-With": "XMLHttpRequest", Referer: watchUrl };
    const cookie = this._cookieHeader(response);
    if (cookie) headers.Cookie = cookie;
    const data = await this._api(this.base + "/ajax/episodes?animeId=" + animeId[1], { headers: headers });
    const listed = data && data.episodes;
    if (!Array.isArray(listed) || listed.length === 0) throw new Error("no episodes listed");

    const episodes = [];
    const seen = {};
    for (const item of listed) {
      if (!item || typeof item.number !== "number" || seen[item.number]) continue;
      if (item[audio] !== true) continue;
      seen[item.number] = true;
      const titles = item.titles && typeof item.titles === "object" ? item.titles : {};
      const episode = {
        // slug | audio | number | episode id | player id | AniList id/number
        id: [slug, audio, item.number, item.id, item.embed_id || "", typeof item.ani === "string" ? item.ani : ""].join("|"),
        number: item.number,
        url: this.base + "/watch/" + slug + "?ep=" + item.number,
        title: this._text(titles.en) || this._text(titles.romaji) || "Episode " + item.number,
      };
      if (typeof item.thumbnail === "string" && /^https:\/\//.test(item.thumbnail)) episode.image = item.thumbnail;
      if (item.filler === true) episode.filler = true;
      episodes.push(episode);
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error(audio === "dub" ? "no dub" : "no subbed episodes");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    const episodeId = parts[3];
    const playerId = parts[4];
    const aniEpisode = /^\d+\/\d+$/.test(parts[5] || "") ? parts[5] : "";
    if (!slug || !/^\d+$/.test(episodeId || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const paths = {
      "recloud 1": "/embed/hd-1/" + episodeId + "/" + audio + "?k=1",
      "recloud 2": aniEpisode ? "/embed/hd-2/ani/" + aniEpisode + "/" + audio + "?k=1" : "",
      "recloud hd": playerId ? "/embed/s-1/" + encodeURIComponent(playerId) + "/" + audio + "?k=1" : "",
    };
    const order = wanted === "default" ? known : [wanted];
    let reason = null;
    for (const name of order) {
      const path = paths[name.toLowerCase()];
      if (!path) {
        reason = reason || "'" + name + "' is not offered for this episode";
        continue;
      }
      try {
        return await this._player(known.filter(function (k) { return k.toLowerCase() === name.toLowerCase(); })[0], this.player + path, audio);
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- players

  // A player page names the address of its sources; that answers with the playlist, the
  // subtitle tracks and the intro/outro times, all as addresses on the player's host.
  async _player(name, embedUrl, audio) {
    const page = await this._page(embedUrl, this.base + "/");
    const named = /var\s+sourcesUrl\s*=\s*['"]([^'"]+)['"]/.exec(page);
    if (!named) throw new Error("the player page has changed (no sources address)");
    const data = await this._api(this._absolute(named[1], this.player), { headers: { Referer: embedUrl } });
    if (data && data.error) throw new Error(this._text(String(data.error)) || "the player reports an error");

    let file = "";
    if (data && Array.isArray(data.sources) && data.sources[0] && typeof data.sources[0].file === "string") file = data.sources[0].file;
    else if (data && data.link && typeof data.link.file === "string") file = data.link.file;
    else if (data && typeof data.file === "string") file = data.file;
    if (!file) throw new Error("the player names no video");

    const self = this;
    const listed = (data && Array.isArray(data.tracks) ? data.tracks : []).map(function (track) {
      if (!track || typeof track.file !== "string" || (track.kind !== "captions" && track.kind !== "subtitles")) return null;
      return { url: self._absolute(track.file, self.player), label: track.label, isDefault: track.default === true };
    });
    const subtitles = this._subtitles(listed);
    const result = {
      server: name,
      headers: { Referer: embedUrl },
      videoSources: [
        {
          url: this._absolute(file, this.player),
          type: "m3u8",
          quality: "auto",
          label: audio === "dub" ? "Dub" : subtitles.length > 0 ? "Soft sub" : "Sub",
          subtitles: subtitles,
        },
      ],
    };
    const skip = this._skip(data.intro, data.outro);
    if (skip) result.skip = skip;
    return result;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // A JSON answer of the site's API. `init` may carry `method`, `body` and extra `headers`.
  async _api(url, init) {
    const host = this._host(url);
    const headers = { Accept: "application/json" };
    for (const name of Object.keys(this.apiHeaders || {})) headers[name] = this.apiHeaders[name];
    for (const name of Object.keys((init && init.headers) || {})) headers[name] = init.headers[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/json";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  // The cookies a response set, as a request's Cookie header.
  _cookieHeader(response) {
    const pairs = [];
    if (response.cookies && typeof response.cookies === "object") {
      for (const name of Object.keys(response.cookies)) pairs.push(name + "=" + response.cookies[name]);
    }
    if (pairs.length === 0 && response.headers) {
      const raw = typeof response.headers.get === "function" ? response.headers.get("set-cookie") : response.headers["set-cookie"];
      for (const cookie of String(raw || "").split(/,\s*(?=[\w.-]+=)/)) {
        const first = cookie.split(";")[0].trim();
        if (first.indexOf("=") > 0) pairs.push(first);
      }
    }
    return pairs.join("; ");
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // `listed`: [{ url, label, isDefault }].
  _subtitles(listed) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !/^https?:\/\//i.test(entry.url)) continue;
      if (subtitles.some(function (s) { return s.url === entry.url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: entry.url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // Intro and outro as { start, end } in seconds.
  _skip(intro, outro) {
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const first = part(intro);
    const last = part(outro);
    if (!first && !last) return null;
    const skip = {};
    if (first) {
      skip.introStart = first.start;
      skip.introEnd = first.end;
    }
    if (last) {
      skip.outroStart = last.start;
      skip.outroEnd = last.end;
    }
    return skip;
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page of a site as text. `referer` is a URL, or an object of request headers.
  async _page(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }

  // ---------------------------------------------------------------- video hosts

  // A Blogger video (blogger.com/video.g?token=…): its MP4 files, best first, as
  // [{ url, quality }]. The page names them itself or through the player's data request.
  async _blogger(url, referer) {
    const page = await this._page(url, referer);
    const found = [];
    const add = function (address, itag) {
      const quality = { 18: "360p", 22: "720p", 37: "1080p", 59: "480p" }[itag];
      if (!quality || !/^https:\/\//.test(address) || found.some(function (f) { return f.quality === quality; })) return;
      found.push({ url: address, quality: quality });
    };

    const listed = /"streams":\[([\s\S]*?)\]/.exec(page);
    if (listed && page.indexOf("errorContainer") < 0) {
      const re = /"play_url":"([^"]+)"[^}]*?"format_id":(\d+)/g;
      let match;
      while ((match = re.exec(listed[1])) !== null) add(this._unescapeBody(match[1]), parseInt(match[2], 10));
    }
    if (found.length === 0) {
      const token = /[?&]token=([^&#]+)/.exec(url);
      const session = /"FdrFJe":"([^"]+)"/.exec(page);
      const build = /"cfb2h":"([^"]+)"/.exec(page);
      if (!token || !session || !build) throw new Error("the Blogger video page has changed");
      const origin = this._origin(url);
      const request = JSON.stringify([[["WcwnYd", JSON.stringify([token[1], "", 0]), null, "generic"]]]);
      const answer = await this._page(
        origin + "/_/BloggerVideoPlayerUi/data/batchexecute?rpcids=WcwnYd&source-path=%2Fvideo.g&f.sid=" + encodeURIComponent(session[1]) +
          "&bl=" + encodeURIComponent(build[1]) + "&hl=en-US&_reqid=" + (Math.floor(Date.now() / 1000) % 86400) + "&rt=c",
        { Referer: origin + "/", "x-same-domain": "1" },
        { method: "POST", body: "f.req=" + encodeURIComponent(request) + "&", contentType: "application/x-www-form-urlencoded;charset=UTF-8" }
      );
      for (const line of answer.split("\n")) {
        if (line.indexOf('[["wrb.fr"') !== 0) continue;
        let streams = null;
        try {
          streams = JSON.parse(JSON.parse(line)[0][2])[2];
        } catch (error) {
          streams = null;
        }
        for (const stream of Array.isArray(streams) ? streams : []) {
          if (Array.isArray(stream) && typeof stream[0] === "string" && Array.isArray(stream[1])) add(stream[0], stream[1][0]);
        }
      }
    }
    if (found.length === 0) throw new Error("the Blogger video is not available");
    found.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return found;
  }
}

// Oploverz (oploverz.xin): Indonesian subtitles (burnt in) as MP4 files hosted on Blogger,
// through the site's JSON API. Reference for the API: the Aniyomi extension src/id/oploverz
// (github.com/yuzono/anime-extensions).

class Provider {
  constructor() {
    this.site = "https://oploverz.xin";
    this.api = "https://backapi.oploverz.ac/api";
    this.apiHeaders = { Referer: this.site + "/", Origin: this.site };
  }

  getSettings() {
    return {
      episodeServers: ["Blogger"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // The site carries Indonesian-subtitled releases only.
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const results = [];
    for (const query of queries) {
      const found = await this._api(this.api + "/series?page=1&pageSize=24&q=" + encodeURIComponent(query));
      for (const item of found && Array.isArray(found.data) ? found.data : []) {
        if (!item || typeof item.slug !== "string" || !item.slug) continue;
        if (results.some(function (r) { return r.id === item.slug; })) continue;
        // Seasons are named "… S2"; the first one "… S1".
        const shown = this._text(item.title);
        const title = shown.replace(/\s+S1$/i, "").replace(/\s+S(\d+)$/i, " Season $1");
        if (!title) continue;
        results.push({
          id: item.slug,
          title: title,
          url: this.site + "/series/" + item.slug,
          subOrDub: "sub",
          altTitles: this._distinct([this._text(item.japaneseTitle), shown !== title ? shown : ""]),
          format: this._text(item.releaseType) || undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const slug = String(id);
    if (!/^[\w-]+$/.test(slug)) throw new Error("invalid anime id '" + id + "'");

    const listed = await this._api(this.api + "/series/" + slug + "/episodes?pageSize=3000");
    const episodes = [];
    const seen = {};
    for (const item of listed && Array.isArray(listed.data) ? listed.data : []) {
      const number = Number(item && item.episodeNumber);
      if (!item || !isFinite(number) || String(item.episodeNumber).trim() === "" || seen[number]) continue;
      seen[number] = true;
      episodes.push({
        id: slug + "|" + String(item.episodeNumber).trim(),
        number: number,
        url: this.site + "/series/" + slug + "/episode/" + String(item.episodeNumber).trim(),
        title: this._text(item.title) || "Episode " + number,
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const number = parts[1];
    if (!/^[\w-]+$/.test(slug || "") || !/^[\w.-]+$/.test(number || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "blogger") throw new Error("unknown server '" + wanted + "'");

    const found = await this._api(this.api + "/series/" + slug + "/episodes/" + encodeURIComponent(number));
    const streams = found && found.data && Array.isArray(found.data.streamUrl) ? found.data.streamUrl : [];
    if (streams.length === 0) throw new Error("the site has no player for this episode");

    const self = this;
    const hosted = streams.filter(function (stream) {
      return stream && typeof stream.url === "string" && /^https:\/\/[^\/]*blogger\.com\/video\.g\?/.test(stream.url);
    });
    if (hosted.length === 0) {
      const hosts = this._distinct(streams.map(function (stream) { return self._host(stream && stream.url); }));
      throw new Error("no supported player for this episode (offered: " + hosts.join(", ") + ")");
    }

    let reason = null;
    const videoSources = [];
    for (const stream of hosted.slice(0, 4)) {
      try {
        for (const file of await this._blogger(stream.url, this.site + "/")) {
          if (videoSources.some(function (v) { return v.quality === file.quality; })) continue;
          videoSources.push({ url: file.url, type: "mp4", quality: file.quality, label: "Indonesian hard sub", subtitles: [] });
        }
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    if (videoSources.length === 0) throw new Error(reason || "no playable source for this episode");
    videoSources.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return { server: "Blogger", headers: {}, videoSources: videoSources };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // A JSON answer of the site's API. `init` may carry `method`, `body` and extra `headers`.
  async _api(url, init) {
    const host = this._host(url);
    const headers = { Accept: "application/json" };
    for (const name of Object.keys(this.apiHeaders || {})) headers[name] = this.apiHeaders[name];
    for (const name of Object.keys((init && init.headers) || {})) headers[name] = init.headers[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/json";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // `listed`: [{ url, label, isDefault }].
  _subtitles(listed) {
    const subtitles = [];
    let hasDefault = false;
    for (const entry of listed) {
      if (!entry || typeof entry.url !== "string" || !/^https?:\/\//i.test(entry.url)) continue;
      if (subtitles.some(function (s) { return s.url === entry.url; })) continue;
      const isDefault = entry.isDefault === true && !hasDefault;
      if (isDefault) hasDefault = true;
      const language = String(entry.label || "Unknown");
      subtitles.push({ id: language.toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: entry.url, language: language, isDefault: isDefault });
    }
    return subtitles;
  }

  // Intro and outro as { start, end } in seconds.
  _skip(intro, outro) {
    const part = function (entry) {
      if (!entry || typeof entry.start !== "number" || typeof entry.end !== "number") return null;
      return entry.end > entry.start && entry.start >= 0 ? entry : null;
    };
    const first = part(intro);
    const last = part(outro);
    if (!first && !last) return null;
    const skip = {};
    if (first) {
      skip.introStart = first.start;
      skip.introEnd = first.end;
    }
    if (last) {
      skip.outroStart = last.start;
      skip.outroEnd = last.end;
    }
    return skip;
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page of a site as text. `referer` is a URL, or an object of request headers.
  async _page(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  // `www.example.to` and `example.tv` are the same site.
  _sameSite(a, b) {
    const label = function (host) {
      const parts = host.toLowerCase().replace(/^www\./, "").split(".");
      return parts.length > 1 ? parts[parts.length - 2] : parts[0];
    };
    return label(a) === label(b);
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The JSON value that starts at `index` of `text` (an object or an array), or null.
  _jsonAt(text, index) {
    const open = text.charAt(index);
    const close = open === "{" ? "}" : open === "[" ? "]" : "";
    if (!close) return null;
    let depth = 0;
    let quoted = false;
    for (let i = index; i < text.length; i += 1) {
      const c = text.charAt(i);
      if (quoted) {
        if (c === "\\") i += 1;
        else if (c === '"') quoted = false;
      } else if (c === '"') quoted = true;
      else if (c === "{" || c === "[") depth += 1;
      else if (c === "}" || c === "]") {
        depth -= 1;
        if (depth === 0) {
          try {
            return JSON.parse(text.slice(index, i + 1));
          } catch (error) {
            return null;
          }
        }
      }
    }
    return null;
  }

  // The data a Next.js page carries in its `self.__next_f.push([1,"…"])` calls, as one text.
  _nextPayload(html) {
    const re = /self\.__next_f\.push\(\[1,\s*("(?:[^"\\]|\\[\s\S])*")\]\)/g;
    let text = "";
    let match;
    while ((match = re.exec(html)) !== null) {
      try {
        text += JSON.parse(match[1]);
      } catch (error) {
        continue;
      }
    }
    return text;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }

  // ---------------------------------------------------------------- video hosts

  // A Blogger video (blogger.com/video.g?token=…): its MP4 files, best first, as
  // [{ url, quality }]. The page names them itself or through the player's data request.
  async _blogger(url, referer) {
    const page = await this._page(url, referer);
    const found = [];
    const add = function (address, itag) {
      const quality = { 18: "360p", 22: "720p", 37: "1080p", 59: "480p" }[itag];
      if (!quality || !/^https:\/\//.test(address) || found.some(function (f) { return f.quality === quality; })) return;
      found.push({ url: address, quality: quality });
    };

    const listed = /"streams":\[([\s\S]*?)\]/.exec(page);
    if (listed && page.indexOf("errorContainer") < 0) {
      const re = /"play_url":"([^"]+)"[^}]*?"format_id":(\d+)/g;
      let match;
      while ((match = re.exec(listed[1])) !== null) add(this._unescapeBody(match[1]), parseInt(match[2], 10));
    }
    if (found.length === 0) {
      const token = /[?&]token=([^&#]+)/.exec(url);
      const session = /"FdrFJe":"([^"]+)"/.exec(page);
      const build = /"cfb2h":"([^"]+)"/.exec(page);
      if (!token || !session || !build) throw new Error("the Blogger video page has changed");
      const origin = this._origin(url);
      const request = JSON.stringify([[["WcwnYd", JSON.stringify([token[1], "", 0]), null, "generic"]]]);
      const answer = await this._page(
        origin + "/_/BloggerVideoPlayerUi/data/batchexecute?rpcids=WcwnYd&source-path=%2Fvideo.g&f.sid=" + encodeURIComponent(session[1]) +
          "&bl=" + encodeURIComponent(build[1]) + "&hl=en-US&_reqid=" + (Math.floor(Date.now() / 1000) % 86400) + "&rt=c",
        { Referer: origin + "/", "x-same-domain": "1" },
        { method: "POST", body: "f.req=" + encodeURIComponent(request) + "&", contentType: "application/x-www-form-urlencoded;charset=UTF-8" }
      );
      for (const line of answer.split("\n")) {
        if (line.indexOf('[["wrb.fr"') !== 0) continue;
        let streams = null;
        try {
          streams = JSON.parse(JSON.parse(line)[0][2])[2];
        } catch (error) {
          streams = null;
        }
        for (const stream of Array.isArray(streams) ? streams : []) {
          if (Array.isArray(stream) && typeof stream[0] === "string" && Array.isArray(stream[1])) add(stream[0], stream[1][0]);
        }
      }
    }
    if (found.length === 0) throw new Error("the Blogger video is not available");
    found.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return found;
  }
}

// Aniwaves (aniwaves.ru): English subbed and English dubbed anime as HLS. The subbed streams carry
// the subtitles in the picture. Video comes from the site's Vidplay player (play.echovideo.ru).

class Provider {
  constructor() {
    this.base = "https://aniwaves.ru";
    this.servers = ["Vidplay"];
  }

  getSettings() {
    return {
      episodeServers: ["Vidplay"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    let failure = null;
    for (const query of queries) {
      const self = this;
      // The filter page lists every hit with its sub and dub counts; the quick search adds the
      // air dates of the best hits.
      const answers = await Promise.all([
        this._page(this.base + "/filter?keyword=" + encodeURIComponent(query)).then(
          function (html) { return { html: html }; }, function (error) { return { error: error }; }),
        this._json(this.base + "/ajax/anime/search?keyword=" + encodeURIComponent(query), this.base + "/").then(
          function (data) { return { data: data }; }, function (error) { return { error: error }; }),
      ]);
      const listed = answers[0].html ? this._filterItems(answers[0].html) : [];
      const quick = answers[1].data ? this._quickItems(answers[1].data) : [];
      if (answers[0].error && answers[1].error) {
        failure = failure || answers[0].error;
        continue;
      }

      const results = [];
      const add = function (item) {
        if (results.some(function (r) { return r.animeId === item.animeId; })) return;
        results.push(item);
      };
      for (const item of listed) add(item);
      for (const item of quick) {
        const known = results.filter(function (r) { return r.animeId === item.animeId; })[0];
        if (known) {
          if (item.year && !known.year) known.year = item.year;
        } else {
          add(item);
        }
      }

      const out = [];
      for (const item of results) {
        if (audio === "dub" && item.dub === 0) continue;
        const count = audio === "dub" ? item.dub : item.sub;
        const entry = {
          id: item.animeId + "|" + audio,
          title: item.title || item.other,
          url: this.base + "/watch/" + item.slug,
          subOrDub: audio,
          altTitles: item.title && item.other && item.other !== item.title ? [item.other] : [],
        };
        if (item.year) entry.year = item.year;
        if (count) entry.episodeCount = count;
        out.push(entry);
      }
      if (out.length > 0) return out;
    }
    if (failure) throw failure;
    return [];
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const animeId = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+$/.test(animeId || "")) throw new Error("invalid anime id '" + id + "'");

    const data = await this._json(this.base + "/ajax/episode/list/" + animeId, this.base + "/");
    const html = data && typeof data.result === "string" ? data.result : "";
    // One entry: <a href="/watch/74575/ep-1" data-ids="74575&amp;eps=1" data-num="1" data-sub="1" data-dub="1" ...>
    //   <b>1</b><span class="d-title" data-jp="...">The Journey's End</span>
    const episodes = [];
    const seen = {};
    let listed = 0;
    const entries = html.split(/<a\s+(?=[^>]*\bdata-ids=)/).slice(1);
    for (const entry of entries) {
      const tag = entry.slice(0, entry.indexOf(">"));
      const ids = /\bdata-ids="([^"]+)"/.exec(tag);
      const number = /\bdata-num="(\d+(?:\.\d+)?)"/.exec(tag);
      if (!ids || !number) continue;
      listed += 1;
      const has = new RegExp("\\bdata-" + audio + '="1"').test(tag);
      if (!has || seen[number[1]]) continue;
      seen[number[1]] = true;
      const href = /\bhref="([^"]+)"/.exec(tag);
      const named = /class="d-title"[^>]*>([^<]*)</.exec(entry);
      const title = named ? this._plain(named[1]) : "";
      episodes.push({
        id: this._unescapeBody(ids[1]) + "|" + audio,
        number: Number(number[1]),
        url: href ? this.base + this._unescapeBody(href[1]) : this.base + "/",
        title: title || "Episode " + number[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) {
      if (listed > 0) throw new Error(audio === "dub" ? "no dub for this anime" : "no subbed episodes for this anime");
      throw new Error("no episodes listed");
    }
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const ids = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^\d+&eps=[\w.-]+$/.test(ids || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const known = this.servers;
    if (wanted !== "default" && !known.some(function (name) { return name.toLowerCase() === wanted.toLowerCase(); })) {
      throw new Error("unknown server '" + wanted + "'");
    }

    const data = await this._json(this.base + "/ajax/server/list?servers=" + ids, this.base + "/");
    const html = data && typeof data.result === "string" ? data.result : "";
    // <div class="type" data-type="sub"> ... <li data-sv-id="4" data-link-id="...">Vidplay</li> ...</ul>
    const offered = [];
    const players = [];
    const sections = html.split(/<div class="type"/).slice(1);
    for (const section of sections) {
      const type = /^\s*data-type="([^"]*)"/.exec(section);
      if (!type) continue;
      const itemRe = /<li[^>]*\bdata-link-id="([^"]+)"[^>]*>([^<]*)</g;
      let match;
      while ((match = itemRe.exec(section)) !== null) {
        const name = this._plain(match[2]);
        offered.push(name + " (" + type[1] + ")");
        if (type[1].toLowerCase() === audio) players.push({ name: name, link: match[1] });
      }
    }
    if (offered.length === 0) throw new Error("no player listed for this episode");
    if (players.length === 0) throw new Error(audio === "dub" ? "no dub for this episode" : "no subbed version of this episode");

    const order = wanted === "default" ? known : [wanted];
    let reason = null;
    let tried = false;
    for (const name of order) {
      const player = players.filter(function (p) { return p.name.toLowerCase() === name.toLowerCase(); })[0];
      if (!player) continue;
      tried = true;
      try {
        const source = await this._json(this.base + "/ajax/sources?id=" + encodeURIComponent(player.link) + "&asi=0&autoPlay=0", this.base + "/");
        const embed = source && source.result && typeof source.result.url === "string" ? source.result.url : "";
        if (!/^https?:\/\//i.test(embed)) throw new Error("the site names no player address");
        const url = await this._vidplay(embed);
        const result = {
          server: player.name,
          headers: { Referer: this._origin(embed) + "/" },
          videoSources: [
            { url: url, type: "m3u8", quality: "auto", label: audio === "dub" ? "Dub" : "Hard sub", subtitles: [] },
          ],
        };
        const skip = this._skip(source.result.skip_data);
        if (skip) result.skip = skip;
        return result;
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    if (!tried) throw new Error("'" + wanted + "' is not offered for this episode (offered: " + offered.join(", ") + ")");
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- players

  // Vidplay: the player page names a source id (<div id="screen" data-id="...">); `getSources`
  // next to it answers with the HLS address.
  async _vidplay(embedUrl) {
    const page = await this._page(embedUrl, true);
    const screen = /<[^>]*\bid="screen"[^>]*>/.exec(page);
    const sourceId = screen ? /\bdata-id="([^"]+)"/.exec(screen[0]) : null;
    if (!sourceId) throw new Error("the player page has changed (no source id)");
    const folder = String(embedUrl).split(/[?#]/)[0].replace(/[^\/]*$/, "");
    const data = await this._json(folder + "getSources?id=" + encodeURIComponent(this._unescapeBody(sourceId[1])), embedUrl);
    if (data && data.ok === false) throw new Error(String(data.message || data.err || "the player has no source"));
    let url = "";
    const sources = data && data.sources;
    if (typeof sources === "string") url = sources.trim();
    else if (Array.isArray(sources) && sources[0]) url = String(typeof sources[0] === "string" ? sources[0] : sources[0].file || sources[0].src || "");
    else if (sources && typeof sources === "object") url = String(sources.file || sources.src || "");
    if (!/^https?:\/\//i.test(url)) throw new Error("the player names no video");
    return url;
  }

  // ---------------------------------------------------------------- parsing

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // Items of the filter page: <div class="item "> ... <span class="ep-status sub"><span> 28 </span> ...
  //   <a class="name d-title" href="/watch/sousou-no-frieren-74575" data-jp="Sousou no Frieren">Frieren: ...</a>
  _filterItems(html) {
    const list = html.split(/id="list-items"/)[1] || "";
    const items = [];
    for (const block of list.split(/<div class="item\b/).slice(1)) {
      const name = /<a class="name d-title" href="\/watch\/([^"]+)"(?:\s+data-jp="([^"]*)")?>([^<]*)</.exec(block);
      if (!name) continue;
      const numeric = /-(\d+)$/.exec(name[1]);
      if (!numeric) continue;
      items.push({
        animeId: numeric[1],
        slug: name[1],
        title: this._plain(name[3]),
        other: name[2] ? this._plain(name[2]) : "",
        sub: this._count(block, "sub"),
        dub: this._count(block, "dub"),
      });
    }
    return items;
  }

  // Items of the quick search: <a class="item" href="/watch/...-82499"> ... <div class="name d-title" data-jp="...">Title</div>
  //   ... <span class="dot">Jan 16, 2026 to Mar 27, 2026</span>
  _quickItems(data) {
    const html = data && data.result && typeof data.result.html === "string" ? data.result.html : "";
    const items = [];
    for (const block of html.split(/<a class="item"/).slice(1)) {
      const href = /^\s*href="\/watch\/([^"]+)"/.exec(block);
      const name = /class="name d-title"(?:\s+data-jp="([^"]*)")?>([^<]*)</.exec(block);
      if (!href || !name) continue;
      const numeric = /-(\d+)$/.exec(href[1]);
      if (!numeric) continue;
      const aired = /<span class="dot">[A-Z][a-z]{2} \d{1,2}, (\d{4})/.exec(block);
      items.push({
        animeId: numeric[1],
        slug: href[1],
        title: this._plain(name[2]),
        other: name[1] ? this._plain(this._unescapeBody(name[1])) : "",
        sub: -1,
        dub: -1,
        year: aired ? parseInt(aired[1], 10) : undefined,
      });
    }
    return items;
  }

  // The count in a badge: <span class="ep-status dub"><span> 28</span></span>; 0 when absent.
  _count(block, kind) {
    const match = new RegExp('class="ep-status ' + kind + '"><span>\\s*(\\d+)').exec(block);
    return match ? parseInt(match[1], 10) : 0;
  }

  // { intro: [start, end], outro: [start, end] } in seconds; [0, 0] means unknown.
  _skip(listed) {
    if (!listed || typeof listed !== "object") return null;
    const part = function (entry) {
      if (!Array.isArray(entry) || entry.length < 2) return null;
      const start = Number(entry[0]);
      const end = Number(entry[1]);
      return isFinite(start) && isFinite(end) && end > start && start >= 0 ? { start: start, end: end } : null;
    };
    const intro = part(listed.intro);
    const outro = part(listed.outro);
    if (!intro && !outro) return null;
    const skip = {};
    if (intro) {
      skip.introStart = intro.start;
      skip.introEnd = intro.end;
    }
    if (outro) {
      skip.outroStart = outro.start;
      skip.outroEnd = outro.end;
    }
    return skip;
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  // ---------------------------------------------------------------- shared helpers

  // The body of a 2xx answer. A redirect to another site is an error unless `anyHost`, which
  // is for player pages.
  async _page(url, anyHost) {
    const host = this._host(url);
    const response = await this._fetch(url, { headers: { Referer: this.base + "/" } });
    if (!response.ok) {
      const body = response.status === 403 || response.status === 503 ? String(await response.text()) : "";
      if (this._looksLikeChallenge(body)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (!anyHost && response.url && this._host(response.url) !== "unknown host" && this._host(response.url) !== host) {
      throw new Error(host + " redirected to " + this._host(response.url));
    }
    return String(await response.text());
  }

  async _json(url, referer) {
    const host = this._host(url);
    const response = await this._fetch(url, { headers: { Referer: referer, Accept: "application/json", "X-Requested-With": "XMLHttpRequest" } });
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    let data;
    try {
      data = JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
    if (data && typeof data.status === "number" && data.status !== 200) {
      throw new Error(host + ": " + String(data.message || data.result || "status " + data.status));
    }
    return data;
  }

  // One retry when the connection itself fails.
  async _fetch(url, init) {
    try {
      return await fetch(url, init);
    } catch (first) {
      try {
        return await fetch(url, init);
      } catch (error) {
        throw new Error(this._host(url) + " unreachable (" + this._errorText(error) + ")");
      }
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  // Undoes the escaping scraped bodies wrap text in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  _origin(url) {
    const match = /^([a-z][a-z0-9+.-]*:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// AnimeHeaven (animeheaven.me): English subbed anime as MP4 with the subtitles in the picture.
// Each episode is opened through the site's gate page, which reads the episode key from a cookie.
// Flow as in the Seanime AnimeHeaven provider (github.com/Pal-droid/Seanime-Providers).

class Provider {
  constructor() {
    this.base = "https://animeheaven.me";
  }

  getSettings() {
    return {
      episodeServers: ["AnimeHeaven"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    for (const query of queries) {
      const html = await this._page(this.base + "/search.php?s=" + encodeURIComponent(query), this.base + "/");
      // <div class='similarimg'><div class='p1'><a href='anime.php?ak2gr'>...
      //   <div class='similarname c'><a href='anime.php?ak2gr' class='c'>Frieren: Beyond Journey&#039;s End</a>
      const results = [];
      for (const block of html.split(/<div class='similarimg'>/).slice(1)) {
        const name = /<div class='similarname[^']*'>\s*<a href='anime\.php\?([a-z0-9]+)'[^>]*>([^<]*)</i.exec(block);
        if (!name || results.some(function (r) { return r.id === name[1]; })) continue;
        const title = this._plain(name[2]);
        if (!title) continue;
        results.push({ id: name[1], title: title, url: this.base + "/anime.php?" + name[1], subOrDub: "sub" });
      }
      if (results.length > 0) return results;
    }
    return [];
  }

  async findEpisodes(id) {
    const animeId = String(id);
    if (!/^[a-z0-9]+$/i.test(animeId)) throw new Error("invalid anime id '" + id + "'");
    const html = await this._page(this.base + "/anime.php?" + animeId, this.base + "/");
    // <a class='c' id="<key>" onclick='gatea( "<key>")' ... href='gate.php'>
    //   ... <div class='watch1 bc c'>Episode</div><div class=' watch2 bc '>28</div>
    const episodes = [];
    const seen = {};
    for (const entry of html.split(/<a\s+class='c'\s+(?=id\s*=)/).slice(1)) {
      const key = /gatea\(\s*"([a-f0-9]{16,64})"\s*\)/.exec(entry);
      const number = /class=\s*'\s*watch2\b[^']*'\s*>\s*(\d+(?:\.\d+)?)\s*</.exec(entry);
      if (!key || !number || seen[number[1]]) continue;
      seen[number[1]] = true;
      episodes.push({
        id: key[1] + "|" + animeId,
        number: Number(number[1]),
        url: this.base + "/anime.php?" + animeId,
        title: "Episode " + number[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const key = parts[0];
    const animeId = /^[a-z0-9]+$/i.test(parts[1] || "") ? parts[1] : "";
    if (!/^[a-f0-9]{16,64}$/.test(key || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "animeheaven") throw new Error("unknown server '" + wanted + "'");

    const referer = animeId ? this.base + "/anime.php?" + animeId : this.base + "/";
    const html = await this._page(this.base + "/gate.php", referer, { Cookie: "key=" + key });
    // Several <source src='https://cx.animeheaven.me/video.mp4?<key>&<token>'> mirrors; the
    // first one listed can be a short placeholder clip that does not carry the episode key.
    const listed = [];
    const re = /<source\s+src=['"](https?:\/\/[^'"]+)['"]/gi;
    let match;
    while ((match = re.exec(html)) !== null) {
      const url = this._unescapeBody(match[1]);
      if (listed.indexOf(url) < 0) listed.push(url);
    }
    const own = listed.filter(function (url) { return url.indexOf("?" + key + "&") >= 0; });
    own.sort(function (a, b) { return Number(/&error/.test(a)) - Number(/&error/.test(b)); });
    if (own.length === 0) {
      throw new Error(listed.length > 0 ? "the site did not hand out this episode's video" : "the gate page names no video");
    }
    return {
      server: "AnimeHeaven",
      headers: { Referer: this.base + "/" },
      videoSources: own.slice(0, 2).map(function (url, index) {
        return { url: url, type: "mp4", quality: "auto", label: index === 0 ? "Hard sub" : "Hard sub (mirror)", subtitles: [] };
      }),
    };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.englishTitle, media.romajiTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 3);
  }

  async _page(url, referer, extra) {
    const host = this._host(url);
    const headers = { Referer: referer };
    for (const name of Object.keys(extra || {})) headers[name] = extra[name];
    const response = await this._fetch(url, { headers: headers });
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return text;
  }

  // Retries when the connection itself fails; some networks reset connections to this site.
  async _fetch(url, init) {
    let last = null;
    for (let attempt = 0; attempt < 3; attempt += 1) {
      try {
        return await fetch(url, init);
      } catch (error) {
        last = error;
      }
    }
    throw new Error(this._host(url) + " unreachable (" + this._errorText(last) + ")");
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/&amp;/g, "&")
      .replace(/&quot;|&#34;/g, '"')
      .replace(/&#0?39;|&#x27;/g, "'")
      .replace(/&#x2F;|&#47;/g, "/");
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }
}

// Anime Salt (animesalt.cx): Indian-language dubs (Hindi, Tamil, Telugu, ...) plus English and
// Japanese audio, as multi-audio HLS from the site's own player (a "FirePlayer" host, ravok.buzz),
// with English WebVTT subtitles where the release has them. WordPress (TOROFILM theme) pages.

class Provider {
  constructor() {
    this.site = "https://animesalt.cx";
    // Search hits whose pages are read for seasons and languages.
    this.maxHits = 6;
    this.languageCodes = {
      hin: "Hindi", tam: "Tamil", tel: "Telugu", ben: "Bengali", mal: "Malayalam", mar: "Marathi",
      kan: "Kannada", eng: "English", kor: "Korean", jpn: "Japanese",
    };
  }

  getSettings() {
    return {
      episodeServers: ["MyStream"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    for (const query of queries) {
      const body = await this._page(this.site + "/?s=" + encodeURIComponent(query), this.site + "/");
      const hits = this._searchHits(body).slice(0, this.maxHits);
      if (hits.length === 0) continue;

      const self = this;
      const looked = await Promise.all(hits.map(function (hit) {
        return self._page(hit.url, self.site + "/").then(
          function (page) { return { hit: hit, page: page }; },
          function (error) { return { hit: hit, error: error }; });
      }));

      const results = [];
      for (const entry of looked) {
        if (entry.error) continue;
        const hit = entry.hit;
        const languages = this._languages(entry.page);
        const hasDub = languages.some(function (language) { return language !== "Japanese"; });
        const hasJapanese = languages.indexOf("Japanese") >= 0;
        if (audio === "dub" ? !hasDub : !hasJapanese) continue;

        if (hit.kind === "movies") {
          results.push({ id: "movies|" + hit.slug + "||" + audio, title: hit.title, url: hit.url, subOrDub: audio });
          continue;
        }
        const postId = this._postId(entry.page);
        for (const group of this._seasonGroups(entry.page)) {
          if (audio === "dub" && group.every(function (season) { return season.subOnly; })) continue;
          const first = group[0];
          results.push({
            id: "series|" + hit.slug + "|" + postId + ":" + group.map(function (season) { return season.number + (season.subOnly ? "s" : ""); }).join(",") + "|" + audio,
            title: first.number > 1 ? hit.title + " Season " + first.number : hit.title,
            url: hit.url,
            subOrDub: audio,
          });
        }
      }
      if (results.length > 0) return results;
      const failed = looked.filter(function (entry) { return entry.error; })[0];
      if (failed && failed.error && /bot protection|unreachable/.test(String(failed.error.message))) throw failed.error;
    }
    return [];
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const kind = parts[0];
    const slug = parts[1];
    const seasons = parts[2] || "";
    const audio = parts[3] === "dub" ? "dub" : "sub";
    if ((kind !== "series" && kind !== "movies") || !/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    if (kind === "movies") {
      return [{ id: "movies|" + slug + "|" + audio, number: 1, url: this.site + "/movies/" + slug + "/", title: "Movie" }];
    }

    const match = /^(\d+):([\ds,]+)$/.exec(seasons);
    if (!match && seasons !== "") throw new Error("invalid anime id '" + id + "'");
    const episodes = [];
    const seen = {};
    const add = (listed) => {
      for (const item of listed) {
        if (seen[item.number]) continue;
        seen[item.number] = true;
        episodes.push({ id: "episode|" + item.slug + "|" + audio, number: item.number, url: this.site + "/episode/" + item.slug + "/", title: item.title });
      }
    };

    if (!match || match[1] === "0") {
      add(this._episodeItems(await this._page(this.site + "/series/" + slug + "/", this.site + "/")));
    } else {
      const wanted = match[2].split(",").filter(function (entry) { return entry && !(audio === "dub" && /s$/.test(entry)); });
      // Season lists are fetched a few at a time; long series have twenty and more.
      for (let start = 0; start < wanted.length; start += 8) {
        const lists = await Promise.all(wanted.slice(start, start + 8).map((entry) => {
          const url = this.site + "/wp-admin/admin-ajax.php?action=action_select_season&season=" + entry.replace(/s$/, "") + "&post=" + match[1];
          return this._page(url, this.site + "/series/" + slug + "/");
        }));
        for (const body of lists) add(this._episodeItems(body));
      }
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const kind = parts[0];
    const slug = parts[1];
    const audio = parts[2] === "dub" ? "dub" : "sub";
    if ((kind !== "episode" && kind !== "movies") || !/^[\w-]+$/.test(slug || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "mystream") throw new Error("unknown server '" + wanted + "'");

    const pageUrl = this.site + "/" + kind + "/" + slug + "/";
    const page = await this._page(pageUrl, this.site + "/");
    const embed = /<iframe\b[^>]*?\b(?:data-)?src\s*=\s*["'](https:\/\/([\w.-]+)\/video\/([0-9a-f]{32}))["']/i.exec(page);
    if (!embed) throw new Error("no supported player for this episode (only the Abyss player is offered)");
    const playerUrl = embed[1];
    const playerOrigin = "https://" + embed[2];
    const hash = embed[3];

    // The player page (subtitle list) is read while the stream is looked up.
    const playerPage = this._page(playerUrl, this.site + "/").catch(function () { return ""; });
    const answer = await this._page(playerOrigin + "/player/index.php?data=" + hash + "&do=getVideo", { Referer: playerUrl, Origin: playerOrigin, "X-Requested-With": "XMLHttpRequest" },
      { method: "POST", body: "hash=" + hash + "&r=" + encodeURIComponent(this.site + "/") });
    let video;
    try {
      video = JSON.parse(answer);
    } catch (error) {
      throw new Error("the player answered: " + this._plain(answer).slice(0, 120));
    }
    const source = video && (video.securedLink || video.videoSource);
    if (typeof source !== "string" || !/^https?:\/\//.test(source)) throw new Error("the player has no stream for this episode");

    const headers = { Referer: playerOrigin + "/" };
    const master = await this._page(source, headers);
    if (master.indexOf("#EXTM3U") < 0) throw new Error("the player's playlist is unreadable");
    const tracks = this._audioTracks(master);
    const dubs = tracks.filter(function (name) { return name !== "Japanese"; });
    if (audio === "dub" && tracks.length > 0 && dubs.length === 0) throw new Error("no dub for this episode");
    if (audio === "sub" && tracks.length > 0 && tracks.indexOf("Japanese") < 0) throw new Error("no Japanese audio for this episode");

    // The player page names the subtitle files: "[English]https://…,[…]https://…".
    let subtitles = [];
    try {
      const player = await playerPage;
      const listed = /playerjsSubtitle\s*=\s*"([^"]*)"/.exec(player);
      const re = /\[([^\]]+)\](https?:\/\/[^,\s]+)/g;
      let item;
      while (listed && (item = re.exec(this._unescapeBody(listed[1]))) !== null) {
        subtitles.push({ id: item[1].toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: item[2], language: item[1], isDefault: audio === "sub" && subtitles.length === 0 });
      }
    } catch (error) {
      subtitles = [];
    }

    // One playlist carries every audio track; the player's audio menu switches between them.
    const order = ["Hindi", "Tamil", "Telugu", "Bengali", "Malayalam", "Marathi", "Kannada", "English", "Korean", "Japanese"];
    tracks.sort(function (a, b) { return (order.indexOf(a) + 1 || 99) - (order.indexOf(b) + 1 || 99); });
    let label = audio === "dub" ? "Dub" : "Japanese audio";
    if (tracks.length > 0) label = "Multi-audio: " + tracks.join(", ");
    return {
      server: "MyStream",
      headers: headers,
      videoSources: [{ url: source, type: "m3u8", quality: "auto", label: label, subtitles: subtitles }],
    };
  }

  // ---------------------------------------------------------------- site parsing

  // Search result cards: [{ kind: "series"|"movies", slug, title, url }].
  _searchHits(body) {
    const hits = [];
    const re = /<li\b[^>]*\bid="post-\d+"[^>]*>([\s\S]*?)<\/li>/g;
    let match;
    while ((match = re.exec(body)) !== null) {
      const card = match[1];
      const link = /href="(https?:\/\/[^"\/]+\/(series|movies)\/([\w-]+)\/?)"/.exec(card);
      const title = /<h2[^>]*class="entry-title"[^>]*>([\s\S]*?)<\/h2>/.exec(card);
      if (!link || !title) continue;
      if (hits.some(function (hit) { return hit.slug === link[3] && hit.kind === link[2]; })) continue;
      hits.push({ kind: link[2], slug: link[3], title: this._plain(title[1]), url: this.site + "/" + link[2] + "/" + link[3] + "/" });
    }
    return hits;
  }

  // Audio languages a title page names, from its "Languages" box and its <title> ("… in Hindi, Tamil & Japanese").
  _languages(page) {
    const names = [];
    const box = page.indexOf(">Languages</h4>");
    if (box >= 0) {
      const part = page.slice(box, page.indexOf("</div>", box) > 0 ? page.indexOf("</div>", box) : box + 4000);
      const re = /\/category\/language\/[\w-]+\/?"[^>]*>\s*([^<]+?)\s*<\/a>/g;
      let match;
      while ((match = re.exec(part)) !== null) names.push(this._plain(match[1]));
    }
    const title = /<title>([^<]*)<\/title>/i.exec(page);
    const listed = title ? /\bwatch now in\s+(.+)$/i.exec(this._plain(title[1])) : null;
    if (listed) {
      for (const name of listed[1].split(/,|&|\band\b/)) names.push(name.trim());
    }
    const kept = [];
    for (const name of names) {
      const clean = name.replace(/[^A-Za-z ]/g, "").trim();
      if (clean && kept.indexOf(clean) < 0) kept.push(clean.charAt(0).toUpperCase() + clean.slice(1).toLowerCase());
    }
    return kept;
  }

  _postId(page) {
    const match = /data-post="(\d+)"\s+data-season="/.exec(page);
    return match ? match[1] : "0";
  }

  // Seasons grouped into AniList-like entries: a season that starts again at episode 1 begins a new
  // entry ("Season 2 • 1-23"), one that continues the numbering ("Season 2 • 58-100") joins the previous.
  _seasonGroups(page) {
    const seasons = [];
    const re = /data-season="(\d+)"[^>]*>([^<]*)</g;
    let match;
    while ((match = re.exec(page)) !== null) {
      const number = parseInt(match[1], 10);
      if (seasons.some(function (season) { return season.number === number; })) continue;
      const range = /(\d+)\s*-\s*(\d+)/.exec(match[2]);
      // "Season 17 • 362-372 (11) [Sub]": only the original audio so far.
      seasons.push({ number: number, from: range ? parseInt(range[1], 10) : null, subOnly: /\[\s*sub\s*\]/i.test(match[2]) });
    }
    if (seasons.length === 0) return [[{ number: 0, from: 1 }]];
    seasons.sort(function (a, b) { return a.number - b.number; });
    const groups = [];
    for (const season of seasons) {
      if (groups.length === 0 || season.from === 1) groups.push([season]);
      else groups[groups.length - 1].push(season);
    }
    return groups;
  }

  // Episode cards of a season list: [{ slug, number, title }].
  _episodeItems(body) {
    const items = [];
    const re = /<article\b[^>]*\bepisodes\b[^>]*>([\s\S]*?)<\/article>/g;
    let match;
    while ((match = re.exec(body)) !== null) {
      const card = match[1];
      const link = /href="https?:\/\/[^"\/]+\/episode\/([\w-]+)\/?"/.exec(card);
      const number = /class="num-epi"[^>]*>\s*([\d.]+)/.exec(card);
      if (!link || !number) continue;
      const title = /<h2[^>]*class="entry-title"[^>]*>([\s\S]*?)<\/h2>/.exec(card);
      const value = parseFloat(number[1]);
      if (!isFinite(value)) continue;
      items.push({ slug: link[1], number: value, title: (title && this._plain(title[1])) || "Episode " + value });
    }
    return items;
  }

  // Audio renditions of a master playlist, as language names.
  _audioTracks(master) {
    const names = [];
    const re = /#EXT-X-MEDIA:[^\n]*TYPE=AUDIO[^\n]*/g;
    let match;
    while ((match = re.exec(master)) !== null) {
      const line = match[0];
      const code = /LANGUAGE="([^"]+)"/.exec(line);
      const name = /NAME="([^"]+)"/.exec(line);
      const shown = (code && this.languageCodes[code[1].toLowerCase()]) || (name && name[1]) || (code && code[1]) || "";
      if (shown && names.indexOf(shown) < 0) names.push(shown);
    }
    return names;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const titles = [opts && opts.query, media.englishTitle, media.romajiTitle].filter(function (title) {
      return typeof title === "string" && title.trim();
    });
    // The site's search matches every word, so season markers ("Season 2", "2nd Season", "Part 2")
    // are dropped for a further try; its season entries carry them again.
    const reduced = titles.map(function (title) {
      return title.replace(/\s*(?:\b(?:season|part|cour)\s*\d+|\b\d+(?:st|nd|rd|th)\s+season|\bs\d+)\b.*$/i, "").replace(/[\s:\-–]+$/, "");
    });
    for (const title of titles.slice(0, 2).concat(reduced)) {
      const clean = String(title).trim();
      if (clean && queries.indexOf(clean) < 0) queries.push(clean);
    }
    return queries.slice(0, 4);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page of a site as text. `referer` is a URL, or an object of request headers.
  async _page(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (this._looksLikeChallenge(text) && text.length < 20000) throw new Error("blocked by the site's bot protection");
    return text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// DesiDubAnime (desidubanime.me): Hindi (and other Indian-language) dubbed anime, streamed as HLS
// from VidMoly, with English WebVTT subtitles where the upload has them. WordPress (Kiranime theme):
// titles through the WordPress REST API, episodes and players from the watch pages.

class Provider {
  constructor() {
    this.site = "https://www.desidubanime.me";
  }

  getSettings() {
    return {
      episodeServers: ["VidMoly"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // Every stream on the site is a dub; there is no original-audio version to offer.
    if (!opts || !opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    for (const query of queries) {
      const found = await this._json(this.site + "/wp-json/wp/v2/anime?per_page=20&_fields=slug,link,title,class_list&search=" + encodeURIComponent(query));
      const results = [];
      for (const item of Array.isArray(found) ? found : []) {
        if (!item || typeof item.slug !== "string" || !/^[\w%-]+$/.test(item.slug)) continue;
        const classes = Array.isArray(item.class_list) ? item.class_list : [];
        // Titles are tagged with their audio languages; only Hindi ones are listed.
        if (classes.length > 0 && classes.indexOf("tag-hindi") < 0) continue;
        const title = this._plain(item.title && item.title.rendered);
        if (!title || results.some(function (r) { return r.id === item.slug; })) continue;
        results.push({ id: item.slug, title: title, url: this.site + "/anime/" + item.slug + "/", subOrDub: "dub" });
      }
      if (results.length > 0) return results;
    }
    return [];
  }

  async findEpisodes(id) {
    const slug = String(id);
    if (!/^[\w%-]+$/.test(slug)) throw new Error("invalid anime id '" + id + "'");

    // The title page shows the latest few episodes; every watch page lists them all.
    const page = await this._page(this.site + "/anime/" + slug + "/", this.site + "/");
    const first = /href="(https?:\/\/[^"\/]+\/watch\/[\w%-]+\/?)"/.exec(page);
    if (!first) throw new Error("no episodes listed");
    const watch = await this._page(first[1], this.site + "/anime/" + slug + "/");

    const episodes = [];
    const seen = {};
    const re = /<a\b[^>]*href="https?:\/\/[^"\/]+\/watch\/([\w%-]+)\/?"[^>]*class="[^"]*\bepisode-list-item\b[^"]*"[^>]*>([\s\S]*?)<\/a>/g;
    let match;
    while ((match = re.exec(watch)) !== null) {
      const number = /episode-list-item-number"[^>]*>\s*([\d.]+)/.exec(match[2]);
      const title = /episode-list-item-title"[^>]*>([\s\S]*?)<\/span>/.exec(match[2]);
      const value = number ? parseFloat(number[1]) : NaN;
      if (!isFinite(value) || seen[value]) continue;
      seen[value] = true;
      episodes.push({ id: match[1], number: value, url: this.site + "/watch/" + match[1] + "/", title: (title && this._plain(title[1])) || "Episode " + value });
    }
    if (episodes.length === 0) {
      // A single-episode title (a movie) has no list, only its own watch page.
      const own = /\/watch\/([\w%-]+)\/?$/.exec(first[1]);
      if (own) episodes.push({ id: own[1], number: 1, url: first[1], title: "Episode 1" });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const slug = String((episode && episode.id) || "");
    if (!/^[\w%-]+$/.test(slug)) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && wanted.toLowerCase() !== "vidmoly") throw new Error("unknown server '" + wanted + "'");

    const pageUrl = this.site + "/watch/" + slug + "/";
    const page = await this._page(pageUrl, this.site + "/");
    const players = this._players(page);
    if (players.length === 0) throw new Error("the site has no player for this episode");
    const vidmoly = players.filter(function (player) { return /^https:\/\/(?:[\w-]+\.)*vidmoly\.[a-z]+\//i.test(player.url); });
    if (vidmoly.length === 0) {
      const hosts = players.map(function (player) { return this._host(player.url); }, this);
      throw new Error("no supported player for this episode; this extension can't read the video hosts " + hosts.filter(function (h, i) { return hosts.indexOf(h) === i; }).join(", "));
    }

    let reason = null;
    for (const player of vidmoly) {
      try {
        return await this._vidmoly(player.url, pageUrl);
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- players

  // The watch page's server buttons: data-embed-id="base64(name):base64(url or iframe markup)".
  _players(page) {
    const players = [];
    const re = /data-embed-id="([A-Za-z0-9+\/=]+):([A-Za-z0-9+\/=]+)"/g;
    let match;
    while ((match = re.exec(page)) !== null) {
      let name;
      let value;
      try {
        name = this._base64(match[1]);
        value = this._base64(match[2]);
      } catch (error) {
        continue;
      }
      // Iframe markup can carry a scheme-less src ("//vidmoly.net/embed-...").
      const found = /(?:https?:)?\/\/[^\s"'<>]+/.exec(value);
      const url = found && this._absolute(found[0], "https:");
      if (!url || players.some(function (player) { return player.url === url; })) continue;
      players.push({ name: name.replace(/dub$|sub$/i, "") || name, url: url });
    }
    return players;
  }

  async _vidmoly(embedUrl, referer) {
    const response = await this._fetch(embedUrl, { Referer: referer });
    const body = response.text;
    const origin = this._origin(response.url || embedUrl);
    const sources = /sources\s*:\s*\[\s*\{\s*file\s*:\s*['"]([^'"]+)['"]/.exec(body);
    if (!sources) {
      if (/File (?:was )?(?:deleted|not found)|has been removed/i.test(body)) throw new Error("the video was removed from VidMoly");
      throw new Error("VidMoly has no stream for this episode");
    }
    const source = this._absolute(sources[1], origin);

    const subtitles = [];
    const re = /\{\s*file\s*:\s*['"]([^'"]+\.(?:vtt|srt)[^'"]*)['"]\s*,\s*label\s*:\s*['"]([^'"]+)['"][^}]*kind\s*:\s*['"]captions['"]/g;
    let match;
    while ((match = re.exec(body)) !== null) {
      const url = this._absolute(match[1], origin);
      if (subtitles.some(function (s) { return s.url === url; })) continue;
      subtitles.push({ id: match[2].toLowerCase().replace(/[^a-z0-9]+/g, "-") + "-" + subtitles.length, url: url, language: match[2], isDefault: false });
    }

    const headers = { Referer: origin + "/", Origin: origin };
    let url = source;
    let label = "Hindi dub";
    if (this._isHls(source)) {
      const master = await this._page(source, headers);
      if (master.indexOf("#EXTM3U") < 0) throw new Error("VidMoly's playlist is unreadable");
      const languages = [];
      const tracks = /#EXT-X-MEDIA:[^\n]*TYPE=AUDIO[^\n]*/g;
      let track;
      while ((track = tracks.exec(master)) !== null) {
        const code = /LANGUAGE="([^"]+)"/.exec(track[0]);
        if (code && languages.indexOf(code[1].toLowerCase()) < 0) languages.push(code[1].toLowerCase());
      }
      if (languages.length > 0) {
        // Multi-audio uploads list their tracks, Hindi first and marked as the default one.
        if (languages.indexOf("hi") < 0 && languages.indexOf("hin") < 0) throw new Error("no Hindi audio for this episode (tracks: " + languages.join(", ") + ")");
        label = "Hindi dub (multi-audio: " + languages.join(", ") + ")";
      } else {
        // Older uploads list one variant muxed with some track of the release ("index-v1-a6");
        // the releases put Hindi first, so the variant with track 1 is played.
        const variant = /^(https?:\/\/[^\s]+\/index-v\d+-a)\d+(\.m3u8[^\s]*)$/m.exec(master);
        if (variant) url = variant[1] + "1" + variant[2];
      }
    }
    return {
      server: "VidMoly",
      headers: headers,
      videoSources: [{ url: url, type: this._isHls(url) ? "m3u8" : "mp4", quality: "auto", label: label, subtitles: subtitles }],
    };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    const titles = [opts && opts.query, media.englishTitle, media.romajiTitle].filter(function (title) {
      return typeof title === "string" && title.trim();
    });
    // The site's search matches every word, so season markers ("Season 2", "2nd Season", "Part 2")
    // are dropped for a further try; its season entries carry them again.
    const reduced = titles.map(function (title) {
      return title.replace(/\s*(?:\b(?:season|part|cour)\s*\d+|\b\d+(?:st|nd|rd|th)\s+season|\bs\d+)\b.*$/i, "").replace(/[\s:\-–]+$/, "");
    });
    for (const title of titles.slice(0, 2).concat(reduced)) {
      const clean = String(title).trim();
      if (clean && queries.indexOf(clean) < 0) queries.push(clean);
    }
    return queries.slice(0, 4);
  }

  _base64(value) {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const clean = String(value).replace(/=+$/, "");
    const bytes = [];
    let buffer = 0;
    let bits = 0;
    for (const char of clean) {
      const index = alphabet.indexOf(char);
      if (index < 0) throw new Error("not base64");
      buffer = (buffer << 6) | index;
      bits += 6;
      if (bits >= 8) {
        bits -= 8;
        bytes.push((buffer >> bits) & 0xff);
      }
    }
    let text = "";
    for (let i = 0; i < bytes.length; i += 1) text += String.fromCharCode(bytes[i]);
    try {
      return decodeURIComponent(escape(text));
    } catch (error) {
      return text;
    }
  }

  async _json(url) {
    const text = await this._page(url, { Accept: "application/json", Referer: this.site + "/" });
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") throw new Error(this._host(url) + " answered with a page instead of data");
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(this._host(url) + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _absolute(raw, origin) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    return origin + (url.charAt(0) === "/" ? "" : "/") + url;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A response as { text, url } (`url` after redirects). `headers` are request headers.
  async _fetch(url, headers) {
    const host = this._host(url);
    let response;
    try {
      response = await fetch(url, { headers: headers || {} });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (this._looksLikeChallenge(text) && text.length < 20000) throw new Error("blocked by the site's bot protection");
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  // A page as text. `referer` is a URL, or an object of request headers.
  async _page(url, referer) {
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    return (await this._fetch(url, headers)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html || "").replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  _unescapeBody(body) {
    return String(body)
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}

// Latanime (latanime.org): anime dubbed in Latin American Spanish ("… Latino") and Spain
// Spanish ("… Castellano"), and some titles with Spanish subtitles (no suffix). Every audio is a
// separate entry of the site. Episodes play from third-party video hosts (StreamWish, Filemoon,
// VidHide, LuluStream, VOE, Mp4Upload, YourUpload, Uqload, MixDrop).

class Provider {
  constructor() {
    this.base = "https://latanime.org";
  }

  getSettings() {
    return {
      episodeServers: ["StreamWish", "Filemoon", "VidHide", "LuluStream", "Voe", "Mp4Upload", "YourUpload", "Uqload", "MixDrop"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const wantDub = !!(opts && opts.dub);

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/buscar?q=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
      // One card: <a href="https://latanime.org/anime/slug"> … <h3 …>Title Latino</h3>
      // <span class="opacity-75">Latino</span><span …><svg …>…</svg> 2017</span>
      const cards = html.split(/<a href="(?=https:\/\/latanime\.org\/anime\/)/).slice(1);
      for (const card of cards) {
        const slug = /^https:\/\/latanime\.org\/anime\/([\w-]+)"/.exec(card);
        const heading = /<h3\b[^>]*>([\s\S]*?)<\/h3>/.exec(card.split("</a>")[0]);
        if (!slug || !heading || results.some(function (r) { return r.id.split("|")[0] === slug[1]; })) continue;
        const shown = this._plain(heading[1]);
        const kind = /class="opacity-75">([^<]*)</.exec(card);
        const audio = this._audio(slug[1], shown, kind ? kind[1] : "");
        if (audio === "other" || (audio !== "sub") !== wantDub) continue;
        const title = this._clean(shown);
        const year = /<\/svg>\s*((?:19|20)\d{2})\s*<\/span>/.exec(card);
        results.push({
          id: slug[1] + "|" + audio,
          title: title,
          url: this.base + "/anime/" + slug[1],
          subOrDub: audio === "sub" ? "sub" : "dub",
          altTitles: [shown],
          year: year ? parseInt(year[1], 10) : undefined,
        });
      }
      if (results.length > 0) break;
    }
    // Cards show only the Spanish title ("Frieren: Más allá del final del viaje"); the anime page
    // also names the original one ("Sousou no Frieren Audio Latino"). Read it for hits that do not
    // already contain the searched title.
    const asked = queries.map(this._words);
    const unclear = results.filter((r) => !asked.some((q) => this._words(r.title).indexOf(q) >= 0)).slice(0, 6);
    await Promise.all(unclear.map(async (result) => {
      try {
        const original = /<h3 class="fs-6[^"]*">([\s\S]*?)<\/h3>/.exec(await this._page(result.url, this.base + "/"));
        const name = original ? this._clean(this._plain(original[1])) : "";
        if (name && result.altTitles.indexOf(name) < 0) result.altTitles.push(name);
      } catch (error) {
        // The Spanish title still counts.
      }
    }));
    // Latin American dubs first, then Spain's.
    results.sort(function (a, b) { return (/\|castellano$/.test(a.id) ? 1 : 0) - (/\|castellano$/.test(b.id) ? 1 : 0); });
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    if (!/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");
    const audio = ["latino", "castellano", "sub"].indexOf(parts[1]) >= 0 ? parts[1] : this._audio(slug, "");

    const html = await this._page(this.base + "/anime/" + slug, this.base + "/");
    const episodes = [];
    const seen = {};
    const re = /href="https:\/\/latanime\.org\/ver\/([\w-]+?-episodio-(\d+(?:\.\d+)?))"/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      if (seen[match[2]]) continue;
      seen[match[2]] = true;
      episodes.push({
        id: match[1] + "|" + audio,
        number: Number(match[2]),
        url: this.base + "/ver/" + match[1],
        title: "Episodio " + match[2],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const entry = parts[0];
    if (!/^[\w-]+-episodio-[\d.]+$/.test(entry || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const audio = ["latino", "castellano", "sub"].indexOf(parts[1]) >= 0 ? parts[1] : this._audio(entry.replace(/-episodio-[\d.]+$/, ""), "");
    const wanted = String(server || "default");
    if (wanted !== "default" && this.getSettings().episodeServers.indexOf(wanted) < 0) throw new Error("unknown server '" + wanted + "'");

    const watchUrl = this.base + "/ver/" + entry;
    const html = await this._page(watchUrl, this.base + "/");
    // One host: <a class="play-video repro-item cap" data-player="base64 of the embed URL">voe</a>
    const players = [];
    const unread = [];
    const re = /<a\b[^>]*\bdata-player="([^"]+)"[^>]*>/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      const url = this._base64(match[1]);
      if (!/^https?:\/\//.test(url)) continue;
      const name = this._serverOf(url);
      if (name) players.push({ server: name, url: url });
      else if (unread.indexOf(this._host(url)) < 0) unread.push(this._host(url));
    }
    if (players.length === 0 && !/data-player=/.test(html)) throw new Error("no player on the episode page");

    const video = await this._firstVideo(players, wanted, this.base + "/", unread);
    return {
      server: video.server,
      headers: video.headers,
      videoSources: [
        {
          url: video.url,
          type: video.type,
          quality: "auto",
          label: audio === "latino" ? "Latin American Spanish dub" : audio === "castellano" ? "Spain Spanish dub" : "Spanish subtitles",
          subtitles: [],
        },
      ],
    };
  }

  // ---------------------------------------------------------------- parsing

  // "Dandadan CR Latino", "Sousou no Frieren Audio Latino": the title without the audio and the
  // source of the copy.
  _clean(shown) {
    return shown.replace(/\s+(?:Audio\s+)?(Latino|Castellano)\s*$/i, "").replace(/\s+(CR|Crunchyroll|Netflix|1080p)\s*$/i, "").trim() || shown;
  }

  _words(text) {
    return " " + String(text || "").toLowerCase().normalize("NFD").replace(/[^a-z0-9]+/g, " ").trim() + " ";
  }

  // "latino", "castellano", "sub" (Japanese audio, Spanish subtitles) or "other" (Catalan dub).
  // The slug and title decide; the card's type label ("Pelicula Latino") only when they say nothing.
  _audio(slug, shown, kind) {
    const named = function (text) {
      const lower = String(text || "").toLowerCase();
      if (/(^|[\s-])latino(\s|$)/.test(lower)) return "latino";
      if (/(^|[\s-])castellano(\s|$)/.test(lower)) return "castellano";
      if (/catal[aá]n/.test(lower)) return "other";
      return "";
    };
    return named(slug.replace(/-/g, " ")) || named(shown) || named(kind) || "sub";
  }

  // ---------------------------------------------------------------- video hosts

  // The server name of an embed address, or "" for a host this extension cannot read.
  _serverOf(url) {
    const host = this._host(url);
    if (/mp4upload\./.test(host)) return "Mp4Upload";
    if (/(stream|player|embed|hls|ultra|cdn)wish\.|^wish|streamhg\./.test(host)) return "StreamWish";
    if (/^filemoon\.|^byse[a-z]*\./.test(host)) return "Filemoon";
    if (/filelions\.|vidhide|^lions/.test(host)) return "VidHide";
    if (/^lulu[a-z]*\./.test(host)) return "LuluStream";
    if (/^voe\./.test(host)) return "Voe";
    if (/^m[i1]xdr[o0]{1,2}p\.|^mxdrop\./.test(host)) return "MixDrop";
    if (/^uqload\./.test(host)) return "Uqload";
    if (/yourupload\./.test(host)) return "YourUpload";
    return "";
  }

  // `players`: [{ server, url }]. Tries them in the order of getSettings().episodeServers (or
  // only the wanted one) and answers the first video found as { server, url, type, headers }.
  async _firstVideo(players, wanted, referer, unread) {
    const order = this.getSettings().episodeServers;
    let candidates = players.filter(function (p) { return order.indexOf(p.server) >= 0; });
    if (wanted !== "default") {
      candidates = candidates.filter(function (p) { return p.server.toLowerCase() === wanted.toLowerCase(); });
      if (candidates.length === 0) throw new Error("the server '" + wanted + "' has no copy of this episode");
    } else {
      candidates.sort(function (a, b) { return order.indexOf(a.server) - order.indexOf(b.server); });
      if (candidates.length === 0) {
        throw new Error(unread && unread.length > 0
          ? "this extension can't read the video hosts " + unread.join(", ")
          : "this episode is only on video hosts this extension cannot play");
      }
    }
    const failures = [];
    for (const player of candidates) {
      try {
        const video = await this._video(player.server, player.url, referer);
        video.server = player.server;
        return video;
      } catch (error) {
        failures.push(player.server + ": " + this._errorText(error));
      }
    }
    throw new Error("no server answered (" + failures.join("; ") + ")");
  }

  // The playable address behind one embed page: { url, type, headers }.
  async _video(server, url, referer) {
    // The bare mp4upload.com address only redirects, and is unreachable on some networks;
    // mixdrop.is is a parked domain now, mixdrop.ag sends on to MixDrop's current one.
    if (server === "Filemoon") return this._byse(url);
    const embed = url.replace(/^https?:\/\/mp4upload\.com\//i, "https://www.mp4upload.com/").replace(/^https?:\/\/mixdrop\.is\//i, "https://mixdrop.ag/");
    let page = await this._get(embed, referer);
    if (server === "Voe") {
      // The embed page first sends the browser on to the host's current domain.
      const moved = /window\.location\.href\s*=\s*'(https?:\/\/[^']+)'/.exec(page.text);
      if (moved && page.text.indexOf("application/json") < 0) page = await this._get(moved[1], referer);
      return this._voe(page);
    }
    const origin = this._origin(page.url);
    if (this._gone(page.text)) throw new Error("the video was removed from the host");
    if (server === "Mp4Upload") {
      const source = /\bsrc:\s*"(https?:\/\/[^"]+)"/.exec(page.text);
      if (!source) throw new Error("Mp4Upload names no video");
      return { url: source[1], type: this._isHls(source[1]) ? "m3u8" : "mp4", headers: { Referer: origin + "/" } };
    }
    if (server === "YourUpload") {
      const source = /\bfile:\s*'(https?:\/\/[^']+\.mp4[^']*)'/.exec(page.text) || /property="og:video"\s+content="(https?:\/\/[^"]+)"/.exec(page.text);
      if (!source) throw new Error("YourUpload names no video");
      return { url: source[1], type: "mp4", headers: { Referer: origin + "/" } };
    }
    const script = page.text + "\n" + this._unpack(page.text);
    if (server === "MixDrop") {
      const source = /MDCore\.wurl\s*=\s*"([^"]+)"/.exec(script);
      if (!source) throw new Error("MixDrop names no video");
      return { url: this._absolute(source[1], page.url), type: "mp4", headers: { Referer: origin + "/" } };
    }
    // JW Player hosts (StreamWish, VidHide, LuluStream, Uqload): `links={hls4,hls2,…}` or `sources:[{file:…}]`.
    const found = [];
    const links = /\blinks\s*=\s*(\{[^}]*\})/.exec(script);
    if (links) {
      let named = null;
      try {
        named = JSON.parse(links[1]);
      } catch (error) {
        named = null;
      }
      for (const key of ["hls4", "hls2", "hls3"]) {
        if (named && typeof named[key] === "string" && named[key]) found.push(this._absolute(named[key], page.url));
      }
    }
    const re = /sources\s*:\s*\[\s*\{\s*["']?file["']?\s*:\s*["']([^"']+)["']/g;
    let match;
    while ((match = re.exec(script)) !== null) found.push(this._absolute(match[1], page.url));
    for (const address of this._mediaUrls(script)) found.push(address);
    const playable = found.filter(function (address) { return /^https?:\/\//.test(address) && !/\.(?:jpg|png|vtt|srt)(?:[?#]|$)/i.test(address); });
    if (playable.length === 0) throw new Error(server + " names no video");
    const video = playable[0];
    return { url: video, type: this._isHls(video) || /\/master\.txt(?:[?#]|$)/.test(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // VOE keeps its player settings in a JSON string: ROT13, marker strings, base64, a shift of
  // three, reversed, base64 again.
  _voe(page) {
    const packed = /<script type="application\/json">\s*\["([^"]+)"\]/.exec(page.text);
    if (!packed) throw new Error(this._gone(page.text) ? "the video was removed from VOE" : "the VOE page has changed");
    let text = packed[1].replace(/[a-zA-Z]/g, function (c) {
      const base = c <= "Z" ? 65 : 97;
      return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);
    });
    for (const marker of ["@$", "^^", "~@", "%?", "*~", "!!", "#&"]) text = text.split(marker).join("");
    let settings = null;
    try {
      const shifted = Array.from(String(atob(text)), function (c) { return String.fromCharCode(c.charCodeAt(0) - 3); }).join("");
      settings = JSON.parse(String(atob(shifted.split("").reverse().join(""))));
    } catch (error) {
      settings = null;
    }
    const video = settings && (settings.source || settings.direct_access_url);
    if (typeof video !== "string" || !/^https?:\/\//.test(video)) throw new Error("the VOE page names no video");
    const origin = this._origin(page.url);
    return { url: video, type: this._isHls(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // Filemoon's "Byse" player: /api/videos/<code> answers the sources AES-256-GCM encrypted, the
  // key split among `key_parts`.
  async _byse(url) {
    const code = /\/(?:e|d)\/(\w+)/.exec(url);
    if (!code) throw new Error("Filemoon address has no video code");
    const origin = this._origin(url);
    const page = await this._get(origin + "/api/videos/" + code[1], url);
    let info = null;
    try {
      info = JSON.parse(page.text);
    } catch (error) {
      info = null;
    }
    const playback = info && info.playback;
    if (!playback || typeof playback.payload !== "string") throw new Error(this._gone(page.text) ? "the video was removed from Filemoon" : "the Filemoon answer has changed");
    let opened = null;
    try {
      opened = JSON.parse(this._byseOpen(playback));
    } catch (error) {
      opened = null;
    }
    const sources = (opened && Array.isArray(opened.sources) ? opened.sources : []).filter(function (s) { return s && /^https?:\/\//.test(String(s.url)); });
    if (sources.length === 0) throw new Error("Filemoon names no video");
    const video = sources[0];
    const hls = this._isHls(video.url) || /mpegurl/i.test(String(video.mime_type));
    return { url: video.url, type: hls ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // The player's rule: version n (1-20) takes parts n and 31-n as the key, otherwise all of them.
  // GCM decryption is AES-CTR from counter 2; shortcut: the tag is not checked (a wrong key fails at JSON.parse).
  _byseOpen(playback) {
    const bytes = function (text) {
      const plain = String(text).replace(/-/g, "+").replace(/_/g, "/").replace(/=+$/, "");
      const binary = atob(plain + "===".slice((plain.length + 3) % 4));
      return Uint8Array.from(binary, function (c) { return c.charCodeAt(0); });
    };
    const parts = Array.isArray(playback.key_parts) ? playback.key_parts : [];
    const n = Number(playback.version);
    const picked = n >= 1 && n <= 20 && 31 - n <= parts.length ? [parts[n - 1], parts[30 - n]] : parts;
    const pieces = picked.filter(function (p) { return typeof p === "string" && p; }).map(bytes);
    const key = new Uint8Array(pieces.reduce(function (sum, p) { return sum + p.length; }, 0));
    pieces.reduce(function (at, p) { key.set(p, at); return at + p.length; }, 0);
    const iv = bytes(playback.iv);
    const data = bytes(playback.payload);
    if (key.length !== 32 || iv.length !== 12 || data.length <= 16) throw new Error("the Filemoon key has changed");
    const body = data.subarray(0, data.length - 16);
    const counters = new Uint8Array(Math.ceil(body.length / 16) * 16);
    for (let i = 0; i * 16 < counters.length; i += 1) {
      counters.set(iv, i * 16);
      const count = i + 2;
      counters.set([(count >>> 24) & 255, (count >>> 16) & 255, (count >>> 8) & 255, count & 255], i * 16 + 12);
    }
    const stream = bytes(CryptoJS.AES.encrypt(counters, key, { mode: CryptoJS.mode.ECB, padding: CryptoJS.pad.NoPadding }).toString(CryptoJS.enc.Base64));
    let text = "";
    for (let i = 0; i < body.length; i += 1) text += String.fromCharCode(body[i] ^ stream[i]);
    return CryptoJS.enc.Utf8.stringify(CryptoJS.enc.Latin1.parse(text));
  }

  _gone(body) {
    return /File is no longer available|File was deleted|can't find the video you are looking for|file you were looking for (?:could not be found|was deleted)|Video not found|has been removed|404 - Not found/i.test(body);
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as { text, url } (url: the address after redirects). `referer` is a URL, or an
  // object of request headers. `init` may carry `method`, `body` and `contentType`.
  async _get(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  async _page(url, referer, init) {
    return (await this._get(url, referer, init)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _base64(text) {
    try {
      return String(atob(String(text).trim()));
    } catch (error) {
      return "";
    }
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }
}

// MonosChinos (monoschinos2.net): anime with Spanish subtitles, and Latin American Spanish
// ("… Latino") and Spain Spanish ("… Castellano") dubs as separate entries of the site.
// Episodes play from third-party video hosts (StreamWish, Filemoon, VidHide, LuluStream, VOE,
// Mp4Upload, YourUpload, Uqload, MixDrop).

class Provider {
  constructor() {
    this.base = "https://vww.monoschinos2.net";
  }

  getSettings() {
    return {
      episodeServers: ["StreamWish", "Filemoon", "VidHide", "LuluStream", "Voe", "Mp4Upload", "YourUpload", "Uqload", "MixDrop"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const wantDub = !!(opts && opts.dub);

    const results = [];
    for (const query of queries) {
      // Results come 30 to a page; the main series can be on a later one (One Piece is on page 2).
      const cards = [];
      for (let page = 1; page <= 5; page += 1) {
        const html = await this._page(this.base + "/animes?buscar=" + encodeURIComponent(query).replace(/%20/g, "+") + (page > 1 ? "&pag=" + page : ""), this.base + "/");
        // One card: <a href="./anime/slug" title="Ver Anime … Online Gratis"> … <h3 …>Title</h3>
        // <span class="text-muted fs-6">Anime</span></a>
        cards.push.apply(cards, html.split(/<a href="(?=\.\/anime\/)/).slice(1));
        if (html.indexOf("pag=" + (page + 1) + '"') < 0) break;
      }
      for (const card of cards) {
        const slug = /^\.\/anime\/([\w-]+)"/.exec(card);
        const body = card.split("</a>")[0];
        const heading = /<h3\b[^>]*>([\s\S]*?)<\/h3>/.exec(body);
        if (!slug || !heading || results.some(function (r) { return r.id.split("|")[0] === slug[1]; })) continue;
        const shown = this._plain(heading[1]);
        const audio = this._audio(slug[1], shown);
        if (audio === "other" || (audio !== "sub") !== wantDub) continue;
        const title = shown.replace(/\s+(Latino|Castellano)\s*$/i, "").trim() || shown;
        results.push({
          id: slug[1] + "|" + audio,
          title: title,
          url: this.base + "/anime/" + slug[1],
          subOrDub: audio === "sub" ? "sub" : "dub",
          altTitles: title !== shown ? [shown] : [],
        });
      }
      if (results.length > 0) break;
    }
    // Latin American dubs first, then Spain's.
    results.sort(function (a, b) { return (/\|castellano$/.test(a.id) ? 1 : 0) - (/\|castellano$/.test(b.id) ? 1 : 0); });
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    if (!/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");
    const audio = ["latino", "castellano", "sub"].indexOf(parts[1]) >= 0 ? parts[1] : this._audio(slug, "");

    const pageUrl = this.base + "/anime/" + slug;
    const html = await this._page(pageUrl, this.base + "/");
    // <section … id="dt" data-e="28" data-i="3870" data-u="slug">: episode count, the site's id.
    const info = /<[^>]*\bdata-e="(\d+)"[^>]*>/.exec(html);
    const siteId = info ? this._attr(info[0], "data-i") : "";
    const siteSlug = info ? this._attr(info[0], "data-u") || slug : slug;
    if (!info || !siteId) throw new Error(/Just a moment|cf-chl/.test(html) ? "blocked by the site's bot protection" : "the anime page has changed");

    // The list comes in pages of 50, newest first. The page's count can be short by one or two,
    // so pages are read until one is not full.
    const episodes = [];
    const seen = {};
    const headers = { Referer: pageUrl, "X-Requested-With": "XMLHttpRequest" };
    const read = (page) => this._page(this.base + "/ajax_pagination", headers,
      { method: "POST", body: "acc=episodes&i=" + encodeURIComponent(siteId) + "&u=" + encodeURIComponent(siteSlug) + "&p=" + page });
    // Up to six of the counted pages load at once: a long series (One Piece, 24 pages) read one
    // page at a time does not fit the call's time limit.
    const known = Math.min(40, Math.ceil(Number(info[1]) / 50));
    const pending = {};
    for (let page = 1; page <= 40; page += 1) {
      for (let next = page; next <= Math.min(known, page + 5); next += 1) if (!pending[next]) pending[next] = read(next);
      const list = await (pending[page] || read(page));
      const re = /href="https:\/\/[^"\/]+\/ver\/([\w-]+?-episodio-(\d+(?:\.\d+)?))"/g;
      let listed = 0;
      let match;
      while ((match = re.exec(list)) !== null) {
        if (seen[match[2]]) continue;
        seen[match[2]] = true;
        listed += 1;
        episodes.push({
          id: match[1] + "|" + audio,
          number: Number(match[2]),
          url: this.base + "/ver/" + match[1],
          title: "Episodio " + match[2],
        });
      }
      if (listed < 50) break;
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const entry = parts[0];
    if (!/^[\w-]+-episodio-[\d.]+$/.test(entry || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const audio = ["latino", "castellano", "sub"].indexOf(parts[1]) >= 0 ? parts[1] : this._audio(entry.replace(/-episodio-[\d.]+$/, ""), "");
    const wanted = String(server || "default");
    if (wanted !== "default" && this.getSettings().episodeServers.indexOf(wanted) < 0) throw new Error("unknown server '" + wanted + "'");

    const watchUrl = this.base + "/ver/" + entry;
    const html = await this._page(watchUrl, this.base + "/");
    const key = /\bdata-encrypt="([^"]+)"/.exec(html);
    if (!key) throw new Error(/Just a moment|cf-chl/.test(html) ? "blocked by the site's bot protection" : "no player on the episode page");
    const options = await this._page(this.base + "/ajax_pagination", { Referer: watchUrl, "X-Requested-With": "XMLHttpRequest" },
      { method: "POST", body: "acc=opt&i=" + encodeURIComponent(key[1]) });
    // One host: <button class="play-video …" data-player="base64 of the embed URL">voe</button>
    const players = [];
    const re = /\bdata-player="([^"]+)"/g;
    let match;
    while ((match = re.exec(options)) !== null) {
      const url = this._base64(match[1]);
      const name = this._serverOf(url);
      if (/^https?:\/\//.test(url) && name && !players.some(function (p) { return p.url === url; })) players.push({ server: name, url: url });
    }
    if (players.length === 0 && !/data-player=/.test(options)) throw new Error("the site lists no video host for this episode");

    const video = await this._firstVideo(players, wanted, this.base + "/");
    return {
      server: video.server,
      headers: video.headers,
      videoSources: [
        {
          url: video.url,
          type: video.type,
          quality: "auto",
          label: audio === "latino" ? "Latin American Spanish dub" : audio === "castellano" ? "Spain Spanish dub" : "Spanish subtitles",
          subtitles: [],
        },
      ],
    };
  }

  // ---------------------------------------------------------------- parsing

  // "latino", "castellano", "sub" (Japanese audio, Spanish subtitles) or "other" (Catalan dub).
  _audio(slug, shown) {
    const named = function (text) {
      const lower = String(text || "").toLowerCase();
      if (/(^|[\s-])latino(\s|$)/.test(lower)) return "latino";
      if (/(^|[\s-])castellano(\s|$)/.test(lower)) return "castellano";
      if (/(^|[\s-])catal[aá]n(\s|$)/.test(lower)) return "other";
      return "";
    };
    return named(slug.replace(/-/g, " ")) || named(shown) || "sub";
  }

  // ---------------------------------------------------------------- video hosts

  // The server name of an embed address, or "" for a host this extension cannot read.
  _serverOf(url) {
    const host = this._host(url);
    if (/mp4upload\./.test(host)) return "Mp4Upload";
    if (/^byse[a-z]*\./.test(host)) return "Filemoon";
    if (/(stream|player|embed|hls|ultra|cdn)wish\.|^wish|streamhg\./.test(host)) return "StreamWish";
    if (/filelions\.|vidhide|^lions/.test(host)) return "VidHide";
    if (/lulu(vdo|stream)?\./.test(host)) return "LuluStream";
    if (/^voe\./.test(host)) return "Voe";
    if (/^m[i1]xdr[o0]{1,2}p\.|^mxdrop\./.test(host)) return "MixDrop";
    if (/^uqload\./.test(host)) return "Uqload";
    if (/yourupload\./.test(host)) return "YourUpload";
    return "";
  }

  // `players`: [{ server, url }]. Tries them in the order of getSettings().episodeServers (or
  // only the wanted one) and answers the first video found as { server, url, type, headers }.
  async _firstVideo(players, wanted, referer) {
    const order = this.getSettings().episodeServers;
    let candidates = players.filter(function (p) { return order.indexOf(p.server) >= 0; });
    if (wanted !== "default") {
      candidates = candidates.filter(function (p) { return p.server.toLowerCase() === wanted.toLowerCase(); });
      if (candidates.length === 0) throw new Error("the server '" + wanted + "' has no copy of this episode");
    } else {
      candidates.sort(function (a, b) { return order.indexOf(a.server) - order.indexOf(b.server); });
      if (candidates.length === 0) throw new Error("this episode is only on video hosts this extension cannot play");
    }
    const failures = [];
    for (const player of candidates) {
      try {
        const video = await this._video(player.server, player.url, referer);
        video.server = player.server;
        return video;
      } catch (error) {
        failures.push(player.server + ": " + this._errorText(error));
      }
    }
    throw new Error("no server answered (" + failures.join("; ") + ")");
  }

  // The playable address behind one embed page: { url, type, headers }.
  async _video(server, url, referer) {
    if (server === "Filemoon") return this._byse(url);
    // The bare mp4upload.com address only redirects, and is unreachable on some networks.
    let page = await this._get(url.replace(/^https?:\/\/mp4upload\.com\//i, "https://www.mp4upload.com/"), referer);
    if (server === "Voe") {
      // The embed page first sends the browser on to the host's current domain.
      const moved = /window\.location\.href\s*=\s*'(https?:\/\/[^']+)'/.exec(page.text);
      if (moved && page.text.indexOf("application/json") < 0) page = await this._get(moved[1], referer);
      return this._voe(page);
    }
    const origin = this._origin(page.url);
    if (this._gone(page.text)) throw new Error("the video was removed from the host");
    if (server === "Mp4Upload") {
      const source = /\bsrc:\s*"(https?:\/\/[^"]+)"/.exec(page.text);
      if (!source) throw new Error("Mp4Upload names no video");
      return { url: source[1], type: this._isHls(source[1]) ? "m3u8" : "mp4", headers: { Referer: origin + "/" } };
    }
    if (server === "YourUpload") {
      const source = /\bfile:\s*'(https?:\/\/[^']+\.mp4[^']*)'/.exec(page.text) || /property="og:video"\s+content="(https?:\/\/[^"]+)"/.exec(page.text);
      if (!source) throw new Error("YourUpload names no video");
      return { url: source[1], type: "mp4", headers: { Referer: origin + "/" } };
    }
    const script = page.text + "\n" + this._unpack(page.text);
    if (server === "MixDrop") {
      const source = /MDCore\.wurl\s*=\s*"([^"]+)"/.exec(script);
      if (!source) throw new Error("MixDrop names no video");
      return { url: this._absolute(source[1], page.url), type: "mp4", headers: { Referer: origin + "/" } };
    }
    // JW Player hosts (StreamWish, VidHide, LuluStream, Uqload): `links={hls4,hls2,…}` or `sources:[{file:…}]`.
    const found = [];
    const links = /\blinks\s*=\s*(\{[^}]*\})/.exec(script);
    if (links) {
      let named = null;
      try {
        named = JSON.parse(links[1]);
      } catch (error) {
        named = null;
      }
      for (const key of ["hls4", "hls2", "hls3"]) {
        if (named && typeof named[key] === "string" && named[key]) found.push(this._absolute(named[key], page.url));
      }
    }
    const re = /sources\s*:\s*\[\s*\{\s*["']?file["']?\s*:\s*["']([^"']+)["']/g;
    let match;
    while ((match = re.exec(script)) !== null) found.push(this._absolute(match[1], page.url));
    for (const address of this._mediaUrls(script)) found.push(address);
    const playable = found.filter(function (address) { return /^https?:\/\//.test(address) && !/\.(?:jpg|png|vtt|srt)(?:[?#]|$)/i.test(address); });
    if (playable.length === 0) throw new Error(server + " names no video");
    const video = playable[0];
    return { url: video, type: this._isHls(video) || /\/master\.txt(?:[?#]|$)/.test(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // VOE keeps its player settings in a JSON string: ROT13, marker strings, base64, a shift of
  // three, reversed, base64 again.
  _voe(page) {
    const packed = /<script type="application\/json">\s*\["([^"]+)"\]/.exec(page.text);
    if (!packed) throw new Error(this._gone(page.text) ? "the video was removed from VOE" : "the VOE page has changed");
    let text = packed[1].replace(/[a-zA-Z]/g, function (c) {
      const base = c <= "Z" ? 65 : 97;
      return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);
    });
    for (const marker of ["@$", "^^", "~@", "%?", "*~", "!!", "#&"]) text = text.split(marker).join("");
    let settings = null;
    try {
      const shifted = Array.from(String(atob(text)), function (c) { return String.fromCharCode(c.charCodeAt(0) - 3); }).join("");
      settings = JSON.parse(String(atob(shifted.split("").reverse().join(""))));
    } catch (error) {
      settings = null;
    }
    const video = settings && (settings.source || settings.direct_access_url);
    if (typeof video !== "string" || !/^https?:\/\//.test(video)) throw new Error("the VOE page names no video");
    const origin = this._origin(page.url);
    return { url: video, type: this._isHls(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // Filemoon's "Byse" player: /api/videos/<code> answers the sources AES-256-GCM encrypted, the
  // key split among `key_parts`.
  async _byse(url) {
    const code = /\/(?:e|d)\/(\w+)/.exec(url);
    if (!code) throw new Error("Filemoon address has no video code");
    const origin = this._origin(url);
    const page = await this._get(origin + "/api/videos/" + code[1], url);
    let info = null;
    try {
      info = JSON.parse(page.text);
    } catch (error) {
      info = null;
    }
    const playback = info && info.playback;
    if (!playback || typeof playback.payload !== "string") throw new Error(this._gone(page.text) ? "the video was removed from Filemoon" : "the Filemoon answer has changed");
    let opened = null;
    try {
      opened = JSON.parse(this._byseOpen(playback));
    } catch (error) {
      opened = null;
    }
    const sources = (opened && Array.isArray(opened.sources) ? opened.sources : []).filter(function (s) { return s && /^https?:\/\//.test(String(s.url)); });
    if (sources.length === 0) throw new Error("Filemoon names no video");
    const video = sources[0];
    const hls = this._isHls(video.url) || /mpegurl/i.test(String(video.mime_type));
    return { url: video.url, type: hls ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // The player's rule: version n (1-20) takes parts n and 31-n as the key, otherwise all of them.
  // GCM decryption is AES-CTR from counter 2; shortcut: the tag is not checked (a wrong key fails at JSON.parse).
  _byseOpen(playback) {
    const bytes = function (text) {
      const plain = String(text).replace(/-/g, "+").replace(/_/g, "/").replace(/=+$/, "");
      const binary = atob(plain + "===".slice((plain.length + 3) % 4));
      return Uint8Array.from(binary, function (c) { return c.charCodeAt(0); });
    };
    const parts = Array.isArray(playback.key_parts) ? playback.key_parts : [];
    const n = Number(playback.version);
    const picked = n >= 1 && n <= 20 && 31 - n <= parts.length ? [parts[n - 1], parts[30 - n]] : parts;
    const pieces = picked.filter(function (p) { return typeof p === "string" && p; }).map(bytes);
    const key = new Uint8Array(pieces.reduce(function (sum, p) { return sum + p.length; }, 0));
    pieces.reduce(function (at, p) { key.set(p, at); return at + p.length; }, 0);
    const iv = bytes(playback.iv);
    const data = bytes(playback.payload);
    if (key.length !== 32 || iv.length !== 12 || data.length <= 16) throw new Error("the Filemoon key has changed");
    const body = data.subarray(0, data.length - 16);
    const counters = new Uint8Array(Math.ceil(body.length / 16) * 16);
    for (let i = 0; i * 16 < counters.length; i += 1) {
      counters.set(iv, i * 16);
      const count = i + 2;
      counters.set([(count >>> 24) & 255, (count >>> 16) & 255, (count >>> 8) & 255, count & 255], i * 16 + 12);
    }
    const stream = bytes(CryptoJS.AES.encrypt(counters, key, { mode: CryptoJS.mode.ECB, padding: CryptoJS.pad.NoPadding }).toString(CryptoJS.enc.Base64));
    let text = "";
    for (let i = 0; i < body.length; i += 1) text += String.fromCharCode(body[i] ^ stream[i]);
    return CryptoJS.enc.Utf8.stringify(CryptoJS.enc.Latin1.parse(text));
  }

  _gone(body) {
    return /File is no longer available|File was deleted|file you were looking for (?:could not be found|was deleted)|Video not found|has been removed|404 - Not found/i.test(body);
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as { text, url } (url: the address after redirects). `referer` is a URL, or an
  // object of request headers. `init` may carry `method`, `body` and `contentType`.
  async _get(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  async _page(url, referer, init) {
    return (await this._get(url, referer, init)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _base64(text) {
    try {
      return String(atob(String(text).trim()));
    } catch (error) {
      return "";
    }
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }
}

// AniTube (anitube.zip): anime with Brazilian Portuguese subtitles (burnt in, "Legendado") and
// Brazilian Portuguese dubs ("Dublado") as separate entries of the site. Episodes play as HLS
// from the site's own player, or as MP4 from Blogger.

class Provider {
  constructor() {
    this.base = "https://www.anitube.zip";
  }

  getSettings() {
    return {
      episodeServers: ["AniTube", "Blogger"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
      // One card: <div class="aniItem"><a href="https://www.anitube.zip/video/920758/"
      // title="Sousou no Frieren – Todos os Episódios"> … <div class="aniCC">Legendado</div>
      const cards = html.split(/<div class="aniItem">/).slice(1);
      for (const card of cards) {
        const link = /<a\b[^>]*>/.exec(card);
        if (!link) continue;
        // Older entries link as /897019b002 or /video/37785z001.
        const path = /^https?:\/\/[^\/]+\/((?:video\/)?\d+(?:[bz]\d+)?\/?)$/.exec(this._attr(link[0], "href"));
        const shown = this._attr(link[0], "title").replace(/\s+[–-]\s+Todos (?:os )?Epis[oó]dios\s*$/i, "").trim();
        if (!path || !shown || results.some(function (r) { return r.id.split("|")[0] === path[1]; })) continue;
        const label = /<div class="aniCC">\s*([^<]*?)\s*<\/div>/.exec(card);
        const isDub = (label && /dublado/i.test(label[1])) || /\bDublado\b/i.test(shown);
        if (isDub !== (audio === "dub")) continue;
        const title = shown.replace(/\s*\((?:Dublado|Legendado)\)|\s+(?:Dublado|Cl[aá]ssico)(?![\wÀ-ÿ])/gi, "").replace(/\s+/g, " ").trim() || shown;
        results.push({
          id: path[1] + "|" + audio,
          title: title,
          url: this.base + "/" + path[1],
          subOrDub: audio,
          altTitles: title !== shown ? [shown] : [],
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const path = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^(?:video\/)?\d+(?:[bz]\d+)?\/?$/.test(path || "")) throw new Error("invalid anime id '" + id + "'");

    const html = await this._page(this.base + "/" + path, this.base + "/");
    const start = html.indexOf('class="pagAniListaContainer');
    if (start < 0) throw new Error("no episodes listed");
    // One entry: <a href="https://www.anitube.zip/video/920763/" title="…">Title – Episódio 01</a>
    const episodes = [];
    const seen = {};
    const re = /<a href="https?:\/\/[^\/"]+\/([^"]+)" title="[^"]*">([^<]*)<\/a>/g;
    re.lastIndex = start;
    let match;
    while ((match = re.exec(html)) !== null) {
      const numbered = /Epis[oó]dio\s+(\d+(?:\.\d+)?)/i.exec(match[2]);
      if (!numbered) continue;
      const number = Number(numbered[1]);
      if (seen[number]) continue;
      seen[number] = true;
      episodes.push({
        id: match[1] + "|" + audio,
        number: number,
        url: this.base + "/" + match[1],
        title: "Episódio " + number,
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const path = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[\w\/-]+$/.test(path || "") || path.indexOf("..") >= 0) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && this.getSettings().episodeServers.indexOf(wanted) < 0) throw new Error("unknown server '" + wanted + "'");

    const watchUrl = this.base + "/" + path;
    const html = await this._page(watchUrl, this.base + "/");
    // <div id="blog2" …><iframe src="https://api.anivideo.net/videohls.php?d=<playlist>&nocache…">
    // <div id="blog1" …><iframe src="https://www.anitube.zip/<code>/0/0/bg.mp4?…"> (Blogger)
    const frameIn = function (box) {
      const at = html.indexOf('id="' + box + '"');
      const rest = at >= 0 ? html.slice(at + 4) : "";
      const next = rest.search(/id="blog\d"/);
      const frame = /<iframe\b[^>]*>/i.exec(next >= 0 ? rest.slice(0, next) : rest);
      return frame ? frame[0] : "";
    };
    const label = audio === "dub" ? "Brazilian Portuguese dub" : "Brazilian Portuguese hard sub";
    const failures = [];

    if (wanted === "default" || wanted === "AniTube") {
      try {
        const source = this._attr(frameIn("blog2"), "src");
        if (!source) throw new Error("the episode has no HLS player");
        const frame = this._absolute(source, watchUrl);
        let video = /[?&]d=(https?:\/\/[^&]+\.m3u8)/.exec(frame);
        let playlist = video ? video[1] : "";
        if (!playlist) {
          const player = await this._page(frame, watchUrl);
          video = /\bfile:\s*'(https?:\/\/[^']+)'/.exec(player) || /\bfile:\s*"(https?:\/\/[^"]+)"/.exec(player);
          playlist = video ? video[1] : "";
        }
        if (!playlist) throw new Error("the HLS player names no video");
        return {
          server: "AniTube",
          headers: { Referer: this._origin(frame) + "/" },
          videoSources: [{ url: playlist, type: this._isHls(playlist) ? "m3u8" : "mp4", quality: "auto", label: label, subtitles: [] }],
        };
      } catch (error) {
        failures.push("AniTube: " + this._errorText(error));
      }
    }

    // The Blogger box opens the site's redirect to a page that frames the Blogger video.
    if (wanted === "default" || wanted === "Blogger") {
      try {
        const source = this._attr(frameIn("blog1"), "src");
        if (!source) throw new Error("the episode has no Blogger player");
        const frame = this._absolute(source, watchUrl);
        let blogger = frame;
        if (this._host(frame) !== "www.blogger.com") {
          const holder = await this._page(frame, watchUrl);
          const inner = /<iframe\b[^>]*\bsrc="(https:\/\/www\.blogger\.com\/video\.g\?[^"]+)"/i.exec(holder);
          if (!inner) throw new Error("the player frames no Blogger video");
          blogger = this._unescapeBody(inner[1]);
        }
        const files = await this._blogger(blogger, "https://www.blogger.com/");
        return {
          server: "Blogger",
          headers: {},
          videoSources: files.map(function (file) {
            return { url: file.url, type: "mp4", quality: file.quality, label: label, subtitles: [] };
          }),
        };
      } catch (error) {
        failures.push("Blogger: " + this._errorText(error));
      }
    }
    throw new Error("no server answered (" + failures.join("; ") + ")");
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as { text, url } (url: the address after redirects). `referer` is a URL, or an
  // object of request headers. `init` may carry `method`, `body` and `contentType`.
  async _get(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  async _page(url, referer, init) {
    return (await this._get(url, referer, init)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _base64(text) {
    try {
      return String(atob(String(text).trim()));
    } catch (error) {
      return "";
    }
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }

  // A Blogger video (blogger.com/video.g?token=…): its MP4 files, best first, as
  // [{ url, quality }]. The page names them itself or through the player's data request.
  async _blogger(url, referer) {
    const page = await this._page(url, referer);
    const found = [];
    const add = function (address, itag) {
      const quality = { 18: "360p", 22: "720p", 37: "1080p", 59: "480p" }[itag];
      if (!quality || !/^https:\/\//.test(address) || found.some(function (f) { return f.quality === quality; })) return;
      found.push({ url: address, quality: quality });
    };

    const listed = /"streams":\[([\s\S]*?)\]/.exec(page);
    if (listed && page.indexOf("errorContainer") < 0) {
      const re = /"play_url":"([^"]+)"[^}]*?"format_id":(\d+)/g;
      let match;
      while ((match = re.exec(listed[1])) !== null) add(this._unescapeBody(match[1]), parseInt(match[2], 10));
    }
    if (found.length === 0) {
      const token = /[?&]token=([^&#]+)/.exec(url);
      const session = /"FdrFJe":"([^"]+)"/.exec(page);
      const build = /"cfb2h":"([^"]+)"/.exec(page);
      if (!token || !session || !build) throw new Error("the Blogger video page has changed");
      const origin = this._origin(url);
      const request = JSON.stringify([[["WcwnYd", JSON.stringify([token[1], "", 0]), null, "generic"]]]);
      const answer = await this._page(
        origin + "/_/BloggerVideoPlayerUi/data/batchexecute?rpcids=WcwnYd&source-path=%2Fvideo.g&f.sid=" + encodeURIComponent(session[1]) +
          "&bl=" + encodeURIComponent(build[1]) + "&hl=en-US&_reqid=" + (Math.floor(Date.now() / 1000) % 86400) + "&rt=c",
        { Referer: origin + "/", "x-same-domain": "1" },
        { method: "POST", body: "f.req=" + encodeURIComponent(request) + "&", contentType: "application/x-www-form-urlencoded;charset=UTF-8" }
      );
      for (const line of answer.split("\n")) {
        if (line.indexOf('[["wrb.fr"') !== 0) continue;
        let streams = null;
        try {
          streams = JSON.parse(JSON.parse(line)[0][2])[2];
        } catch (error) {
          streams = null;
        }
        for (const stream of Array.isArray(streams) ? streams : []) {
          if (Array.isArray(stream) && typeof stream[0] === "string" && Array.isArray(stream[1])) add(stream[0], stream[1][0]);
        }
      }
    }
    if (found.length === 0) throw new Error("the Blogger video is not available");
    found.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return found;
  }
}

// Animes Digital (animesdigital.org): anime with Brazilian Portuguese subtitles (burnt in) and
// Brazilian Portuguese dubs ("… Dublado") as separate entries of the site. Episodes play as HLS
// from the site's own player, or as MP4 from Blogger.

class Provider {
  constructor() {
    this.base = "https://animesdigital.org";
  }

  getSettings() {
    return {
      episodeServers: ["AnimesDigital", "Blogger"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/pesquisa/?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
      // One card: <div class="itemA"><a href="https://animesdigital.org/anime/a/slug" title="…"> …
      // <span class="title_anime">Sousou no Frieren Dublado</span></a>
      const cards = html.split(/<div class="itemA">/).slice(1);
      for (const card of cards) {
        const link = /<a\b[^>]*>/.exec(card);
        if (!link) continue;
        const slug = /^https?:\/\/[^\/]+\/anime\/a\/([\w-]+)\/?$/.exec(this._attr(link[0], "href"));
        const heading = /class="title_anime">([\s\S]*?)<\/span>/.exec(card.split("</a>")[0]);
        if (!slug || !heading || results.some(function (r) { return r.id.split("|")[0] === slug[1]; })) continue;
        const shown = this._plain(heading[1]);
        const isDub = /\bDublado\b/i.test(shown) || /-dublado(-|$)/.test(slug[1]);
        if (isDub !== (audio === "dub")) continue;
        const title = shown.replace(/\s*\(Dublado\)|\s+Dublado\b/gi, "").replace(/\s+[–-]\s+Todos os Epis[oó]dios\s*$/i, "").replace(/\s+/g, " ").trim() || shown;
        results.push({
          id: slug[1] + "|" + audio,
          title: title,
          url: this.base + "/anime/a/" + slug[1],
          subOrDub: audio,
          altTitles: title !== shown ? [shown] : [],
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    const first = await this._get(this.base + "/anime/a/" + slug, this.base + "/");
    // Long series list 50 episodes per page: <div class="content-pagination"> … <a href="…/page/10/">
    const pages = [first.text];
    const listed = /class="content-pagination\b[\s\S]*?<\/ul>/.exec(first.text);
    if (listed) {
      let last = 1;
      let folder = "";
      const re = /href="(https?:\/\/[^"]+?\/)page\/(\d+)\/?"/g;
      let match;
      while ((match = re.exec(listed[0])) !== null) {
        if (parseInt(match[2], 10) > last) last = parseInt(match[2], 10);
        folder = match[1];
      }
      // Fetched 8 at a time: one by one, a ~1,200-episode series outlasts the episode-list deadline.
      for (let page = 2; page <= Math.min(last, 40) && folder; page += 8) {
        const batch = [];
        for (let n = page; n < page + 8 && n <= Math.min(last, 40); n += 1) batch.push(this._page(folder + "page/" + n + "/", first.url));
        for (const html of await Promise.all(batch)) pages.push(html);
      }
    }

    // One entry: <a href="https://animesdigital.org/video/a/112846/" class="b_flex"> …
    // <div class="title_anime">Sousou no Frieren Episódio 28</div>
    const episodes = [];
    const seen = {};
    for (const html of pages) {
      const re = /<a href="https?:\/\/[^\/"]+\/(video\/a\/[\w-]+\/?)"\s+class="b_flex">([\s\S]*?)<\/a>/g;
      let match;
      while ((match = re.exec(html)) !== null) {
        const name = /class="title_anime">([^<]*)</.exec(match[2]);
        const numbered = name ? /Epis[oó]dio\s+(\d+(?:\.\d+)?)/i.exec(name[1]) : null;
        if (!numbered) continue;
        const number = Number(numbered[1]);
        if (seen[number]) continue;
        seen[number] = true;
        episodes.push({
          id: match[1] + "|" + audio,
          number: number,
          url: this.base + "/" + match[1],
          title: "Episódio " + number,
        });
      }
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const path = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^video\/a\/[\w-]+\/?$/.test(path || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    if (wanted !== "default" && this.getSettings().episodeServers.indexOf(wanted) < 0) throw new Error("unknown server '" + wanted + "'");

    const watchUrl = this.base + "/" + path;
    const html = await this._page(watchUrl, this.base + "/");
    // Players: https://api.anivideo.net/videohls.php?d=<playlist>&nocache… (HLS), and
    // https://animesdigital.org/<code>/<n>/bg.mp4?… which leads to a page framing a Blogger video.
    const frames = [];
    const re = /<iframe\b[^>]*>/gi;
    let match;
    while ((match = re.exec(html)) !== null) {
      const source = this._attr(match[0], "src");
      if (source) frames.push(this._absolute(source, watchUrl));
    }
    const label = audio === "dub" ? "Brazilian Portuguese dub" : "Brazilian Portuguese hard sub";
    const failures = [];

    if (wanted === "default" || wanted === "AnimesDigital") {
      try {
        const frame = frames.filter(function (f) { return /videohls\.php/.test(f); })[0];
        if (!frame) throw new Error("the episode has no HLS player");
        let video = /[?&]d=(https?:\/\/[^&]+\.m3u8)/.exec(frame);
        let playlist = video ? video[1] : "";
        if (!playlist) {
          const player = await this._page(frame, watchUrl);
          video = /\bfile:\s*'(https?:\/\/[^']+)'/.exec(player) || /\bfile:\s*"(https?:\/\/[^"]+)"/.exec(player);
          playlist = video ? video[1] : "";
        }
        if (!playlist) throw new Error("the HLS player names no video");
        return {
          server: "AnimesDigital",
          headers: { Referer: this._origin(frame) + "/" },
          videoSources: [{ url: playlist, type: this._isHls(playlist) ? "m3u8" : "mp4", quality: "auto", label: label, subtitles: [] }],
        };
      } catch (error) {
        failures.push("AnimesDigital: " + this._errorText(error));
      }
    }

    if (wanted === "default" || wanted === "Blogger") {
      try {
        const frame = frames.filter(function (f) { return /blogger\.com\/video\.g|\/bg\.mp4/.test(f); })[0];
        if (!frame) throw new Error("the episode has no Blogger player");
        let blogger = frame;
        if (this._host(frame) !== "www.blogger.com") {
          const holder = await this._page(frame, watchUrl);
          const inner = /<iframe\b[^>]*\bsrc="(https:\/\/www\.blogger\.com\/video\.g\?[^"]+)"/i.exec(holder);
          if (!inner) throw new Error("the player frames no Blogger video");
          blogger = this._unescapeBody(inner[1]);
        }
        const files = await this._blogger(blogger, "https://www.blogger.com/");
        return {
          server: "Blogger",
          headers: {},
          videoSources: files.map(function (file) {
            return { url: file.url, type: "mp4", quality: file.quality, label: label, subtitles: [] };
          }),
        };
      } catch (error) {
        failures.push("Blogger: " + this._errorText(error));
      }
    }
    throw new Error("no server answered (" + failures.join("; ") + ")");
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as { text, url } (url: the address after redirects). `referer` is a URL, or an
  // object of request headers. `init` may carry `method`, `body` and `contentType`.
  async _get(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  async _page(url, referer, init) {
    return (await this._get(url, referer, init)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    const origin = this._origin(base || this.base);
    if (url.charAt(0) === "/") return origin + url;
    const folder = String(base || this.base).split(/[?#]/)[0].replace(/\/[^\/]*$/, "/");
    return (/^https?:\/\/[^\/]+$/i.test(folder.replace(/\/$/, "")) ? origin + "/" : folder) + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _base64(text) {
    try {
      return String(atob(String(text).trim()));
    } catch (error) {
      return "";
    }
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /(https?:)?\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      let url = match[0].replace(/[);,\]}]+$/, "");
      if (!match[1]) {
        const before = text.charAt(match.index - 1);
        if (before !== '"' && before !== "'") continue;
        url = "https:" + url;
      }
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }

  // A Blogger video (blogger.com/video.g?token=…): its MP4 files, best first, as
  // [{ url, quality }]. The page names them itself or through the player's data request.
  async _blogger(url, referer) {
    const page = await this._page(url, referer);
    const found = [];
    const add = function (address, itag) {
      const quality = { 18: "360p", 22: "720p", 37: "1080p", 59: "480p" }[itag];
      if (!quality || !/^https:\/\//.test(address) || found.some(function (f) { return f.quality === quality; })) return;
      found.push({ url: address, quality: quality });
    };

    const listed = /"streams":\[([\s\S]*?)\]/.exec(page);
    if (listed && page.indexOf("errorContainer") < 0) {
      const re = /"play_url":"([^"]+)"[^}]*?"format_id":(\d+)/g;
      let match;
      while ((match = re.exec(listed[1])) !== null) add(this._unescapeBody(match[1]), parseInt(match[2], 10));
    }
    if (found.length === 0) {
      const token = /[?&]token=([^&#]+)/.exec(url);
      const session = /"FdrFJe":"([^"]+)"/.exec(page);
      const build = /"cfb2h":"([^"]+)"/.exec(page);
      if (!token || !session || !build) throw new Error("the Blogger video page has changed");
      const origin = this._origin(url);
      const request = JSON.stringify([[["WcwnYd", JSON.stringify([token[1], "", 0]), null, "generic"]]]);
      const answer = await this._page(
        origin + "/_/BloggerVideoPlayerUi/data/batchexecute?rpcids=WcwnYd&source-path=%2Fvideo.g&f.sid=" + encodeURIComponent(session[1]) +
          "&bl=" + encodeURIComponent(build[1]) + "&hl=en-US&_reqid=" + (Math.floor(Date.now() / 1000) % 86400) + "&rt=c",
        { Referer: origin + "/", "x-same-domain": "1" },
        { method: "POST", body: "f.req=" + encodeURIComponent(request) + "&", contentType: "application/x-www-form-urlencoded;charset=UTF-8" }
      );
      for (const line of answer.split("\n")) {
        if (line.indexOf('[["wrb.fr"') !== 0) continue;
        let streams = null;
        try {
          streams = JSON.parse(JSON.parse(line)[0][2])[2];
        } catch (error) {
          streams = null;
        }
        for (const stream of Array.isArray(streams) ? streams : []) {
          if (Array.isArray(stream) && typeof stream[0] === "string" && Array.isArray(stream[1])) add(stream[0], stream[1][0]);
        }
      }
    }
    if (found.length === 0) throw new Error("the Blogger video is not available");
    found.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return found;
  }
}

// AnimeToast (animetoast.cc): German subtitles (burnt in) and German dub. Sub and dub are separate
// entries of the site, named "… Ger Sub" and "… Ger Dub". Every entry lists its episodes once per
// video host (Voe, Vidmoly, Mp4Upload, …); newer entries load the host's player through the site's
// `get_episode_data` request instead.

class Provider {
  constructor() {
    this.base = "https://www.animetoast.cc";
    this.servers = ["Voe", "Vidmoly", "Mp4Upload"];
  }

  getSettings() {
    return {
      episodeServers: ["Voe", "Vidmoly", "Mp4Upload"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    const results = [];
    for (const query of queries) {
      for (let page = 1; page <= 2; page += 1) {
        const path = page === 1 ? "/" : "/page/" + page + "/";
        const html = await this._page(this.base + path + "?s=" + encodeURIComponent(query).replace(/%20/g, "+"), this.base + "/");
        // One result: <h3><a href="https://www.animetoast.cc/slug/" rel="74" title="Title Ger Sub">
        const re = /<h3>\s*<a\s+href="https?:\/\/(?:www\.)?animetoast\.cc\/([\w-]+)\/"[^>]*\btitle="([^"]*)"/g;
        let match;
        let found = 0;
        while ((match = re.exec(html)) !== null) {
          found += 1;
          const slug = match[1];
          const shown = this._plain(match[2]);
          if (!shown || results.some(function (r) { return r.id.split("|")[0] === slug; })) continue;
          const isDub = /\bGer\s*Dub\b/i.test(shown) || /-ger-dub$/.test(slug);
          if (isDub !== (audio === "dub")) continue;
          const title = shown.replace(/\s*\bGer\s*(?:Sub|Dub)\b\s*$/i, "").trim() || shown;
          results.push({
            id: slug + "|" + audio,
            title: title,
            url: this.base + "/" + slug + "/",
            subOrDub: audio,
          });
        }
        if (found === 0 || !/class="next page-numbers"|rel="next"/.test(html)) break;
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    if (!/^[\w-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    const html = await this._page(this.base + "/" + slug + "/", this.base + "/");
    const pageUrl = this.base + "/" + slug + "/";
    const listing = await this._listing(html);
    const numbers = [];
    const add = function (number) { if (numbers.indexOf(number) < 0) numbers.push(number); };
    for (const entry of listing.entries) add(entry.number);
    for (const range of listing.ranges) {
      if (range.to) {
        for (let number = range.from; number <= range.to; number += 1) add(number);
        continue;
      }
      try {
        for (const entry of await this._rangeEntries(range, pageUrl)) add(entry.number);
      } catch (error) {
        // An open range that cannot be read adds nothing.
      }
    }
    numbers.sort(function (a, b) { return a - b; });
    if (numbers.length === 0) throw new Error("no episodes listed");
    return numbers.map(function (number) {
      return {
        id: [slug, audio, String(number)].join("|"),
        number: number,
        url: pageUrl,
        title: "Episode " + number,
      };
    });
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const audio = parts[1] === "dub" ? "dub" : "sub";
    const number = Number(parts[2]);
    if (!/^[\w-]+$/.test(slug || "") || !isFinite(number)) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const kind = wanted === "default" ? "" : this.servers.filter(function (s) { return s.toLowerCase() === wanted.toLowerCase(); })[0];
    if (kind === undefined) throw new Error("unknown server '" + wanted + "'");

    const pageUrl = this.base + "/" + slug + "/";
    const html = await this._page(pageUrl, this.base + "/");
    const listing = await this._listing(html);
    const entries = listing.entries.filter(function (entry) { return entry.number === number; });
    const failures = [];
    for (const range of listing.ranges) {
      if (number < range.from || (range.to && number > range.to)) continue;
      try {
        for (const entry of await this._rangeEntries(range, pageUrl)) if (entry.number === number) entries.push(entry);
      } catch (error) {
        failures.push(this._errorText(error));
      }
    }
    if (entries.length === 0 && failures.length > 0) throw new Error(failures.join("; "));
    if (entries.length === 0) throw new Error("episode " + number + " is not listed");

    // Known hosts first, in the order of the servers; a tab's name hints at its host.
    const order = this.servers;
    const rank = function (entry) {
      const index = order.indexOf(entry.kind);
      return index < 0 ? order.length : index;
    };
    entries.sort(function (a, b) { return rank(a) - rank(b); });

    // Hosts of players this extension has no reader for, named when nothing else plays.
    const unread = [];
    for (const entry of entries) {
      if (kind && entry.kind && entry.kind !== kind) continue;
      let embedUrl = "";
      try {
        embedUrl = await this._embedOf(entry, listing, pageUrl);
      } catch (error) {
        failures.push(this._errorText(error));
        continue;
      }
      const host = this._kindOf(embedUrl);
      if (!host && !kind) {
        const name = this._host(embedUrl);
        if (name !== "unknown host" && unread.indexOf(name) < 0) unread.push(name);
      }
      if (!host || (kind && host !== kind)) continue;
      try {
        const found = host === "Voe" ? await this._voe(embedUrl, pageUrl)
          : host === "Vidmoly" ? await this._vidmoly(embedUrl, pageUrl)
          : await this._mp4upload(embedUrl, pageUrl);
        return {
          server: host,
          headers: { Referer: found.referer },
          videoSources: [
            {
              url: found.url,
              type: this._isHls(found.url) ? "m3u8" : "mp4",
              quality: "auto",
              label: audio === "dub" ? "German dub" : "German hard sub",
              subtitles: [],
            },
          ],
        };
      } catch (error) {
        failures.push(host + ": " + this._errorText(error));
      }
    }
    if (unread.length > 0) failures.push("this extension can't read the video hosts " + unread.join(", "));
    if (failures.length > 0) throw new Error(failures.join("; "));
    throw new Error(kind ? "no " + kind + " player for this episode" : "no supported player for this episode");
  }

  // ---------------------------------------------------------------- the site's episode lists

  // The episodes of an entry's page as { entries: [{ number, kind, link?, server?, page? }], ranges,
  // title, nonce }. `link` is the `?link=` index of one host's episode on its page (`page`, else the
  // entry's page); `server` the player number of the site's `get_episode_data` request.
  async _listing(html) {
    const panes = this._panes(html);
    const entries = panes.entries;
    let match;

    const player = /<div\s+class="simple-iframe-player"\s+data-title="([^"]*)"/.exec(html);
    const config = /var\s+iframe_loader\s*=\s*(\{[^;]*\});/.exec(html);
    let title = "";
    let nonce = "";
    if (player && config) {
      title = this._unescapeBody(player[1]);
      try {
        nonce = String(JSON.parse(config[1]).nonce || "");
      } catch (error) {
        nonce = "";
      }
      const servers = [];
      const optionRe = /<option\s+value="(\d+)"/g;
      const select = /<select\s+class="server-select">([\s\S]*?)<\/select>/.exec(html);
      while (select && (match = optionRe.exec(select[1])) !== null) servers.push(match[1]);
      if (servers.length > 0 && nonce) {
        const listed = await this._episodeData({ title: title, server: servers[0] }, nonce);
        const episodes = listed && Array.isArray(listed.episodes) ? listed.episodes : [];
        for (const episode of episodes) {
          const number = Number(episode && episode.number);
          if (!isFinite(number) || number <= 0) continue;
          for (const server of servers) entries.push({ number: number, kind: "", server: server });
        }
      }
    }
    return { entries: entries, ranges: panes.ranges, title: title, nonce: nonce };
  }

  // The `?link=` episodes of a page's host tabs, and its range links ("S01:E01-61", "E1073-1116",
  // "S22:E1086-") as { from, to (0 when open), kind, link }; each range once, its first host's.
  _panes(html) {
    const entries = [];
    const ranges = [];
    const names = {};
    const tabRe = /href="#multi_link_tab(\d+)"[^>]*>([^<]*)</g;
    let match;
    while ((match = tabRe.exec(html)) !== null) names[match[1]] = this._plain(match[2]);

    const panes = html.split(/<div\s+id="multi_link_tab(?=\d+")/).slice(1);
    for (const pane of panes) {
      const tab = pane.slice(0, pane.indexOf('"'));
      const kind = this._kindOfName(names[tab] || "");
      const linkRe = /href="[^"]*\?link=(\d+)"[^>]*>([\s\S]*?)<\/a>/g;
      while ((match = linkRe.exec(pane)) !== null) {
        // "Ep. 12", "1155", "E1073"; specials are left out.
        const label = this._plain(match[2]);
        const numbered = /^(?:Ep\.?\s*|E)?(\d+)$/i.exec(label);
        const range = /^(?:S\d+\s*:\s*)?E(\d+)\s*-\s*(\d*)$/i.exec(label);
        if (numbered) {
          entries.push({ number: parseInt(numbered[1], 10), kind: kind, link: match[1] });
        } else if (range) {
          const from = parseInt(range[1], 10);
          const to = range[2] ? parseInt(range[2], 10) : 0;
          if (ranges.some(function (r) { return r.from === from && r.to === to; })) continue;
          ranges.push({ from: from, to: to, kind: kind, link: match[1] });
        }
      }
    }
    const order = this.servers;
    const rank = function (range) {
      const index = order.indexOf(range.kind);
      return index < 0 ? order.length : index;
    };
    ranges.sort(function (a, b) { return rank(a) - rank(b); });
    return { entries: entries, ranges: ranges };
  }

  // The episodes behind a range link: its player links to a page of the site that lists them,
  // counted from 1 ("Ep. 1" is the range's first episode) or by their own numbers.
  async _rangeEntries(range, pageUrl) {
    const target = await this._embedOf(range, null, pageUrl);
    if (this._host(target) !== this._host(this.base)) throw new Error("range " + range.from + "- has no episode page");
    const page = target.split(/[?#]/)[0];
    const panes = this._panes(await this._page(page, pageUrl));
    const lowest = Math.min.apply(null, panes.entries.map(function (entry) { return entry.number; }));
    const shift = lowest < range.from ? range.from - 1 : 0;
    return panes.entries.map(function (entry) {
      const number = entry.number + shift;
      return { number: number, kind: entry.kind, link: entry.link, page: page };
    });
  }

  // The `get_episode_data` answer: the episode list of a player, or with `episode` its address.
  async _episodeData(fields, nonce) {
    const body = ["action=get_episode_data", "title=" + encodeURIComponent(fields.title), "server=" + encodeURIComponent(fields.server)];
    if (fields.episode !== undefined) body.push("episode=" + encodeURIComponent(String(fields.episode)));
    body.push("nonce=" + encodeURIComponent(nonce));
    const text = await this._page(this.base + "/wp-admin/admin-ajax.php", { Referer: this.base + "/", "X-Requested-With": "XMLHttpRequest" }, {
      method: "POST",
      body: body.join("&"),
    });
    let answer = null;
    try {
      answer = JSON.parse(text);
    } catch (error) {
      throw new Error(text.trim() === "-1" || text.trim() === "0" ? "the site refused the episode request" : "the site's episode answer is unreadable");
    }
    if (!answer || answer.success !== true) throw new Error("the site has no data for this episode");
    return answer.data || {};
  }

  // The address of a host's player for one listed episode.
  async _embedOf(entry, listing, pageUrl) {
    if (entry.server !== undefined) {
      const data = await this._episodeData({ title: listing.title, server: entry.server, episode: entry.number }, listing.nonce);
      return typeof data.url === "string" ? this._absolute(data.url, pageUrl) : "";
    }
    const page = entry.page || pageUrl;
    const html = await this._page(page + "?link=" + entry.link, pageUrl);
    // The player is an <iframe>, or (Voe) a picture linking to it.
    const area = html.split(/class="multi_link-area"/)[0];
    const frame = /<iframe\b[^>]*\bsrc="(https?:\/\/[^"]+)"/i.exec(area);
    if (frame) return this._unescapeBody(frame[1]);
    const linked = /<a\s+href="(https?:\/\/[^"]+)"\s+target="_blank"\s*>\s*<img\b[^>]*\/player/i.exec(area);
    return linked ? this._unescapeBody(linked[1]) : "";
  }

  _kindOfName(name) {
    if (/voe/i.test(name)) return "Voe";
    if (/^vidm|vidmoly/i.test(name)) return "Vidmoly";
    if (/mp4/i.test(name)) return "Mp4Upload";
    return "";
  }

  _kindOf(url) {
    const host = this._host(url);
    if (/(^|\.)voe\.sx$/.test(host)) return "Voe";
    if (/vidmoly/.test(host)) return "Vidmoly";
    if (/mp4upload/.test(host)) return "Mp4Upload";
    return "";
  }

  // ---------------------------------------------------------------- video hosts

  // Voe: the first page sends the browser on to the player's current domain; the player's
  // setup is a JSON string (ROT13, junk markers, base64, shifted characters, reversed, base64).
  async _voe(url, referer) {
    let page = await this._page(url, referer, null, true);
    let playerUrl = url;
    const moved = /window\.location\.href\s*=\s*'(https?:\/\/[^']+)'/.exec(page);
    if (moved && !/application\/json/.test(page)) {
      playerUrl = moved[1];
      page = await this._page(playerUrl, referer, null, true);
    }
    const setup = this._voeSetup(page);
    const video = setup ? String(setup.source || setup.direct_access_url || "") : "";
    if (!/^https?:\/\//i.test(video)) throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Voe" : "the player names no video");
    return { url: video, referer: this._origin(playerUrl) + "/" };
  }

  _voeSetup(page) {
    const block = /<script\s+type="application\/json">\s*([\s\S]*?)\s*<\/script>/.exec(page);
    if (!block) return null;
    try {
      let text = JSON.parse(block[1]);
      if (Array.isArray(text)) text = text[0];
      text = String(text).replace(/[a-zA-Z]/g, function (c) {
        const base = c <= "Z" ? 65 : 97;
        return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);
      });
      for (const junk of ["@$", "^^", "~@", "%?", "*~", "!!", "#&"]) text = text.split(junk).join("");
      text = String(atob(text));
      let shifted = "";
      for (let i = 0; i < text.length; i += 1) shifted += String.fromCharCode(text.charCodeAt(i) - 3);
      return JSON.parse(String(atob(shifted.split("").reverse().join(""))));
    } catch (error) {
      return null;
    }
  }

  // Vidmoly: the page's player setup names the playlist (`sources: [{ file: '...' }]`).
  async _vidmoly(url, referer) {
    const page = await this._page(url, referer, null, true);
    const setup = /sources:\s*\[\s*\{\s*file:\s*["']([^"']+)["']/.exec(page);
    const video = setup ? this._unescapeBody(setup[1]) : this._mediaUrls(page).filter(this._isHls)[0];
    if (!video || !/^https?:\/\//i.test(video)) {
      throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Vidmoly" : "the player names no video");
    }
    return { url: video, referer: this._origin(url) + "/" };
  }

  // Mp4Upload: the player's setup names the MP4 (`src: "…/video.mp4"`), possibly in a packed script.
  async _mp4upload(url, referer) {
    const page = await this._page(url, referer, null, true);
    const text = page + "\n" + this._unpack(page);
    const setup = /\bsrc:\s*["'](https?:\/\/[^"']+\.mp4[^"']*)["']/.exec(text) || /"src":"(https?:[^"]+\.mp4[^"]*)"/.exec(text);
    const video = setup ? this._unescapeBody(setup[1]) : "";
    if (!video) throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Mp4Upload" : "the player names no video");
    return { url: video, referer: "https://www.mp4upload.com/" };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as text. `referer` is a URL, or an object of request headers. A video host's
  // "not found" page is returned (`lenient`) so its text can explain the failure.
  async _page(url, referer, init, lenient) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (lenient && response.status === 404) return text;
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (this._looksLikeChallenge(text) && !lenient) throw new Error("blocked by the site's bot protection");
    return text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  _absolute(raw, base) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    return this._origin(base || this.base) + (url.charAt(0) === "/" ? "" : "/") + url;
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /https?:\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      const url = match[0].replace(/[);,\]}]+$/, "");
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }
}

// AniWorld (aniworld.to): German dub, and German or English subtitles burnt into the video. One
// entry of the site holds every season of a show ("Staffel 1", "Staffel 2"…); this extension lists
// each season as its own search result ("… Season 2") so it matches the app's per-season titles.
// Every episode page lists its video hosts per language; a host's `/redirect/<id>` link leads to
// the player (VOE, Vidmoly, Filemoon; Doodstream is not read).

class Provider {
  constructor() {
    this.base = "https://aniworld.to";
    this.servers = ["VOE", "Vidmoly", "Filemoon"];
    // The site's language keys: 1 German dub, 3 German subtitles, 2 English subtitles.
    this.languages = { dub: [["1", "German dub"]], sub: [["3", "German hard sub"], ["2", "English hard sub"]] };
  }

  getSettings() {
    return {
      episodeServers: ["VOE", "Vidmoly", "Filemoon"],
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");
    const audio = opts && opts.dub ? "dub" : "sub";

    let found = [];
    for (const query of queries) {
      const text = await this._page(this.base + "/ajax/seriesSearch?keyword=" + encodeURIComponent(query), this.base + "/");
      let list = [];
      try {
        list = JSON.parse(text);
      } catch (error) {
        throw new Error("the site's search answer is unreadable");
      }
      found = (Array.isArray(list) ? list : []).filter(function (item) { return item && /^[\w-]+$/.test(String(item.link || "")); });
      if (found.length > 0) break;
    }

    const results = [];
    // Each show's page names its seasons; the first few shows are enough for a good match.
    for (const item of found.slice(0, 3)) {
      const slug = String(item.link);
      const name = this._plain(item.name) || slug;
      let page = "";
      try {
        page = await this._page(this.base + "/anime/stream/" + slug, this.base + "/");
      } catch (error) {
        continue;
      }
      const alt = /data-alternativeTitles="([^"]*)"/i.exec(page);
      const altTitles = alt ? this._plain(alt[1]).split(/\s*,\s*/).filter(function (t) { return t; }) : [];
      const year = /itemprop="startDate"><a[^>]*>(\d{4})</.exec(page);
      const seasons = [];
      const seasonRe = new RegExp('href="/anime/stream/' + slug + '/staffel-(\\d+)"', "g");
      let match;
      while ((match = seasonRe.exec(page)) !== null) {
        const n = parseInt(match[1], 10);
        if (n > 0 && seasons.indexOf(n) < 0) seasons.push(n);
      }
      if (seasons.length === 0) seasons.push(1);
      // Long shows (One Piece) are one title in the app but many seasons here, each counted from 1:
      // then the plain title lists every season numbered on ("season" 0). The show page lists season 1.
      const wanted = Number(opts && opts.media && opts.media.episodeCount) || 0;
      const firstSeason = (page.match(/itemprop="episodeNumber"/g) || []).length;
      const allSeasons = seasons.length > 1 && (wanted > firstSeason || (!wanted && seasons.length >= 3));
      for (const season of seasons) {
        const suffix = season === 1 ? "" : " Season " + season;
        const result = {
          id: [slug, season === 1 && allSeasons ? 0 : season, audio].join("|"),
          title: name + suffix,
          url: this.base + "/anime/stream/" + slug + "/staffel-" + season,
          subOrDub: audio,
          altTitles: altTitles.map(function (t) { return t + suffix; }),
        };
        if (season === 1 && year) result.year = parseInt(year[1], 10);
        results.push(result);
      }
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = this._idParts(id, 3);
    const show = this.base + "/anime/stream/" + parts.slug;
    let seasons = [parts.season];
    if (parts.season === 0) {
      const page = await this._page(show, this.base + "/");
      seasons = [];
      const seasonRe = new RegExp('href="/anime/stream/' + parts.slug + '/staffel-(\\d+)"', "g");
      let match;
      while ((match = seasonRe.exec(page)) !== null) {
        const n = parseInt(match[1], 10);
        if (n > 0 && seasons.indexOf(n) < 0) seasons.push(n);
      }
      seasons.sort(function (a, b) { return a - b; });
    }
    // Season pages, a few at a time (One Piece has over 20).
    const pages = [];
    for (let i = 0; i < seasons.length; i += 4) {
      const batch = seasons.slice(i, i + 4);
      const read = await Promise.all(batch.map((season) => this._page(show + "/staffel-" + season, show)));
      for (let j = 0; j < batch.length; j += 1) pages.push({ season: batch[j], html: read[j] });
    }

    const episodes = [];
    let offset = 0;
    for (const page of pages) {
      const rows = this._rows(page.html, parts.audio);
      for (const row of rows.listed) {
        const number = offset + row.number;
        if (episodes.some(function (e) { return e.number === number; })) continue;
        episodes.push({
          id: [parts.slug, page.season, parts.audio, row.number].join("|"),
          number: number,
          url: show + "/staffel-" + page.season + "/episode-" + row.number,
          title: row.title || "Episode " + number,
        });
      }
      offset += rows.last;
    }
    if (episodes.length === 0) {
      throw new Error(parts.audio === "dub" ? "no German dub listed for this season" : "no subtitled episodes listed for this season");
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    return episodes;
  }

  // A season page's episodes in the wanted language ({ number, title }), and its last episode number.
  _rows(html, audio) {
    // One table row per episode; its flags say which languages the episode has.
    const flag = audio === "dub" ? /\/german\.svg/ : /\/japanese-(?:german|english)\.svg/;
    const listed = [];
    let last = 0;
    for (const row of html.split(/<tr\b[^>]*itemprop="episode"/).slice(1)) {
      const body = row.split("</tr>")[0];
      const number = /itemprop="episodeNumber"\s+content="(\d+)"/.exec(body);
      const n = number ? parseInt(number[1], 10) : 0;
      if (!(n > 0)) continue;
      last = Math.max(last, n);
      if (!flag.test(body)) continue;
      const german = /<strong>([\s\S]*?)<\/strong>/.exec(body);
      const english = /<span>([\s\S]*?)<\/span>/.exec(body);
      listed.push({ number: n, title: this._plain(this._plain(german ? german[1] : english ? english[1] : "")) });
    }
    return { listed: listed, last: last };
  }

  async findEpisodeServer(episode, server) {
    const parts = this._idParts(episode && episode.id, 4);
    const number = Number(parts.rest[0]);
    if (!(number > 0)) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const kind = wanted === "default" ? "" : this.servers.filter(function (s) { return s.toLowerCase() === wanted.toLowerCase(); })[0];
    if (kind === undefined) throw new Error("unknown server '" + wanted + "'");

    const pageUrl = this.base + "/anime/stream/" + parts.slug + "/staffel-" + parts.season + "/episode-" + number;
    const html = await this._page(pageUrl, this.base + "/anime/stream/" + parts.slug + "/staffel-" + parts.season);
    // <li … data-lang-key="1" data-link-id="…" data-link-target="/redirect/…"> … <h4>VOE</h4>
    const links = [];
    const itemRe = /<li\b[^>]*data-lang-key="(\d)"[^>]*data-link-target="(\/redirect\/\d+)"[^>]*>([\s\S]*?)<\/li>/g;
    let match;
    while ((match = itemRe.exec(html)) !== null) {
      const name = /<h4>([^<]*)<\/h4>/.exec(match[3]);
      links.push({ lang: match[1], target: match[2], host: this._serverOf(name ? name[1] : "") });
    }
    if (links.length === 0) throw new Error("episode " + number + " lists no players");

    const order = this.servers;
    const failures = [];
    const unread = [];
    for (const language of this.languages[parts.audio === "dub" ? "dub" : "sub"]) {
      const candidates = links.filter(function (link) { return link.lang === language[0]; });
      candidates.sort(function (a, b) {
        const rank = function (link) { const i = order.indexOf(link.host); return i < 0 ? order.length : i; };
        return rank(a) - rank(b);
      });
      for (const link of candidates) {
        if (!link.host) {
          continue;
        }
        if (kind && link.host !== kind) continue;
        try {
          const player = await this._get(this.base + link.target, pageUrl);
          const host = this._serverOfUrl(player.url);
          if (!host) {
            const name = this._host(player.url);
            if (unread.indexOf(name) < 0) unread.push(name);
            continue;
          }
          const found = host === "VOE" ? await this._voe(player.url, player.text)
            : host === "Vidmoly" ? await this._vidmoly(player.url, player.text)
            : await this._byse(player.url);
          return {
            server: host,
            headers: found.headers,
            videoSources: [
              {
                url: found.url,
                type: found.type,
                quality: "auto",
                label: language[1],
                subtitles: [],
              },
            ],
          };
        } catch (error) {
          failures.push(link.host + ": " + this._errorText(error));
        }
      }
    }
    if (unread.length > 0) failures.push("this extension can't read the video hosts " + unread.join(", "));
    if (failures.length > 0) throw new Error(failures.join("; "));
    const hosts = links.map(function (l) { return l.host; }).filter(function (h) { return h; });
    if (hosts.length === 0) throw new Error("this episode is only on video hosts the extension can't read (such as Doodstream)");
    throw new Error(kind ? "no " + kind + " player for this episode in this language" : "no player for this episode in this language");
  }

  // ---------------------------------------------------------------- ids and hosts

  _idParts(id, count) {
    const parts = String(id || "").split("|");
    const slug = parts[0];
    const season = parseInt(parts[1], 10);
    // Season 0: every season numbered on (long shows); episode ids always name a real season.
    if (parts.length < count || !/^[\w-]+$/.test(slug || "") || !(season >= 0) || (count > 3 && season === 0)) throw new Error("invalid id '" + id + "'");
    return { slug: slug, season: season, audio: parts[2] === "dub" ? "dub" : "sub", rest: parts.slice(3) };
  }

  _serverOf(name) {
    if (/^\s*voe\s*$/i.test(name)) return "VOE";
    if (/vidmoly/i.test(name)) return "Vidmoly";
    if (/filemoon/i.test(name)) return "Filemoon";
    return "";
  }

  _serverOfUrl(url) {
    const host = this._host(url);
    if (/(^|\.)voe\.sx$/.test(host) || /voe/.test(host)) return "VOE";
    if (/vidmoly/.test(host)) return "Vidmoly";
    if (/^filemoon\.|^byse[a-z]*\./.test(host)) return "Filemoon";
    return "";
  }

  // ---------------------------------------------------------------- video hosts

  // VOE: the first page may send the browser on to the player's current domain; the player's
  // setup is a JSON string (ROT13, junk markers, base64, shifted characters, reversed, base64).
  async _voe(url, page) {
    let playerUrl = url;
    const moved = /window\.location\.href\s*=\s*'(https?:\/\/[^']+)'/.exec(page);
    if (moved && !/application\/json/.test(page)) {
      playerUrl = moved[1];
      page = (await this._get(playerUrl, this.base + "/")).text;
    }
    const setup = this._voeSetup(page);
    const video = setup ? String(setup.source || setup.direct_access_url || "") : "";
    if (!/^https?:\/\//i.test(video)) throw new Error(this._gone(page) ? "the video was removed from VOE" : "the player names no video");
    const origin = this._origin(playerUrl);
    return { url: video, type: this._isHls(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  _voeSetup(page) {
    const block = /<script\s+type="application\/json">\s*([\s\S]*?)\s*<\/script>/.exec(page);
    if (!block) return null;
    try {
      let text = JSON.parse(block[1]);
      if (Array.isArray(text)) text = text[0];
      text = String(text).replace(/[a-zA-Z]/g, function (c) {
        const base = c <= "Z" ? 65 : 97;
        return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);
      });
      for (const junk of ["@$", "^^", "~@", "%?", "*~", "!!", "#&"]) text = text.split(junk).join("");
      text = String(atob(text));
      let shifted = "";
      for (let i = 0; i < text.length; i += 1) shifted += String.fromCharCode(text.charCodeAt(i) - 3);
      return JSON.parse(String(atob(shifted.split("").reverse().join(""))));
    } catch (error) {
      return null;
    }
  }

  // Vidmoly: the page's player setup names the playlist (`sources: [{ file: '...' }]`).
  async _vidmoly(url, page) {
    const setup = /sources:\s*\[\s*\{\s*file:\s*["']([^"']+)["']/.exec(page);
    const video = setup ? this._unescapeBody(setup[1]) : this._mediaUrls(page).filter(this._isHls)[0];
    if (!video || !/^https?:\/\//i.test(video)) throw new Error(this._gone(page) ? "the video was removed from Vidmoly" : "the player names no video");
    const origin = this._origin(url);
    return { url: video, type: this._isHls(video) ? "m3u8" : "mp4", headers: { Referer: origin + "/" } };
  }

  // Filemoon's "Byse" player: /api/videos/<code> answers the sources AES-256-GCM encrypted, the
  // key split among `key_parts`.
  async _byse(url) {
    const code = /\/(?:e|d)\/(\w+)/.exec(url);
    if (!code) throw new Error("Filemoon address has no video code");
    const origin = this._origin(url);
    const page = await this._get(origin + "/api/videos/" + code[1], url);
    let info = null;
    try {
      info = JSON.parse(page.text);
    } catch (error) {
      info = null;
    }
    const playback = info && info.playback;
    if (!playback || typeof playback.payload !== "string") throw new Error(this._gone(page.text) ? "the video was removed from Filemoon" : "the Filemoon answer has changed");
    let opened = null;
    try {
      opened = JSON.parse(this._byseOpen(playback));
    } catch (error) {
      opened = null;
    }
    const sources = (opened && Array.isArray(opened.sources) ? opened.sources : []).filter(function (s) { return s && /^https?:\/\//.test(String(s.url)); });
    if (sources.length === 0) throw new Error("Filemoon names no video");
    const video = sources[0];
    const hls = this._isHls(video.url) || /mpegurl/i.test(String(video.mime_type));
    return { url: video.url, type: hls ? "m3u8" : "mp4", headers: { Referer: origin + "/", Origin: origin } };
  }

  // The player's rule: version n (1-20) takes parts n and 31-n as the key, otherwise all of them.
  // GCM decryption is AES-CTR from counter 2; shortcut: the tag is not checked (a wrong key fails at JSON.parse).
  _byseOpen(playback) {
    const bytes = function (text) {
      const plain = String(text).replace(/-/g, "+").replace(/_/g, "/").replace(/=+$/, "");
      const binary = atob(plain + "===".slice((plain.length + 3) % 4));
      return Uint8Array.from(binary, function (c) { return c.charCodeAt(0); });
    };
    const parts = Array.isArray(playback.key_parts) ? playback.key_parts : [];
    const n = Number(playback.version);
    const picked = n >= 1 && n <= 20 && 31 - n <= parts.length ? [parts[n - 1], parts[30 - n]] : parts;
    const pieces = picked.filter(function (p) { return typeof p === "string" && p; }).map(bytes);
    const key = new Uint8Array(pieces.reduce(function (sum, p) { return sum + p.length; }, 0));
    pieces.reduce(function (at, p) { key.set(p, at); return at + p.length; }, 0);
    const iv = bytes(playback.iv);
    const data = bytes(playback.payload);
    if (key.length !== 32 || iv.length !== 12 || data.length <= 16) throw new Error("the Filemoon key has changed");
    const body = data.subarray(0, data.length - 16);
    const counters = new Uint8Array(Math.ceil(body.length / 16) * 16);
    for (let i = 0; i * 16 < counters.length; i += 1) {
      counters.set(iv, i * 16);
      const count = i + 2;
      counters.set([(count >>> 24) & 255, (count >>> 16) & 255, (count >>> 8) & 255, count & 255], i * 16 + 12);
    }
    const stream = bytes(CryptoJS.AES.encrypt(counters, key, { mode: CryptoJS.mode.ECB, padding: CryptoJS.pad.NoPadding }).toString(CryptoJS.enc.Base64));
    let text = "";
    for (let i = 0; i < body.length; i += 1) text += String.fromCharCode(body[i] ^ stream[i]);
    return CryptoJS.enc.Utf8.stringify(CryptoJS.enc.Latin1.parse(text));
  }

  _gone(body) {
    return /File is no longer available|File was deleted|can't find the video you are looking for|file you were looking for (?:could not be found|was deleted)|Video not found|has been removed|404 - Not found/i.test(body);
  }

  // ---------------------------------------------------------------- shared helpers

  // Titles to search for: the query, the romaji and English titles, each without punctuation (the
  // site's search finds "Frieren Beyond Journeys End" but not "Frieren: Beyond Journey's End"), and
  // without season words, since one entry holds every season ("Sousou no Frieren 2nd Season").
  _queries(opts) {
    const media = (opts && opts.media) || {};
    const titles = [opts && opts.query, media.romajiTitle, media.englishTitle].filter(function (t) { return typeof t === "string" && t.trim(); });
    const queries = [];
    const add = function (text) {
      const clean = String(text).replace(/\s+/g, " ").trim();
      if (clean && queries.indexOf(clean) < 0) queries.push(clean);
    };
    const bare = function (title) {
      return title.replace(/[^\p{L}\p{N}\s]+/gu, " ");
    };
    const seasonless = function (title) {
      return bare(title).replace(/\b\d+(?:st|nd|rd|th)\s+season\b|\bseason\s*\d+\b|\b(?:part|cour)\s*\d+\b|\s(?:[2-9]|II|III|IV)\s*$/gi, " ");
    };
    for (const title of titles) {
      add(title);
      add(bare(title));
    }
    for (const title of titles) add(seasonless(title));
    return queries.slice(0, 6);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page and the address it ended at (after redirects). `referer` is a URL.
  async _get(url, referer) {
    const host = this._host(url);
    const headers = {};
    if (referer) headers.Referer = referer;
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 403 && host === this._host(this.base)) throw new Error("AniWorld refuses connections from this network or region (HTTP 403)");
      if (response.status === 404) throw new Error(this._gone(text) ? "the video was removed" : "not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
    return { text: text, url: typeof response.url === "string" && response.url ? response.url : url };
  }

  async _page(url, referer) {
    return (await this._get(url, referer)).text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /https?:\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      const url = match[0].replace(/[);,\]}]+$/, "");
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }
}

// Neko Sama (neko-sama.fr): French dub (VF) from the players its pages embed (Vidmoly, Voe,
// VidHide), as HLS. One page of the site holds every season of a series, numbered on from the
// previous season; each season is offered as its own result here, numbered from 1.

class Provider {
  constructor() {
    this.base = "https://neko-sama.fr";
    this.servers = ["Vidmoly", "Voe", "VidHide"];
  }

  getSettings() {
    return {
      episodeServers: ["Vidmoly", "Voe", "VidHide"],
      // The site has only the French dub, so that is all it offers, as the dub.
      supportsDub: true,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    if (!opts || !opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    // The site's search reads one list of every series: [{ name, slug, img, year }].
    const index = await this._api(this.base + "/fr/data/search.json", { headers: { Referer: this.base + "/" } });
    if (!Array.isArray(index)) throw new Error("the site's series list is unreadable");

    const scored = [];
    for (const entry of index) {
      if (!entry || typeof entry.slug !== "string" || !/^[\w-]+$/.test(entry.slug)) continue;
      let best = 0;
      for (const query of queries) best = Math.max(best, this._score(query, String(entry.name || "")), this._score(query, entry.slug.replace(/-/g, " ")));
      if (best >= 0.5) scored.push({ entry: entry, score: best });
    }
    scored.sort(function (a, b) { return b.score - a.score; });

    // The series pages are read in parallel; one that fails is left out.
    const self = this;
    const hits = scored.slice(0, 4);
    const looked = await Promise.all(hits.map(function (item) {
      return self._seasons(item.entry.slug).then(null, function () { return []; });
    }));
    const results = [];
    for (let h = 0; h < hits.length; h += 1) {
      const entry = hits[h].entry;
      const name = this._text(entry.name) || entry.slug;
      const seasons = looked[h];
      const year = /^(19|20)\d{2}$/.test(String(entry.year)) ? parseInt(entry.year, 10) : undefined;
      if (seasons.length === 0) continue;
      for (let i = 0; i < seasons.length; i += 1) {
        const shown = this._text(seasons[i].name);
        const numbered = /^Saison\s*(\d+)$/i.exec(shown);
        let title = name;
        if (numbered) {
          if (parseInt(numbered[1], 10) > 1) title = name + " Season " + numbered[1];
        } else if (i > 0 || (shown && shown.toLowerCase() !== name.toLowerCase())) {
          title = shown.toLowerCase().indexOf(name.toLowerCase()) === 0 ? shown : name + " " + shown;
          title = title.replace(/\bSaison\s*(\d+)/i, "Season $1");
        }
        results.push({
          id: entry.slug + "|" + i,
          title: title,
          url: this.base + "/anime/" + entry.slug,
          subOrDub: "dub",
          altTitles: shown && shown !== title ? [shown] : [],
          year: i === 0 ? year : undefined,
          episodeCount: seasons[i].episods.length,
        });
      }
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const slug = parts[0];
    const season = parseInt(parts[1], 10);
    if (!/^[\w-]+$/.test(slug || "") || !(season >= 0)) throw new Error("invalid anime id '" + id + "'");

    const seasons = await this._seasons(slug);
    const chosen = seasons[season];
    if (!chosen) throw new Error("the series has no season " + (season + 1));
    const base = this.base;
    const episodes = [];
    chosen.episods.forEach(function (episode, position) {
      if (!episode || !Array.isArray(episode.players) || episode.players.length === 0) return;
      const number = position + 1;
      const name = typeof episode.name === "string" ? episode.name.replace(/\s+/g, " ").trim() : "";
      episodes.push({
        id: [slug, String(season), String(episode.num)].join("|"),
        number: number,
        url: base + "/anime/" + slug,
        title: name ? "Episode " + number + ": " + name : "Episode " + number,
      });
    });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    const slug = parts[0];
    const season = parseInt(parts[1], 10);
    const num = parts[2];
    if (!/^[\w-]+$/.test(slug || "") || !(season >= 0) || !num) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default");
    const kind = wanted === "default" ? "" : this.servers.filter(function (s) { return s.toLowerCase() === wanted.toLowerCase(); })[0];
    if (kind === undefined) throw new Error("unknown server '" + wanted + "'");

    const seasons = await this._seasons(slug);
    const listed = ((seasons[season] && seasons[season].episods) || []).filter(function (e) { return e && String(e.num) === num; })[0];
    if (!listed) throw new Error("the episode is no longer listed");
    const pageUrl = this.base + "/anime/" + slug;

    const order = this.servers;
    const self = this;
    const players = listed.players
      .map(function (player) { return player && typeof player.src === "string" ? self._absolute(player.src) : ""; })
      .filter(function (url) { return /^https?:\/\//i.test(url); })
      .map(function (url) { return { url: url, kind: self._kindOf(url) }; })
      .filter(function (player) { return player.kind && (!kind || player.kind === kind); });
    players.sort(function (a, b) { return order.indexOf(a.kind) - order.indexOf(b.kind); });
    if (players.length === 0) throw new Error(kind ? "no " + kind + " player for this episode" : "no supported player for this episode");

    const failures = [];
    for (const player of players) {
      try {
        const found = player.kind === "Voe" ? await this._voe(player.url, pageUrl)
          : player.kind === "Vidmoly" ? await this._vidmoly(player.url, pageUrl)
          : await this._vidhide(player.url, pageUrl);
        return {
          server: player.kind,
          headers: { Referer: found.referer },
          videoSources: [
            {
              url: found.url,
              type: this._isHls(found.url) ? "m3u8" : "mp4",
              quality: "auto",
              label: "French dub (VF)",
              subtitles: [],
            },
          ],
        };
      } catch (error) {
        failures.push(player.kind + ": " + this._errorText(error));
      }
    }
    throw new Error(failures.join("; "));
  }

  // ---------------------------------------------------------------- the site's pages

  // A series' seasons, as the page carries them: [{ name, episods: [{ num, name, players: [{ src }] }] }].
  async _seasons(slug) {
    const html = await this._page(this.base + "/anime/" + slug, this.base + "/");
    const block = /<script\b[^>]*\bid="js-seasons-data"[^>]*>([\s\S]*?)<\/script>/.exec(html);
    if (!block) throw new Error("the series page lists no episodes");
    let seasons = null;
    try {
      seasons = JSON.parse(block[1]);
    } catch (error) {
      throw new Error("the series page's episode list is unreadable");
    }
    return (Array.isArray(seasons) ? seasons : []).filter(function (s) { return s && Array.isArray(s.episods) && s.episods.length > 0; });
  }

  // Embed addresses: Voe `/e/<12 letters>` on changing domains, Vidmoly and its copies
  // `/embed-<id>.html`, VidHide `/embed/<id>` on changing domains.
  _kindOf(url) {
    const host = this._host(url);
    if (/(^|\.)voe\.sx$/.test(host) || /^https?:\/\/[^\/]+\/e\/[a-z0-9]{12}(?:[?#]|$)/.test(url)) return "Voe";
    if (/vidmoly|ansembed/.test(host)) return "Vidmoly";
    if (/smoothpre|dingtezuni|vidhide|callistanise/.test(host) || /^https?:\/\/[^\/]+\/embed\/[a-z0-9]{12}(?:[?#]|$)/.test(url)) return "VidHide";
    return "";
  }

  // Share of the query's words found in the name.
  _score(query, name) {
    const words = function (text) {
      const plain = String(text).toLowerCase();
      const folded = typeof plain.normalize === "function" ? plain.normalize("NFD").replace(/[\u0300-\u036f]/g, "") : plain;
      return folded.replace(/[\u2019']/g, "").split(/[^a-z0-9]+/).filter(Boolean);
    };
    const wanted = words(query);
    const have = words(name);
    if (wanted.length === 0 || have.length === 0) return 0;
    let hits = 0;
    for (const word of wanted) if (have.indexOf(word) >= 0) hits += 1;
    let back = 0;
    for (const word of have) if (wanted.indexOf(word) >= 0) back += 1;
    return Math.min(hits / wanted.length, (back / have.length + 1) / 2);
  }

  // ---------------------------------------------------------------- video hosts

  // Voe: the first page sends the browser on to the player's current domain; the player's
  // setup is a JSON string (ROT13, junk markers, base64, shifted characters, reversed, base64).
  async _voe(url, referer) {
    let page = await this._page(url, referer, null, true);
    let playerUrl = url;
    const moved = /window\.location\.href\s*=\s*'(https?:\/\/[^']+)'/.exec(page);
    if (moved && !/application\/json/.test(page)) {
      playerUrl = moved[1];
      page = await this._page(playerUrl, referer, null, true);
    }
    const setup = this._voeSetup(page);
    const video = setup ? String(setup.source || setup.direct_access_url || "") : "";
    if (!/^https?:\/\//i.test(video)) throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Voe" : "the player names no video");
    return { url: video, referer: this._origin(playerUrl) + "/" };
  }

  _voeSetup(page) {
    const block = /<script\s+type="application\/json">\s*([\s\S]*?)\s*<\/script>/.exec(page);
    if (!block) return null;
    try {
      let text = JSON.parse(block[1]);
      if (Array.isArray(text)) text = text[0];
      text = String(text).replace(/[a-zA-Z]/g, function (c) {
        const base = c <= "Z" ? 65 : 97;
        return String.fromCharCode(((c.charCodeAt(0) - base + 13) % 26) + base);
      });
      for (const junk of ["@$", "^^", "~@", "%?", "*~", "!!", "#&"]) text = text.split(junk).join("");
      text = String(atob(text));
      let shifted = "";
      for (let i = 0; i < text.length; i += 1) shifted += String.fromCharCode(text.charCodeAt(i) - 3);
      return JSON.parse(String(atob(shifted.split("").reverse().join(""))));
    } catch (error) {
      return null;
    }
  }

  // Vidmoly: the page's player setup names the playlist (`sources: [{ file: '...' }]`).
  async _vidmoly(url, referer) {
    const page = await this._page(url, referer, null, true);
    const setup = /sources:\s*\[\s*\{\s*file:\s*["']([^"']+)["']/.exec(page);
    const video = setup ? this._unescapeBody(setup[1]) : this._mediaUrls(page).filter(this._isHls)[0];
    if (!video || !/^https?:\/\//i.test(video)) {
      throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from Vidmoly" : "the player names no video");
    }
    return { url: video, referer: this._origin(url) + "/" };
  }

  // VidHide: a packed script holds `var links={"hls2":"https://…","hls4":"/stream/…"}`.
  async _vidhide(url, referer) {
    const page = await this._page(url, referer, null, true);
    const text = this._unpack(page);
    const links = /\blinks\s*=\s*(\{[^}]*\})/.exec(text);
    let listed = null;
    try {
      listed = links ? JSON.parse(links[1]) : null;
    } catch (error) {
      listed = null;
    }
    const origin = this._origin(url);
    let video = "";
    for (const name of ["hls2", "hls4", "hls3"]) {
      const value = listed && typeof listed[name] === "string" ? listed[name] : "";
      if (!value || !/\.m3u8/i.test(value)) continue;
      video = /^https?:\/\//i.test(value) ? value : origin + (value.charAt(0) === "/" ? "" : "/") + value;
      break;
    }
    if (!video) throw new Error(/deleted|not found|removed/i.test(page) ? "the video was removed from VidHide" : "the player names no video");
    return { url: video, referer: origin + "/" };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.englishTitle, media.romajiTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 3);
  }

  // A JSON answer. `init` may carry extra `headers`.
  async _api(url, init) {
    const text = await this._page(url, Object.assign({ Accept: "application/json" }, (init && init.headers) || {}));
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") throw new Error(this._host(url) + " answered with a page instead of data");
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(this._host(url) + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _isHls(url) {
    return String(url).split(/[?#]/)[0].toLowerCase().indexOf(".m3u8") >= 0;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page as text. `referer` is a URL, or an object of request headers. A video host's
  // "not found" page is returned (`lenient`) so its text can explain the failure.
  async _page(url, referer, init, lenient) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    let response;
    try {
      response = await fetch(url, { headers: headers });
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (lenient && response.status === 404) return text;
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    if (this._looksLikeChallenge(text) && !lenient) throw new Error("blocked by the site's bot protection");
    return text;
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // Embed addresses come with any letter case in the host ("Smoothpre.com").
  _absolute(raw) {
    let url = String(raw).trim();
    if (url.indexOf("//") === 0) url = "https:" + url;
    const match = /^(https?:\/\/)([^\/?#]+)(.*)$/i.exec(url);
    return match ? match[1].toLowerCase() + match[2].toLowerCase() + match[3] : "";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  // Every distinct `.m3u8` / `.mp4` URL in the body, in order of appearance.
  _mediaUrls(body) {
    const text = this._unescapeBody(body);
    const re = /https?:\/\/[^\s"'<>\\]+?\.(?:m3u8|mp4)[^\s"'<>\\]*/gi;
    const urls = [];
    let match;
    while ((match = re.exec(text)) !== null) {
      const url = match[0].replace(/[);,\]}]+$/, "");
      if (urls.indexOf(url) < 0) urls.push(url);
    }
    return urls;
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }
}

// WitAnime (witanime.site): Arabic subtitles (burnt in) as HLS from HGCloud (a StreamWish
// player) and MP4 from mp4upload, Videa, Soraplay and Yonaplay. The site lists every episode on the show's page and hands out
// each player through a short-lived token of the visitor's session.

// Each call gets a new Provider, so what the calls share lives here: the episode listing and the
// queue of token releases.
const witanimeShared = { listings: {}, releases: Promise.resolve() };

class Provider {
  constructor() {
    this.base = "https://witanime.site";
    // Pages of the site whose player HGCloud's loader page sends the visitor to.
    this.wishMirrors = ["vibuxer.com", "embedwish.com", "swdyu.com", "hgplaycdn.com", "hanerix.com", "audinifer.com"];
  }

  getSettings() {
    return {
      episodeServers: ["HGCloud", "mp4upload", "Videa", "Soraplay", "Yonaplay"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // The site's players carry the original audio with Arabic subtitles.
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const results = [];
    for (const query of queries) {
      const answer = await this._request(this.base + "/search/suggest?q=" + encodeURIComponent(query), {
        headers: this._fetchHeaders({ Accept: "application/json" }),
      });
      const found = this._json(answer);
      for (const item of found && Array.isArray(found.results) ? found.results : []) {
        const match = /^https:\/\/[^\/]+\/(anime|movie)\/([\w.-]+)\/?$/.exec(String((item && item.url) || ""));
        const title = this._text(item && item.title);
        if (!match || !title) continue;
        const id = match[1] + "|" + match[2];
        if (results.some(function (r) { return r.id === id; })) continue;
        results.push({
          id: id,
          title: title,
          url: this.base + "/" + match[1] + "/" + match[2],
          subOrDub: "sub",
          altTitles: this._distinct([this._text(item.alternative_title)]),
          format: match[1] === "movie" ? "MOVIE" : undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const parts = String(id).split("|");
    const kind = parts[0];
    const slug = parts[1];
    if ((kind !== "anime" && kind !== "movie") || !/^[\w.-]+$/.test(slug || "")) throw new Error("invalid anime id '" + id + "'");

    if (kind === "movie") {
      return [{ id: "movie|" + slug, number: 1, url: this.base + "/watch/movie/" + slug, title: "Movie" }];
    }

    const html = this._body(await this._request(this.base + "/anime/" + slug, { headers: { Referer: this.base + "/" } }));
    // One entry: <a href="https://witanime.site/watch/slug/12" …>; recaps are numbered "12.5".
    const escaped = slug.replace(/[.]/g, "\\.");
    const re = new RegExp('href="https://[^"/]+/watch/' + escaped + '/(\\d+(?:\\.\\d+)?)"', "g");
    const episodes = [];
    const seen = {};
    let match;
    while ((match = re.exec(html)) !== null) {
      if (seen[match[1]]) continue;
      seen[match[1]] = true;
      episodes.push({
        id: slug + "|" + match[1],
        number: Number(match[1]),
        url: this.base + "/watch/" + slug + "/" + match[1],
        title: "Episode " + match[1],
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    if (!/^[\w.-]+$/.test(parts[0] || "") || !/^[\w.-]+$/.test(parts[1] || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const watchUrl = parts[0] === "movie" ? this.base + "/watch/movie/" + parts[1] : this.base + "/watch/" + parts[0] + "/" + parts[1];
    const wanted = String(server || "default").toLowerCase();
    const names = this.getSettings().episodeServers;
    if (wanted !== "default" && !names.some(function (name) { return name.toLowerCase() === wanted; })) throw new Error("unknown server '" + server + "'");

    const listing = await this._listing(watchUrl);
    const session = listing.session;
    const players = listing.players;
    if (players.length === 0) throw new Error("the site has no player for this episode");

    const order = wanted === "default" ? ["hgcloud", "mp4upload", "videa", "soraplay", "yonaplay"] : [wanted];
    const chosen = [];
    for (const host of order) {
      for (const player of players) if (player.host === host) chosen.push(player);
    }
    if (chosen.length === 0) {
      const offered = this._distinct(players.map(function (p) { return p.host; }));
      throw new Error(wanted === "default"
        ? "no supported player for this episode (offered: " + offered.join(", ") + ")"
        : "no " + server + " player for this episode");
    }

    let reason = null;
    for (const host of order) {
      const videoSources = [];
      let headers = {};
      for (const player of chosen.filter(function (p) { return p.host === host; }).slice(0, 3)) {
        try {
          const embedUrl = await this._embedUrl(player.token, session);
          const found = host === "mp4upload" ? [await this._mp4upload(embedUrl)]
            : host === "videa" ? await this._videa(embedUrl)
            : host === "soraplay" ? await this._soraplay(embedUrl)
            : host === "yonaplay" ? [await this._yonaplay(embedUrl)]
            : [await this._streamWish(embedUrl)];
          for (const file of found) {
            if (videoSources.some(function (v) { return v.url === file.url || v.quality === (file.quality || player.quality); })) continue;
            headers = file.headers;
            videoSources.push({
              url: file.url,
              type: file.type,
              quality: file.quality || { "4K": "2160p", FHD: "1080p", HD: "720p", SD: "480p" }[player.quality] || "auto",
              label: "Arabic hard sub",
              subtitles: [],
            });
          }
          if (videoSources.length >= 2) break;
        } catch (error) {
          reason = reason || this._errorText(error);
        }
      }
      if (videoSources.length > 0) {
        const name = { hgcloud: "HGCloud", mp4upload: "mp4upload", videa: "Videa", soraplay: "Soraplay", yonaplay: "Yonaplay" }[host];
        return { server: name, headers: headers, videoSources: videoSources };
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- site session

  // The players are listed for the session the episode page opened. The app asks every server at
  // once and the site rate-limits bursts, so one listing serves an episode's calls for half a minute.
  _listing(watchUrl) {
    const cached = witanimeShared.listings[watchUrl];
    if (cached && Date.now() - cached.at < 30000) return cached.promise;
    const promise = this._loadListing(watchUrl);
    witanimeShared.listings = {};
    witanimeShared.listings[watchUrl] = { at: Date.now(), promise: promise };
    promise.catch(function () {
      const entry = witanimeShared.listings[watchUrl];
      if (entry && entry.promise === promise) delete witanimeShared.listings[watchUrl];
    });
    return promise;
  }

  async _loadListing(watchUrl) {
    const page = await this._request(watchUrl, { headers: { Referer: this.base + "/" } });
    const html = this._body(page);
    const csrf = /<meta\s+name="csrf-token"\s+content="([^"]+)"/.exec(html);
    const listed = /sourcesUrl:\s*'([^']+)'/.exec(html);
    if (!csrf || !listed) throw new Error("no player on the episode page");
    const session = {
      cookie: this._cookieHeader(page),
      csrf: csrf[1],
      referer: watchUrl,
    };
    const manifest = this._json(await this._request(this._absolute(this._unescapeBody(listed[1])), {
      method: "POST",
      headers: this._sessionHeaders(session),
    }));

    // { players: { FHD: [{ token, label, version, lang }], HD: […], SD: […] } }
    const players = [];
    const groups = (manifest && manifest.players) || {};
    for (const quality of ["4K", "FHD", "HD", "SD"]) {
      for (const player of Array.isArray(groups[quality]) ? groups[quality] : []) {
        if (!player || typeof player.token !== "string" || !/^[\w-]+$/.test(player.token)) continue;
        if (player.version && player.version !== "sub") continue;
        players.push({ token: player.token, host: String(player.label || "").toLowerCase(), quality: quality });
      }
    }
    return { session: session, players: players };
  }

  // The player address behind a token: the site first releases the token for the session, then
  // its gate (loaded as an iframe) redirects to the host's embed page. Releases go one at a time.
  _embedUrl(token, session) {
    const turn = witanimeShared.releases.then(() => this._release(token, session));
    witanimeShared.releases = turn.catch(function () {});
    return turn;
  }

  async _release(token, session) {
    const released = await this._request(this.base + "/watch/stream-source/" + token, {
      method: "POST",
      headers: this._sessionHeaders(session),
    });
    this._json(released);
    const gate = await this._request(this.base + "/watch/stream-gate/" + token, {
      redirect: "manual",
      allowStatus: [301, 302, 303, 307, 308],
      headers: {
        Cookie: session.cookie,
        "Sec-Fetch-Dest": "iframe",
        "Sec-Fetch-Mode": "navigate",
        "Sec-Fetch-Site": "same-origin",
      },
    });
    const location = this._header(gate, "location");
    if (!/^https?:\/\//i.test(location)) throw new Error("the site did not hand out the player");
    return location;
  }

  _sessionHeaders(session) {
    return this._fetchHeaders({
      Accept: "application/json",
      Cookie: session.cookie,
      "X-CSRF-TOKEN": session.csrf,
      Referer: session.referer,
      Origin: this.base,
    });
  }

  // The headers a script of the site's own page sends; its JSON endpoints answer only those.
  _fetchHeaders(extra) {
    const headers = { "Sec-Fetch-Dest": "empty", "Sec-Fetch-Mode": "cors", "Sec-Fetch-Site": "same-origin" };
    for (const name of Object.keys(extra || {})) headers[name] = extra[name];
    return headers;
  }

  // The cookies a response set, as a request's Cookie header.
  _cookieHeader(response) {
    const pairs = [];
    if (response.cookies && typeof response.cookies === "object") {
      for (const name of Object.keys(response.cookies)) pairs.push(name + "=" + response.cookies[name]);
    }
    if (pairs.length === 0) {
      const raw = this._header(response, "set-cookie");
      for (const cookie of raw.split(/,\s*(?=[\w.-]+=)/)) {
        const first = cookie.split(";")[0].trim();
        if (first.indexOf("=") > 0) pairs.push(first);
      }
    }
    return pairs.join("; ");
  }

  // ---------------------------------------------------------------- video hosts

  // mp4upload.com/embed-<id>.html names its MP4 in the player setup: `src: "https://…/video.mp4"`.
  async _mp4upload(embedUrl) {
    const html = this._body(await this._request(embedUrl, { headers: { Referer: this.base + "/" } }));
    const match = /\bsrc:\s*"(https?:\/\/[^"]+\.mp4[^"]*)"/.exec(html);
    if (!match) {
      if (/File (?:was deleted|Not Found)|file you were looking for/i.test(html)) throw new Error("the mp4upload file was deleted");
      throw new Error("the mp4upload page names no video");
    }
    // The file server answers only with the player's Referer.
    return { url: match[1], type: "mp4", headers: { Referer: "https://www.mp4upload.com/" } };
  }

  // A StreamWish player (/e/<id>). HGCloud's own page is a loader that sends the viewer to one
  // of the player's mirrors, which all serve the same files.
  async _streamWish(embedUrl) {
    const id = /\/(?:e|v|f)\/([\w]+)/.exec(embedUrl);
    if (!id) throw new Error("unexpected HGCloud address");
    const pages = [embedUrl].concat(this.wishMirrors.map(function (host) { return "https://" + host + "/e/" + id[1]; }));
    let reason = null;
    for (const pageUrl of pages.slice(0, 4)) {
      try {
        const html = this._body(await this._request(pageUrl, { headers: { Referer: this.base + "/" } }));
        const script = this._unpack(html) || html;
        const origin = this._origin(pageUrl);
        const links = {};
        const re = /"(hls\d)"\s*:\s*"([^"]+)"/g;
        let match;
        while ((match = re.exec(script)) !== null) links[match[1]] = this._unescapeBody(match[2]);
        let url = links.hls2 || links.hls4 || "";
        if (!url) {
          const file = /file\s*:\s*"([^"]+\.m3u8[^"]*)"/.exec(script);
          url = file ? file[1] : "";
        }
        if (!url) {
          if (/File is no longer available|file was deleted|Not Found/i.test(html) && html.length < 20000) throw new Error("the HGCloud file was deleted");
          continue;
        }
        if (url.charAt(0) === "/") url = origin + url;
        return { url: url, type: "m3u8", headers: { Referer: origin + "/", Origin: origin } };
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    throw new Error(reason || "the HGCloud player names no video");
  }

  // soraplay.xyz/embed/<id>/ is a JW Player whose setup lists the MP4s:
  // `{"file":"https://…/….mp4","type":"video/mp4","label":"1080p (source)"}`.
  async _soraplay(embedUrl) {
    const html = this._body(await this._request(embedUrl, { headers: { Referer: this.base + "/" } }));
    const files = [];
    const re = /"file"\s*:\s*"(https?:[^"]+\.mp4[^"]*)"\s*,\s*"type"\s*:\s*"video\/mp4"\s*,\s*"label"\s*:\s*"(\d+p)?/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      files.push({ url: this._unescapeBody(match[1]), type: "mp4", quality: match[2] || "auto", headers: {} });
    }
    if (files.length === 0) throw new Error("the Soraplay page names no video");
    files.sort(function (a, b) { return (parseInt(b.quality, 10) || 0) - (parseInt(a.quality, 10) || 0); });
    return files;
  }

  // yonaplay.net/embed/<code>/ is a server picker: its API opens a session, lists the servers and
  // answers each one's address AES-GCM encrypted with the session key. Its Dotplay server names an MP4.
  async _yonaplay(embedUrl) {
    const origin = this._origin(embedUrl);
    const page = await this._request(embedUrl, { headers: { Referer: this.base + "/" } });
    const cookie = this._cookieHeader(page);
    const call = async (path, body) => this._json(await this._request(origin + "/api/" + path, {
      method: "POST",
      body: JSON.stringify(body),
      headers: { "Content-Type": "application/json", "X-Requested-With": "XMLHttpRequest", Accept: "application/json", Cookie: cookie, Referer: embedUrl, Origin: origin },
    }));
    const session = await call("init-session.php", {});
    if (!session || !session.success || typeof session.c !== "string" || typeof session.k !== "string") throw new Error("the Yonaplay page has changed");
    const listed = await call("sources.php", { code: session.c });
    const servers = [];
    for (const quality of ["4k", "fhd", "hd", "sd"]) {
      const group = listed && listed.qualities && listed.qualities[quality];
      for (const server of group && Array.isArray(group.servers) ? group.servers : []) {
        if (server && typeof server.token === "string") servers.push({ token: server.token, name: String(server.name || ""), quality: quality });
      }
    }
    const dotplay = servers.filter(function (s) { return /^dotplay$/i.test(s.name); });
    if (dotplay.length === 0) throw new Error("no Dotplay server on Yonaplay (offered: " + this._distinct(servers.map(function (s) { return s.name; })).join(", ") + ")");
    const answer = await call("api.php", { code: session.c, token: dotplay[0].token, key: session.k });
    const address = answer && answer.success && typeof answer.d === "string" ? this._gcmOpen(answer.d, session.k) : "";
    if (!/^https:\/\/[^\/]+\/embed\/\w+/.test(address)) throw new Error("Yonaplay did not hand out the player");
    // dotplay.net/embed/<code>: /api.php?code=<code> answers `video_url`, base64 of "<url>|<expiry>".
    const code = /\/embed\/(\w+)/.exec(address);
    const video = this._json(await this._request(this._origin(address) + "/api.php?code=" + code[1], {
      headers: { Accept: "application/json", Referer: address },
    }));
    let url = "";
    try {
      url = String(atob(String(video && video.video_url))).split("|")[0];
    } catch (error) {
      url = "";
    }
    if (!/^https?:\/\//.test(url)) throw new Error("the Dotplay page names no video");
    return { url: url, type: "mp4", quality: { "4k": "2160p", fhd: "1080p", hd: "720p", sd: "480p" }[dotplay[0].quality], headers: {} };
  }

  // base64(iv[12] | tag[16] | ciphertext), AES-256-GCM with SHA-256(key) as the key. GCM decryption is
  // AES-CTR from counter 2; shortcut: the tag is not checked (a wrong key fails the address check).
  _gcmOpen(data, key) {
    const bytes = function (text) {
      const binary = atob(String(text).replace(/\s+/g, ""));
      return Uint8Array.from(binary, function (c) { return c.charCodeAt(0); });
    };
    const raw = bytes(data);
    if (raw.length <= 28) return "";
    const iv = raw.subarray(0, 12);
    const body = raw.subarray(28);
    const aesKey = bytes(CryptoJS.SHA256(key).toString(CryptoJS.enc.Base64));
    const counters = new Uint8Array(Math.ceil(body.length / 16) * 16);
    for (let i = 0; i * 16 < counters.length; i += 1) {
      counters.set(iv, i * 16);
      const count = i + 2;
      counters.set([(count >>> 24) & 255, (count >>> 16) & 255, (count >>> 8) & 255, count & 255], i * 16 + 12);
    }
    const stream = bytes(CryptoJS.AES.encrypt(counters, aesKey, { mode: CryptoJS.mode.ECB, padding: CryptoJS.pad.NoPadding }).toString(CryptoJS.enc.Base64));
    let text = "";
    for (let i = 0; i < body.length; i += 1) text += String.fromCharCode(body[i] ^ stream[i]);
    return CryptoJS.enc.Utf8.stringify(CryptoJS.enc.Latin1.parse(text));
  }

  // videa.hu/player?v=<id>: the player's XML (RC4-encrypted, base64) lists MP4 files that
  // answer with the hash and expiry it names. The key is derived from the page's `_xt` nonce,
  // a seed of ours and a header of the XML answer (the scheme yt-dlp's Videa extractor uses).
  async _videa(embedUrl) {
    const id = /[?&]v=([\w]+)/.exec(embedUrl);
    if (!id) throw new Error("unexpected Videa address");
    const playerUrl = "https://videa.hu/player?v=" + id[1];
    const html = this._body(await this._request(playerUrl, { headers: { Referer: this.base + "/" } }));
    const nonce = /_xt\s*=\s*"([^"]{64})"/.exec(html);
    if (!nonce) throw new Error("the Videa page has changed");
    const secret = "xHb0ZvME5q8CBcoQi6AngerDu3FGO9fkUlwPmLVY_RTzj2hJIS4NasXWKy1td7p";
    const head = nonce[1].slice(0, 32);
    const tail = nonce[1].slice(32);
    let derived = "";
    for (let i = 0; i < 32; i += 1) {
      const index = i - (secret.indexOf(head.charAt(i)) - 31);
      derived += tail.charAt(index < 0 ? index + tail.length : index);
    }
    const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    let seed = "";
    for (let i = 0; i < 8; i += 1) seed += letters.charAt(Math.floor(Math.random() * letters.length));

    const answer = await this._request("https://videa.hu/player/xml?v=" + id[1] + "&_s=" + seed + "&_t=" + derived.slice(0, 16), {
      headers: { Referer: playerUrl },
    });
    let xml = answer.text;
    if (xml.indexOf("<?xml") !== 0) {
      const key = derived.slice(16) + seed + this._header(answer, "x-videa-xs");
      let data;
      try {
        data = String(atob(xml.replace(/\s+/g, "")));
      } catch (error) {
        throw new Error("Videa sent unreadable data");
      }
      xml = this._rc4(data, key);
    }
    if (xml.indexOf("<videa_video") < 0) throw new Error("Videa sent unreadable data");
    if (/<error\b/.test(xml) && xml.indexOf("<video_source") < 0) throw new Error("the Videa video is not available");

    const files = [];
    const re = /<video_source\b([^>]*)>([^<]+)<\/video_source>/g;
    let match;
    while ((match = re.exec(xml)) !== null) {
      const name = /\bname="([^"]+)"/.exec(match[1]);
      const mime = /\bmimetype="([^"]+)"/.exec(match[1]);
      const expiry = /\bexp="(\d+)"/.exec(match[1]);
      if (!name || (mime && mime[1] !== "video/mp4")) continue;
      const hash = new RegExp("<hash_value_" + name[1].replace(/[^\w]/g, "") + ">([^<]+)<").exec(xml);
      let url = this._absolute(this._unescapeBody(match[2].trim()));
      if (hash && expiry) url += (url.indexOf("?") < 0 ? "?" : "&") + "md5=" + encodeURIComponent(hash[1]) + "&expires=" + expiry[1];
      files.push({ url: url, type: "mp4", quality: /^\d+p$/.test(name[1]) ? name[1] : "auto", headers: {} });
    }
    if (files.length === 0) throw new Error("the Videa video has no MP4 file");
    files.sort(function (a, b) { return (parseInt(b.quality, 10) || 0) - (parseInt(a.quality, 10) || 0); });
    return files;
  }

  // RC4 of a byte string (each char one byte); answers a byte string.
  _rc4(data, key) {
    const state = [];
    for (let i = 0; i < 256; i += 1) state[i] = i;
    let j = 0;
    for (let i = 0; i < 256; i += 1) {
      j = (j + state[i] + key.charCodeAt(i % key.length)) % 256;
      const swap = state[i];
      state[i] = state[j];
      state[j] = swap;
    }
    let out = "";
    let i = 0;
    j = 0;
    for (let k = 0; k < data.length; k += 1) {
      i = (i + 1) % 256;
      j = (j + state[i]) % 256;
      const swap = state[i];
      state[i] = state[j];
      state[j] = swap;
      out += String.fromCharCode(data.charCodeAt(k) ^ state[(state[i] + state[j]) % 256]);
    }
    return out;
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // One request; answers { status, text, response }. `options`: method, body, headers, redirect,
  // allowStatus (statuses besides 2xx that are not an error).
  async _request(url, options) {
    const host = this._host(url);
    const init = { headers: (options && options.headers) || {} };
    if (options && options.method) init.method = options.method;
    if (options && options.body !== undefined) init.body = options.body;
    if (options && options.redirect) init.redirect = options.redirect;
    let response;
    let text;
    for (let attempt = 0; ; attempt += 1) {
      try {
        response = await fetch(url, init);
      } catch (error) {
        throw new Error(host + " unreachable (" + this._errorText(error) + ")");
      }
      text = String(await response.text());
      // The site answers 429 to a burst of requests even with quota left; one after a pause passes.
      if (response.status !== 429 || attempt > 0 || url.indexOf(this.base + "/") !== 0) break;
      await new Promise(function (resolve) { setTimeout(resolve, 3000); });
    }
    const allowed = (options && options.allowStatus) || [];
    if (!response.ok && allowed.indexOf(response.status) < 0) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 419) throw new Error(host + " ended the visit's session; try again");
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { status: response.status, text: text, host: host, headers: response.headers, cookies: response.cookies };
  }

  _body(answer) {
    return answer.text;
  }

  _json(answer) {
    const trimmed = answer.text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") throw new Error(answer.host + " answered with a page instead of data");
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(answer.host + " sent unreadable data");
    }
  }

  _header(answer, name) {
    const headers = answer.headers;
    if (!headers) return "";
    let value = typeof headers.get === "function" ? headers.get(name) : null;
    if (value === null || value === undefined) {
      const wanted = name.toLowerCase();
      for (const key of Object.keys(headers)) if (key.toLowerCase() === wanted) value = headers[key];
    }
    return value === null || value === undefined ? "" : String(value);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _absolute(raw) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    return this.base + (url.charAt(0) === "/" ? "" : "/") + url;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&quot;/g, '"')
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The text a `eval(function(p,a,c,k,e,d){…})` packed script expands to; "" when none.
  _unpack(body) {
    const re = /\}\s*\(\s*'((?:[^'\\]|\\[\s\S])*)'\s*,\s*(\d+)\s*,\s*(\d+)\s*,\s*'((?:[^'\\]|\\[\s\S])*)'\s*\.split\(\s*'\|'\s*\)/g;
    let out = "";
    let match;
    while ((match = re.exec(body)) !== null) {
      const payload = match[1].replace(/\\'/g, "'").replace(/\\\\/g, "\\");
      const radix = parseInt(match[2], 10);
      const words = match[4].split("|");
      const digits = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const value = function (token) {
        let n = 0;
        for (let i = 0; i < token.length; i += 1) {
          const d = digits.indexOf(token.charAt(i));
          if (d < 0 || d >= radix) return -1;
          n = n * radix + d;
        }
        return n;
      };
      out += payload.replace(/\b\w+\b/g, function (token) {
        const n = value(token);
        return n >= 0 && n < words.length && words[n] ? words[n] : token;
      }) + "\n";
    }
    return out;
  }
}

// Nonton Anime ID (nontonanimeid.my.id): Indonesian subtitles (burnt in) as MP4 files from the
// site's own file server (one file per quality) and from Blogger.

class Provider {
  constructor() {
    this.base = "https://nontonanimeid.my.id";
    this.apiHeaders = { Referer: this.base + "/" };
  }

  getSettings() {
    return {
      episodeServers: ["Animeverse", "Blogger"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // The site carries Indonesian-subtitled releases only.
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const results = [];
    for (const query of queries) {
      const html = await this._page(this.base + "/?s=" + encodeURIComponent(query), this.base + "/");
      // One card: <article class="bs" …> <a href="https://…/anime/slug/" … title="Title" class="tip">
      // … <div class="typez TV">TV</div>
      const cards = html.split('<article class="bs"').slice(1);
      for (const card of cards) {
        const link = /<a\s+href="https:\/\/[^"\/]+\/anime\/([^"\/]+)\/"[^>]*\btitle="([^"]*)"/.exec(card);
        if (!link) continue;
        let slug = link[1];
        try {
          slug = decodeURIComponent(slug);
        } catch (error) {
          continue;
        }
        if (!/^[\w-]+$/.test(slug) || results.some(function (r) { return r.id === slug; })) continue;
        const title = this._plain(link[2]);
        if (!title) continue;
        const type = /class="typez\s+([^"]+)"/.exec(card);
        results.push({
          id: slug,
          title: title,
          url: this.base + "/anime/" + slug + "/",
          subOrDub: "sub",
          format: type && /movie/i.test(type[1]) ? "MOVIE" : undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const slug = String(id);
    if (!/^[\w-]+$/.test(slug)) throw new Error("invalid anime id '" + id + "'");

    const html = await this._page(this.base + "/anime/" + slug + "/", this.base + "/");
    // One entry: <li data-index="0"> <a href="https://…/slug-episode-10/"> <div class="epl-num">10</div>
    // <div class="epl-title">…</div>
    const re = /<li\s+data-index="\d+"[^>]*>\s*<a\s+href="https:\/\/[^"\/]+\/([^"\/]+)\/"[^>]*>\s*<div class="epl-num">([^<]*)<\/div>\s*<div class="epl-title">([^<]*)<\/div>/g;
    const episodes = [];
    const seen = {};
    let match;
    while ((match = re.exec(html)) !== null) {
      let entry = match[1];
      try {
        entry = decodeURIComponent(entry);
      } catch (error) {
        continue;
      }
      const label = this._plain(match[2]);
      const numbered = /^(\d+(?:\.\d+)?)/.exec(label);
      // A film is listed once, as "Movie".
      const number = numbered ? Number(numbered[1]) : /movie|film/i.test(label) ? 1 : null;
      if (number === null || seen[number]) continue;
      seen[number] = true;
      episodes.push({
        id: match[1],
        number: number,
        url: this.base + "/" + match[1] + "/",
        title: this._plain(match[3]) || "Episode " + number,
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const entry = String((episode && episode.id) || "");
    if (!/^[\w%-]+$/.test(entry)) throw new Error("invalid episode id '" + entry + "'");
    const wanted = String(server || "default").toLowerCase();
    if (wanted !== "default" && wanted !== "animeverse" && wanted !== "blogger") throw new Error("unknown server '" + server + "'");

    const watchUrl = this.base + "/" + entry + "/";
    const html = await this._page(watchUrl, this.base + "/");
    // The mirrors: <select class="mirror"> <option value="<base64 of an <iframe src=…> tag>">Server 720p</option>
    const players = [];
    const re = /<option\s+value="([A-Za-z0-9+\/=]{16,})"[^>]*>([\s\S]*?)<\/option>/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      let tag = "";
      try {
        tag = String(atob(match[1]));
      } catch (error) {
        continue;
      }
      const src = /\bsrc\s*=\s*["']([^"']+)["']/i.exec(tag);
      if (src) players.push({ url: this._unescapeBody(src[1]).replace(/^\/\//, "https://"), label: this._plain(match[2]) });
    }
    if (players.length === 0) throw new Error("the site has no player for this episode");

    const files = players.filter(function (p) { return /^https:\/\/[^\/]*animeverse\.[a-z]+\/.+\.mp4(?:[?#]|$)/i.test(p.url); });
    const hosted = players.filter(function (p) { return /^https:\/\/[^\/]*blogger\.com\/video\.g\?/.test(p.url); });
    if (files.length === 0 && hosted.length === 0) {
      const self = this;
      const hosts = this._distinct(players.map(function (p) { return self._host(p.url); }));
      throw new Error("no supported player for this episode (offered: " + hosts.join(", ") + ")");
    }

    if ((wanted === "default" || wanted === "animeverse") && files.length > 0) {
      const videoSources = [];
      for (const file of files) {
        const quality = /(\d{3,4})p/i.exec(file.label);
        const named = quality ? quality[1] + "p" : "auto";
        if (videoSources.some(function (v) { return v.url === file.url || v.quality === named; })) continue;
        videoSources.push({ url: file.url, type: "mp4", quality: named, label: "Indonesian hard sub", subtitles: [] });
      }
      videoSources.sort(function (a, b) { return (parseInt(b.quality, 10) || 0) - (parseInt(a.quality, 10) || 0); });
      return { server: "Animeverse", headers: {}, videoSources: videoSources };
    }
    if (wanted === "animeverse") throw new Error("no Animeverse player for this episode");
    if (hosted.length === 0) throw new Error("no Blogger player for this episode");

    let reason = null;
    const videoSources = [];
    for (const player of hosted.slice(0, 3)) {
      try {
        for (const file of await this._blogger(player.url, watchUrl)) {
          if (videoSources.some(function (v) { return v.quality === file.quality; })) continue;
          videoSources.push({ url: file.url, type: "mp4", quality: file.quality, label: "Indonesian hard sub", subtitles: [] });
        }
      } catch (error) {
        reason = reason || this._errorText(error);
      }
    }
    if (videoSources.length === 0) throw new Error(reason || "no playable source for this episode");
    videoSources.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return { server: "Blogger", headers: {}, videoSources: videoSources };
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // A JSON answer of the site's API. `init` may carry `method`, `body` and extra `headers`.
  async _api(url, init) {
    const host = this._host(url);
    const headers = { Accept: "application/json" };
    for (const name of Object.keys(this.apiHeaders || {})) headers[name] = this.apiHeaders[name];
    for (const name of Object.keys((init && init.headers) || {})) headers[name] = init.headers[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/json";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    const trimmed = text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") {
      throw new Error(this._looksLikeChallenge(trimmed) ? "blocked by the site's bot protection" : host + " answered with a page instead of data");
    }
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(host + " sent unreadable data");
    }
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // A page of a site as text. `referer` is a URL, or an object of request headers.
  async _page(url, referer, init) {
    const host = this._host(url);
    const headers = {};
    if (typeof referer === "string" && referer) headers.Referer = referer;
    else if (referer && typeof referer === "object") for (const name of Object.keys(referer)) headers[name] = referer[name];
    const options = { headers: headers };
    if (init && init.method) {
      options.method = init.method;
      options.body = init.body;
      headers["Content-Type"] = init.contentType || "application/x-www-form-urlencoded; charset=UTF-8";
    }
    let response;
    try {
      response = await fetch(url, options);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    if (!response.ok) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return text;
  }

  // Visible text of a piece of markup.
  _plain(html) {
    return this._unescapeBody(String(html).replace(/<[^>]*>/g, " ")).replace(/&nbsp;|&#160;/g, " ").replace(/\s+/g, " ").trim();
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&#x([0-9a-fA-F]{2,4});/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }

  // The value of an attribute in one tag's text.
  _attr(tag, name) {
    const match = new RegExp("[\\s\"']" + name + "\\s*=\\s*(?:\"([^\"]*)\"|'([^']*)'|([^\\s>]+))", "i").exec(" " + tag);
    return match ? this._unescapeBody(match[1] !== undefined ? match[1] : match[2] !== undefined ? match[2] : match[3]).trim() : "";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  // ---------------------------------------------------------------- video hosts

  // A Blogger video (blogger.com/video.g?token=…): its MP4 files, best first, as
  // [{ url, quality }]. The page names them itself or through the player's data request.
  async _blogger(url, referer) {
    const page = await this._page(url, referer);
    const found = [];
    const add = function (address, itag) {
      const quality = { 18: "360p", 22: "720p", 37: "1080p", 59: "480p" }[itag];
      if (!quality || !/^https:\/\//.test(address) || found.some(function (f) { return f.quality === quality; })) return;
      found.push({ url: address, quality: quality });
    };

    const listed = /"streams":\[([\s\S]*?)\]/.exec(page);
    if (listed && page.indexOf("errorContainer") < 0) {
      const re = /"play_url":"([^"]+)"[^}]*?"format_id":(\d+)/g;
      let match;
      while ((match = re.exec(listed[1])) !== null) add(this._unescapeBody(match[1]), parseInt(match[2], 10));
    }
    if (found.length === 0) {
      const token = /[?&]token=([^&#]+)/.exec(url);
      const session = /"FdrFJe":"([^"]+)"/.exec(page);
      const build = /"cfb2h":"([^"]+)"/.exec(page);
      if (!token || !session || !build) throw new Error("the Blogger video page has changed");
      const origin = this._origin(url);
      const request = JSON.stringify([[["WcwnYd", JSON.stringify([token[1], "", 0]), null, "generic"]]]);
      const answer = await this._page(
        origin + "/_/BloggerVideoPlayerUi/data/batchexecute?rpcids=WcwnYd&source-path=%2Fvideo.g&f.sid=" + encodeURIComponent(session[1]) +
          "&bl=" + encodeURIComponent(build[1]) + "&hl=en-US&_reqid=" + (Math.floor(Date.now() / 1000) % 86400) + "&rt=c",
        { Referer: origin + "/", "x-same-domain": "1" },
        { method: "POST", body: "f.req=" + encodeURIComponent(request) + "&", contentType: "application/x-www-form-urlencoded;charset=UTF-8" }
      );
      for (const line of answer.split("\n")) {
        if (line.indexOf('[["wrb.fr"') !== 0) continue;
        let streams = null;
        try {
          streams = JSON.parse(JSON.parse(line)[0][2])[2];
        } catch (error) {
          streams = null;
        }
        for (const stream of Array.isArray(streams) ? streams : []) {
          if (Array.isArray(stream) && typeof stream[0] === "string" && Array.isArray(stream[1])) add(stream[0], stream[1][0]);
        }
      }
    }
    if (found.length === 0) throw new Error("the Blogger video is not available");
    found.sort(function (a, b) { return parseInt(b.quality, 10) - parseInt(a.quality, 10); });
    return found;
  }
}

// AnimeTR (animetr.co): Turkish subtitles (burnt in) by the site's fansub, played from the video
// hosts it embeds: Vidmoly, Rumble and Dailymotion (HLS). The site removed many older episodes
// for copyright reasons; their pages still list players that no longer answer.

class Provider {
  constructor() {
    this.base = "https://animetr.co";
  }

  getSettings() {
    return {
      episodeServers: ["Vidmoly", "Rumble", "Dailymotion"],
      supportsDub: false,
    };
  }

  // ---------------------------------------------------------------- interface

  async search(opts) {
    // The site carries Turkish-subtitled releases only.
    if (opts && opts.dub) return [];
    const queries = this._queries(opts);
    if (queries.length === 0) throw new Error("no title to search for");

    const results = [];
    for (const query of queries) {
      const html = this._body(await this._request(this.base + "/seriler?title=" + encodeURIComponent(query), { headers: { Referer: this.base + "/" } }));
      // One card: <a href="https://animetr.co/seri/slug" class="anime-card" data-category="anime" aria-label="Title">
      const re = /<a\s+href="https:\/\/[^"\/]+\/seri\/([\w-]+)"\s+class="anime-card"([^>]*)>/g;
      let match;
      while ((match = re.exec(html)) !== null) {
        const label = /aria-label="([^"]*)"/.exec(match[2]);
        const title = label ? this._text(this._unescapeBody(label[1])) : "";
        if (!title || results.some(function (r) { return r.id === match[1]; })) continue;
        const category = /data-category="([^"]*)"/.exec(match[2]);
        results.push({
          id: match[1],
          title: title,
          url: this.base + "/seri/" + match[1],
          subOrDub: "sub",
          format: category && /film|movie/i.test(category[1]) ? "MOVIE" : undefined,
        });
      }
      if (results.length > 0) break;
    }
    return results;
  }

  async findEpisodes(id) {
    const slug = String(id);
    if (!/^[\w-]+$/.test(slug)) throw new Error("invalid anime id '" + id + "'");

    const html = this._body(await this._request(this.base + "/seri/" + slug, { headers: { Referer: this.base + "/" } }));
    // One entry: <a href="/izle/slug/bolum-12">; a half episode is "bolum-1-5".
    const re = new RegExp('href="(?:https://[^"/]+)?/izle/' + slug + '/(bolum-(\\d+)(?:-(\\d))?)"', "g");
    const episodes = [];
    const seen = {};
    let match;
    while ((match = re.exec(html)) !== null) {
      const number = Number(match[2] + (match[3] ? "." + match[3] : ""));
      if (seen[number]) continue;
      seen[number] = true;
      episodes.push({
        id: slug + "|" + match[1],
        number: number,
        url: this.base + "/izle/" + slug + "/" + match[1],
        title: "Bölüm " + number,
      });
    }
    episodes.sort(function (a, b) { return a.number - b.number; });
    if (episodes.length === 0) throw new Error("no episodes listed");
    return episodes;
  }

  async findEpisodeServer(episode, server) {
    const parts = String((episode && episode.id) || "").split("|");
    if (!/^[\w-]+$/.test(parts[0] || "") || !/^bolum-[\w-]+$/.test(parts[1] || "")) throw new Error("invalid episode id '" + (episode && episode.id) + "'");
    const wanted = String(server || "default").toLowerCase();
    const names = this.getSettings().episodeServers;
    if (wanted !== "default" && !names.some(function (name) { return name.toLowerCase() === wanted; })) throw new Error("unknown server '" + server + "'");

    const watchUrl = this.base + "/izle/" + parts[0] + "/" + parts[1];
    const html = this._body(await this._request(watchUrl, { headers: { Referer: this.base + "/seri/" + parts[0] } }));
    // One player: <div class="player-frame" id="player_0_3" …> … <iframe data-src="https://…">
    const players = [];
    const re = /<div\s+class="player-frame"[\s\S]*?<iframe\b[^>]*?\bdata-src="([^"]+)"/g;
    let match;
    while ((match = re.exec(html)) !== null) {
      const url = this._unescapeBody(match[1]);
      if (players.indexOf(url) < 0) players.push(url);
    }
    if (players.length === 0) throw new Error("the site has no player for this episode");

    const hosts = {
      vidmoly: function (url) { return /^https:\/\/(?:www\.)?vidmoly\.[a-z]+\/(?:embed-|w\/)/i.test(url); },
      rumble: function (url) { return /^https:\/\/rumble\.com\/embed\//i.test(url); },
      dailymotion: function (url) { return /^https:\/\/(?:www\.)?dailymotion\.com\/embed\/video\//i.test(url); },
    };
    const order = wanted === "default" ? ["vidmoly", "rumble", "dailymotion"] : [wanted];
    if (!players.some(function (url) { return order.some(function (host) { return hosts[host](url); }); })) {
      const self = this;
      const offered = this._distinct(players.map(function (url) { return self._host(url); }));
      throw new Error(wanted === "default"
        ? "no supported player for this episode (offered: " + offered.join(", ") + ")"
        : "no " + server + " player for this episode");
    }

    let reason = null;
    for (const host of order) {
      for (const url of players.filter(hosts[host]).slice(0, 3)) {
        try {
          const found = host === "vidmoly" ? await this._vidmoly(url)
            : host === "rumble" ? await this._rumble(url)
            : await this._dailymotion(url);
          return {
            server: { vidmoly: "Vidmoly", rumble: "Rumble", dailymotion: "Dailymotion" }[host],
            headers: found.headers,
            videoSources: [{ url: found.url, type: "m3u8", quality: "auto", label: "Turkish hard sub", subtitles: [] }],
          };
        } catch (error) {
          reason = reason || this._errorText(error);
        }
      }
    }
    throw new Error(reason || "no playable source for this episode");
  }

  // ---------------------------------------------------------------- video hosts

  // vidmoly.biz/embed-<id>.html names its playlist in the player setup: `file: 'https://…/master.m3u8'`.
  async _vidmoly(embedUrl) {
    const html = this._body(await this._request(embedUrl, { headers: { Referer: this.base + "/" } }));
    const match = /file\s*:\s*['"](https?:\/\/[^'"]+\.m3u8[^'"]*)['"]/.exec(html);
    if (!match) {
      if (/Video is processing/i.test(html)) throw new Error("Vidmoly is still processing the video");
      throw new Error(/deleted|not found|removed/i.test(html) ? "the video was removed from Vidmoly" : "the Vidmoly page names no video");
    }
    const origin = this._origin(embedUrl);
    return { url: this._unescapeBody(match[1]), headers: { Referer: origin + "/", Origin: origin } };
  }

  // rumble.com/embed/<id>/: the player's own JSON names the video's HLS playlist.
  async _rumble(embedUrl) {
    const id = /\/embed\/([\w]+)/.exec(embedUrl);
    if (!id) throw new Error("unexpected Rumble address");
    const data = this._json(await this._request("https://rumble.com/embedJS/u3/?request=video&ver=2&v=" + id[1], {
      headers: { Referer: embedUrl, Accept: "application/json" },
    }));
    const listed = (data && data.u && data.u.hls) || (data && data.ua && data.ua.hls && data.ua.hls.auto) || null;
    const url = listed && typeof listed.url === "string" ? listed.url : "";
    if (!/^https:\/\//.test(url)) throw new Error("the Rumble video is not available");
    return { url: url, headers: { Referer: "https://rumble.com/" } };
  }

  // dailymotion.com/embed/video/<id>: the player's metadata names an HLS playlist that answers
  // only with the visitor cookie (`v1st`) the metadata request set, and the player's origin.
  async _dailymotion(embedUrl) {
    const id = /\/video\/([\w]+)/.exec(embedUrl);
    if (!id) throw new Error("unexpected Dailymotion address");
    const answer = await this._request("https://www.dailymotion.com/player/metadata/video/" + id[1], {
      headers: { Referer: embedUrl, Accept: "application/json" },
      allowStatus: [404, 403, 410],
    });
    const data = this._json(answer);
    if (data && data.error) throw new Error("the Dailymotion video is not available");
    const auto = data && data.qualities && Array.isArray(data.qualities.auto) ? data.qualities.auto : [];
    const url = auto[0] && typeof auto[0].url === "string" ? auto[0].url : "";
    if (!/^https:\/\//.test(url)) throw new Error("the Dailymotion video names no stream");
    const headers = { Referer: "https://www.dailymotion.com/", Origin: "https://www.dailymotion.com" };
    const cookie = this._cookieHeader(answer);
    if (cookie) headers.Cookie = cookie;
    return { url: url, headers: headers };
  }

  // The cookies a response set, as a request's Cookie header.
  _cookieHeader(response) {
    const pairs = [];
    if (response.cookies && typeof response.cookies === "object") {
      for (const name of Object.keys(response.cookies)) pairs.push(name + "=" + response.cookies[name]);
    }
    if (pairs.length === 0) {
      const raw = this._header(response, "set-cookie");
      for (const cookie of raw.split(/,\s*(?=[\w.-]+=)/)) {
        const first = cookie.split(";")[0].trim();
        if (first.indexOf("=") > 0) pairs.push(first);
      }
    }
    return pairs.join("; ");
  }

  // ---------------------------------------------------------------- shared helpers

  _queries(opts) {
    const media = (opts && opts.media) || {};
    const queries = [];
    for (const title of [opts && opts.query, media.romajiTitle, media.englishTitle]) {
      if (typeof title === "string" && title.trim() && queries.indexOf(title.trim()) < 0) queries.push(title.trim());
    }
    return queries.slice(0, 2);
  }

  // One request; answers { status, text, response }. `options`: method, body, headers, redirect,
  // allowStatus (statuses besides 2xx that are not an error).
  async _request(url, options) {
    const host = this._host(url);
    const init = { headers: (options && options.headers) || {} };
    if (options && options.method) init.method = options.method;
    if (options && options.body !== undefined) init.body = options.body;
    if (options && options.redirect) init.redirect = options.redirect;
    let response;
    try {
      response = await fetch(url, init);
    } catch (error) {
      throw new Error(host + " unreachable (" + this._errorText(error) + ")");
    }
    const text = String(await response.text());
    const allowed = (options && options.allowStatus) || [];
    if (!response.ok && allowed.indexOf(response.status) < 0) {
      if (this._looksLikeChallenge(text)) throw new Error("blocked by the site's bot protection");
      if (response.status === 404) throw new Error("not found on " + host);
      if (response.status === 419) throw new Error(host + " ended the visit's session; try again");
      if (response.status === 429) throw new Error("rate limited by " + host);
      throw new Error("HTTP " + response.status + " from " + host);
    }
    return { status: response.status, text: text, host: host, headers: response.headers, cookies: response.cookies };
  }

  _body(answer) {
    return answer.text;
  }

  _json(answer) {
    const trimmed = answer.text.replace(/^\s+/, "");
    if (trimmed.charAt(0) === "<") throw new Error(answer.host + " answered with a page instead of data");
    try {
      return JSON.parse(trimmed);
    } catch (error) {
      throw new Error(answer.host + " sent unreadable data");
    }
  }

  _header(answer, name) {
    const headers = answer.headers;
    if (!headers) return "";
    let value = typeof headers.get === "function" ? headers.get(name) : null;
    if (value === null || value === undefined) {
      const wanted = name.toLowerCase();
      for (const key of Object.keys(headers)) if (key.toLowerCase() === wanted) value = headers[key];
    }
    return value === null || value === undefined ? "" : String(value);
  }

  _looksLikeChallenge(body) {
    const markers = ["Just a moment", "cf-chl", "challenge-platform/h/", "Attention Required! | Cloudflare",
      "Sorry, you have been blocked", "DDoS-Guard", "Checking your browser"];
    return markers.some(function (marker) { return body.indexOf(marker) >= 0; });
  }

  _text(value) {
    return typeof value === "string" ? value.replace(/\s+/g, " ").trim() : "";
  }

  _distinct(values) {
    const kept = [];
    for (const value of values) {
      if (value && kept.indexOf(value) < 0) kept.push(value);
    }
    return kept;
  }

  _host(url) {
    const match = /^[a-z][a-z0-9+.-]*:\/\/([^\/?#:]+)/i.exec(String(url));
    return match ? match[1].toLowerCase() : "unknown host";
  }

  _origin(url) {
    const match = /^(https?:\/\/[^\/?#]+)/i.exec(String(url));
    return match ? match[1] : "";
  }

  _absolute(raw) {
    const url = String(raw).trim();
    if (url.indexOf("//") === 0) return "https:" + url;
    if (/^https?:\/\//i.test(url)) return url;
    return this.base + (url.charAt(0) === "/" ? "" : "/") + url;
  }

  _errorText(error) {
    const text = error && error.message ? String(error.message) : String(error);
    return text.length > 140 ? text.slice(0, 140) : text;
  }

  // Undoes the escaping scraped bodies wrap URLs in: `\/`, `\uXXXX` and common HTML entities.
  _unescapeBody(body) {
    return String(body)
      .replace(/\\+u([0-9a-fA-F]{4})/g, function (whole, hex) { return String.fromCharCode(parseInt(hex, 16)); })
      .replace(/\\+\//g, "/")
      .replace(/&#(\d{2,5});/g, function (whole, code) { return String.fromCharCode(parseInt(code, 10)); })
      .replace(/&quot;/g, '"')
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&amp;/g, "&");
  }
}
